    try std.testing.expect(hl < session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[hl] == .group_header);
    // ★ 하이라이트 = 비고정 리전 마커(UG, tab 3)의 헤더 — 삽입 위치와 정합. 옛 버그면 전역 첫 헤더(고정 PG, slot 0)를 반환.
    try std.testing.expectEqual(@as(usize, 3), session.sidebar_rows.items[hl].group_header.tab);
    try std.testing.expect(hl != 0); // 고정 리전 헤더(hPG)가 아니다
}

test "그룹핀 리뷰 #6: accent 막대 current_group_color가 핀 경계에서 리셋(고정 색 그룹 뒤 top카드 무색, §12)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]

    const red: u32 = 0xFF0000;
    const blue: u32 = 0x0000FF;
    // 고정 색 그룹 PG=[t0(RED),t1](pin) + 비고정 top카드 t2(무색) + 비고정 색 그룹 UG=[t3(BLUE),t4].
    session.tabs.items[0].group_start = try allocator.dupe(u8, "PG");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].group_color = red;
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true;
    session.tabs.items[3].group_start = try allocator.dupe(u8, "UG");
    session.tabs.items[3].group_depth = 1;
    session.tabs.items[3].group_color = blue;
    session.rebuildSidebar() catch {};

    // 표시 rows: [hPG, c t0, c t1, c t2, hUG, c t3, c t4]. 좌측 accent 막대(layer0·x=gap·w=bar_w) 색을 센다.
    const tk = session.buildChromeTokens();
    const gap_f: f32 = @floatFromInt(tk.space.card_gap_px);
    const bar_w = tk.space.accent_bar_width_px;
    try std.testing.expect(bar_w > 0); // rich accent 막대 존재(전제)
    const red_word = packStraightRgbU32(red, 0xFF);
    var red_accents: usize = 0;
    for (session.gpu_quads.items) |q| {
        if (q.layer == 0 and q.fill_color0 == red_word and q.w == @as(f32, @floatFromInt(bar_w)) and q.x == gap_f) red_accents += 1;
    }
    // ★ RED accent = PG 마커 카드+멤버 카드 = 2개뿐. 옛 버그면 비고정 top카드 t2가 색을 상속해 3개.
    try std.testing.expectEqual(@as(usize, 2), red_accents);
}

test "그룹핀 리뷰 #7: 드래그 중 sidebarMaxScroll이 preview_rows(더 긴 force-emit) 기준(§9 SG8 스크롤 정합)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 순수 스크롤 math 확인 — 실제 탭/기하와 무관하게 행 리스트만 바꿔 content 높이가 렌더 도메인을 따르는지 본다.
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 40;
    session.backing_height_px = 200; // 뷰포트 = 200 - 40(헤더) = 160
    session.sidebar_width_px = 100;

    const mkCard = struct {
        fn f(tab: usize) chrome.components.sidebar.Row {
            return .{ .card = .{ .tab = tab, .label = "x", .active = false } };
        }
    }.f;
    session.sidebar_rows.clearRetainingCapacity();
    inline for (0..3) |i| try session.sidebar_rows.append(session.allocator, mkCard(i)); // 3행 = 120px <= 160 → 스크롤 없음
    session.sidebar_preview_rows.clearRetainingCapacity();
    inline for (0..6) |i| try session.sidebar_preview_rows.append(session.allocator, mkCard(i)); // 6행 = 240px > 160(force-emit)

    // 비드래그(preview=null) → sidebar_rows(짧음) 기준 → 스크롤 불필요.
    try std.testing.expectEqual(@as(u32, 0), session.sidebarMaxScroll());
    // 드래그 프리뷰 활성 → sidebarRenderRows()=preview_rows(길음) 기준 → 스크롤 가능(240-160=80).
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = .none, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    try std.testing.expectEqual(@as(u32, 80), session.sidebarMaxScroll()); // ★ 옛 버그면 sidebar_rows(3행)로 0 → 스크롤 불가
    session.sidebar_drag_preview = null; // teardown(preview_rows는 deinit이 정리)
}

test "그룹핀 리뷰 #8: 그룹 헤더 드래그 시작이 hovered_slot을 클리어(재배치 preview에 stale 호버 밴드 방지, §9 SG8)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];

    // 두 형제 그룹 A=[t0,t1], B=[t2,t3](B depth1로 오버라이드해 형제 최상위).
    session.createGroupAbsorbForTab(t0);
    session.createGroupAbsorbForTab(t2);
    t2.group_depth = 1;
    session.recomputeVisibleTabs(); // rows: [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]

    const header_h = session.sidebar_header_height_px;
    const header_row_h = session.sidebar_header_row_h_px;
    const slot_h = session.sidebar_slot_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const rowY = struct {
        fn f(s: *AppSession, row: usize, hh: u32, sh: u32, hrh: u32) f64 {
            const top = chrome.components.sidebar.rowTop(s.sidebar_rows.items, row, hh, sh, hrh, 0);
            const rh = chrome.components.sidebar.rowHeight(s.sidebar_rows.items[row], sh, hrh);
            return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
        }
    }.f;

    session.hovered_slot = 2; // stale 호버(카드 슬롯)
    session.mouse(1, x, rowY(session, 0, header_h, slot_h, header_row_h), 0, 0); // down on 헤더 A → arm(토글 후보)
    try std.testing.expect(session.sidebar_group_drag_armed);
    try std.testing.expectEqual(@as(?usize, 2), session.hovered_slot); // arm만으론 호버 유지(클릭=토글일 수 있음)

    // 그룹 B 카드(row4)로 drag → threshold 초과 → 그룹 통째 드래그 시작 → hovered_slot 클리어.
    session.mouse(2, x, rowY(session, 4, header_h, slot_h, header_row_h), 0, 0);
    try std.testing.expect(session.sidebar_group_drag_active);
    try std.testing.expectEqual(@as(?usize, null), session.hovered_slot); // ★ 드래그 시작이 stale 호버 클리어
    session.mouse(3, x, rowY(session, 4, header_h, slot_h, header_row_h), 0, 0); // up → 커밋(정리)
    try std.testing.expectEqual(@as(?usize, null), session.hovered_slot);
}

// 그룹핀 리뷰 #9: **그룹 먼저 고정 → 그 다음 독립 top카드 개별 고정**(togglePin) = 실제 사용자 경로이자 버그 지점(§12 GP1).
// togglePin의 pin 목적지가 고정 리전 **끝**(pinned_count-1)이면 새로 고정한 top카드가 고정 그룹 subtree **뒤**에 놓여
// 위치 파생(§2.1)이 그 카드를 그룹 멤버로 **흡수**했다. 목적지를 firstGroupStartInRegion(0, pinned_count)(고정 리전 첫
// 그룹 마커 **앞**)로 바꿔 `[고정 top카드][고정 그룹]` 순서를 유지한다. 기존 GP3(c)/GP4(a)는 top카드를 **먼저** pin
// 세팅 후 그룹을 고정해 이 경로를 미검증으로 남겼다. 각 단언은 옛 목적지(count-1)면 fail하도록 골랐다(수정 회귀 시 red).
test "그룹핀 리뷰 #9: 그룹 먼저 고정 → 독립 top카드 개별 고정이 고정 그룹 subtree 앞에 안착(흡수 방지, §12 GP1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]

    // 배치: 독립 top카드 둘(X1=t0·X2=t1) + 그룹 A=[t2(마커,depth1),t3,t4](멤버는 위치 파생). t0·t1은 마커 앞이라 최상위.
    session.tabs.items[2].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[2].group_depth = 1;
    const x1 = session.tabs.items[0];
    const x2 = session.tabs.items[1];
    const a_marker = session.tabs.items[2];
    const a_m1 = session.tabs.items[3];
    const a_m2 = session.tabs.items[4];

    // 현재 인덱스 파생 헬퍼(heap-pin *Tab 일치 검색 — 이동 후 위치를 다시 찾는다).
    const idxOf = struct {
        fn f(s: *AppSession, t: *Tab) usize {
            for (s.tabs.items, 0..) |it, i| if (it == t) return i;
            unreachable;
        }
    }.f;
    // projectRowsCore 투영 row(카드)를 tab 인덱스로 찾는다 — 라이브는 identity order라 card.tab = self.tabs 인덱스.
    const findCard = struct {
        fn f(s: *AppSession, tab_index: usize) chrome.components.sidebar.Row {
            for (s.sidebar_rows.items) |r| switch (r) {
                .card => |c| if (c.tab == tab_index) return r,
                .group_header => {},
            };
            unreachable;
        }
    }.f;

    // ── 1) 그룹 A를 **먼저** 통째 고정(toggleGroupPin) → 프리픽스로 안착([A마커,멤버,멤버] + 비고정 [t0,t1]) ──
    session.toggleGroupPin(a_marker);
    try std.testing.expect(a_marker.pinned and a_m1.pinned and a_m2.pinned); // 그룹째 고정(멤버 pin 동기)
    try std.testing.expect(!x1.pinned and !x2.pinned); // 독립 top카드는 아직 비고정(그룹 토글과 직교)
    // tabs = [A마커, m1, m2, t0(X1), t1(X2)] — X1은 지금 고정 그룹 subtree **뒤**(비고정 리전).
    try std.testing.expectEqual(a_marker, session.tabs.items[0]);
    try std.testing.expectEqual(x1, session.tabs.items[3]);

    // ── 2) 그룹 밖 독립 top카드 X1을 **개별** 고정(togglePin) → 고정 그룹 A **앞**으로 안착해야(흡수 방지) ──
    session.togglePin(x1);
    session.recomputeVisibleTabs();

    const x1_idx = idxOf(session, x1);
    const am_idx = idxOf(session, a_marker);

    // (a) X1이 고정 그룹 A subtree **앞**에 안착 — X1 인덱스 < A 마커 인덱스(옛 count-1이면 A subtree 뒤라 fail).
    try std.testing.expect(x1.pinned);
    try std.testing.expect(x1_idx < am_idx);
    try std.testing.expectEqual(@as(usize, 0), x1_idx); // 고정 리전 첫 자리(top카드)
    try std.testing.expectEqual(@as(usize, 1), am_idx); // A 마커는 그 뒤 = subtree 시작
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(am_idx, null, null)); // A=[1,4) — X1(0)은 밖

    // (b) X1은 그룹 소속이 아니다 — group_start 없음 + enclosing 마커 없음 + tabIsInGroup=false(흡수 안 됨).
    try std.testing.expect(x1.group_start == null);
    try std.testing.expect(session.enclosingGroupMarkerIndex(x1_idx) == null);
    try std.testing.expect(!session.tabIsInGroup(x1));

    // (c) X1 렌더 depth 0(들여쓰기 없음) — 라이브 파생·projectRowsCore 투영 둘 다. 옛 버그면 그룹 멤버라 depth 1.
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(x1_idx, null, null));
    const x1_row = findCard(session, x1_idx);
    try std.testing.expectEqual(@as(u8, 0), x1_row.card.depth);
    try std.testing.expect(!x1_row.card.pin_derived); // 개별 pin(그룹 파생 캐시 아님)

    // (d) 사이드바 카드에 📌 — 개별 최상위 pin(pin_derived=false·tab.pinned=1)이라 sidebarRowShowsPin=true(멤버면 억제됐을 것).
    try std.testing.expect(session.sidebarRowShowsPin(x1_row));

    // ── 추가: 고정 top카드가 여러 개여도 전부 그룹 **앞** 유지(고정된 것끼리는 위치만 바뀐다) ──
    session.togglePin(x2); // 두 번째 독립 top카드도 개별 고정
    session.recomputeVisibleTabs();
    const x1_idx2 = idxOf(session, x1);
    const x2_idx2 = idxOf(session, x2);
    const am_idx2 = idxOf(session, a_marker);
    try std.testing.expect(x1.pinned and x2.pinned);
    // 둘 다 A 마커 앞(그룹 흡수 없음), 서로는 위치만 정렬(X1 먼저·X2 그 뒤·그 다음 A) — tabs=[X1,X2,A마커,m1,m2].
    try std.testing.expect(x1_idx2 < am_idx2 and x2_idx2 < am_idx2);
    try std.testing.expectEqual(@as(usize, 0), x1_idx2);
    try std.testing.expectEqual(@as(usize, 1), x2_idx2);
    try std.testing.expectEqual(@as(usize, 2), am_idx2);
    // 둘 다 여전히 그룹 밖·depth 0.
    try std.testing.expect(session.enclosingGroupMarkerIndex(x1_idx2) == null);
    try std.testing.expect(session.enclosingGroupMarkerIndex(x2_idx2) == null);
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(x2_idx2, null, null));
    // 그룹 A subtree 무결(마커+멤버 통째 고정, 흡수/찢김 없음).
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(am_idx2, null, null)); // A=[2,5)
    try std.testing.expect(a_marker.pinned and a_m1.pinned and a_m2.pinned);
    // 카드 📌는 두 최상위 개별 pin(X1·X2)뿐 — 그룹 멤버/마커 카드 📌 노이즈 0(헤더 인디케이터는 별도 도메인).
    var card_pins: usize = 0;
    for (session.sidebar_rows.items) |r| switch (r) {
        .card => if (session.sidebarRowShowsPin(r)) {
            card_pins += 1;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(usize, 2), card_pins); // X1·X2만
}

/// SG8b 등가 헬퍼(docs/sidebar-groups.md §9) — simulateDrop이 낸 **가상 배치**가 **실제 move 함수 적용 후 self.tabs**와
/// 일치함을 단언한다: (1) move 전 탭 포인터·선언 depth 스냅샷, (2) simulateDrop → vl(+ self.tabs 불변 단언), (3) plan에
/// 대응하는 실제 move를 **정확히 1회**, (4) 모든 위치 i에서 `before[vl.order[i]]==tabs[i]`(같은 탭이 같은 위치에)·
/// `vl.group_depth[i]==tabs[i].group_depth`(같은 depth). 프리뷰(비커밋)와 확정(커밋)이 한 순수 코어로 수렴함을 고정한다.
/// 중간 버퍼(그룹 순열 perm/new_order 등)까지 arena가 정리하므로 leak 없음.
fn expectDropEquivalent(session: *AppSession, origin: usize, plan: AppSession.DropPlan) !void {
    const alloc = std.testing.allocator;
    const n = session.tabs.items.len;
    const before = try alloc.alloc(*Tab, n);
    defer alloc.free(before);
    const before_gd = try alloc.alloc(u8, n);
    defer alloc.free(before_gd);
    for (session.tabs.items, 0..) |t, i| {
        before[i] = t;
        before_gd[i] = t.group_depth;
    }
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const vl = try session.simulateDrop(origin, plan, arena.allocator());
    // (2) self.tabs 불변 단언 — 순서·group_depth가 그대로(비커밋).
    for (session.tabs.items, 0..) |t, i| {
        try std.testing.expectEqual(before[i], t);
        try std.testing.expectEqual(before_gd[i], t.group_depth);
    }
    // (3) 확정 경로 — plan별 실제 move 1회.
    switch (plan) {
        .none => {},
        .card => |c| _ = session.moveTab(origin, c.target_tab),
        .group_sibling => |g| _ = session.moveGroupSibling(origin, g.insert_before),
        .group_nest => |g| _ = session.moveGroupNesting(origin, g.insert_before, g.target_depth),
    }
    // (4) 등가 단언 — 같은 위치에 같은 탭·같은 depth.
    try std.testing.expectEqual(n, session.tabs.items.len);
    for (session.tabs.items, 0..) |t, i| {
        try std.testing.expectEqual(before[vl.order[i]], t);
        try std.testing.expectEqual(vl.group_depth[i], t.group_depth);
    }
}

/// §14.6 SR4 model-2 프리뷰=확정 등가(카드 경로) — simulateDrop이 낸 가상 `top_level[]`가 **실제 commitSidebarDragPreview**
/// 확정 후 self.tabs.top_level와 위치별로 일치함을 단언한다(+order·group_depth도). expectDropEquivalent(raw move)와 달리
/// **commit 경로**(top_level write 포함)를 태워, 프리뷰(가상 override)와 확정(실제 write)이 같은 게이트를 써 갈리지 않음을
/// 고정한다(카드 plan 전용 — 그룹 plan은 top_level 불변이라 expectDropEquivalent로 충분). 로컬 pin 없는 시나리오라 commit의
/// normalize/float/sweep 후처리는 no-op이라 vl와 committed가 그대로 일치한다(등가 정확성 보장).
fn expectCardDropTopLevelEquivalent(session: *AppSession, origin: usize, plan: AppSession.DropPlan) !void {
    const alloc = std.testing.allocator;
    const n = session.tabs.items.len;
    const before = try alloc.alloc(*Tab, n);
    defer alloc.free(before);
    for (session.tabs.items, 0..) |t, i| before[i] = t;
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const vl = try session.simulateDrop(origin, plan, arena.allocator());
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변(비커밋 SG8)
    // 확정 — 실제 commit 경로(moveTab + top_level write + normalize/float/sweep).
    session.sidebar_drag_preview = .{ .origin = origin, .origin_len = 1, .plan = plan, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    try std.testing.expectEqual(n, session.tabs.items.len);
    for (session.tabs.items, 0..) |t, i| {
        try std.testing.expectEqual(before[vl.order[i]], t); // 같은 위치에 같은 탭(순열 일치)
        try std.testing.expectEqual(vl.group_depth[i], t.group_depth); // 선언 depth 일치
        try std.testing.expectEqual(vl.top_level[i], t.top_level); // ★ 가상 top_level == 확정 실제 top_level(프리뷰=확정)
    }
}

// §14.6 SR4 model-2 — 카드 드래그가 top_level을 **직접 전이**한다(그룹 밖 gap=최상위 복귀 / 그룹 안=멤버 흡수). VirtualLayout.
// top_level[] 가상화로 프리뷰(가상 override)=확정(실제 write)이 같은 depth/소속을 낸다. 배치 [A(마커), a1, TOP1(top_level), X].
test "SR4(a): 카드를 그룹 뒤 top카드 옆(gap)으로 드래그 → top_level=true·depth0·enclosing null(model-2 전이)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    // [A(마커 t0,depth1), a1(t1,멤버), TOP1(t2,top_level 인터리브 top카드), X(t3, TOP1 뒤 sticky top)].
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    const top1 = session.tabs.items[2];
    const x = session.tabs.items[3];
    session.recomputeVisibleTabs();
    // 사전: X(t3)는 sticky top(밖·depth0), TOP1(t2)도 밖.
    try std.testing.expect(session.enclosingGroupMarkerIndex(3) == null);
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(3, null, null));

    // X를 TOP1 row(=그룹 뒤 gap의 top카드) 옆으로 드래그. 분류: 타겟 TOP1이 최상위 → 전이 의도 true(그룹 밖 gap).
    var top1_row: usize = 0;
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .card => |c| if (c.tab == 2) {
            top1_row = s;
        },
        .group_header => {},
    };
    try std.testing.expect(session.sidebarCardDropTopLevel(top1_row)); // 타겟 최상위 → true
    const target = session.sidebarGroupDropTargetTab(top1_row, 3).?; // TOP1 위치 = 2
    try std.testing.expectEqual(@as(usize, 2), target);
    const plan: AppSession.DropPlan = .{ .card = .{ .target_tab = target, .top_level = true } };

    // 프리뷰=확정 등가(가상 top_level == commit 후 실제).
    try expectCardDropTopLevelEquivalent(session, 3, plan);

    // 확정 결과: [A, a1, X, TOP1] — X는 그룹 뒤 최상위(top_level=true·depth0·밖), TOP1도 top카드 유지.
    var x_idx: usize = 0;
    var top1_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| {
        if (t == x) x_idx = i;
        if (t == top1) top1_idx = i;
    }
    try std.testing.expectEqual(@as(usize, 2), x_idx);
    try std.testing.expectEqual(@as(usize, 3), top1_idx);
    try std.testing.expect(x.top_level); // ★ model-2 전이 — 그룹 뒤 gap = top_level 세팅
    try std.testing.expect(session.enclosingGroupMarkerIndex(x_idx) == null); // 그룹 밖
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(x_idx, null, null)); // depth 0
    try std.testing.expect(!session.tabIsInGroup(x)); // 소속 없음(최상위)
    // 렌더 정합: X 카드 row depth 0.
    session.recomputeVisibleTabs();
    var x_depth: u8 = 255;
    for (session.sidebar_rows.items) |row| switch (row) {
        .card => |c| if (c.tab == x_idx) {
            x_depth = c.depth;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(u8, 0), x_depth);
}

test "SR4(b): 카드를 그룹 안(멤버 카드)으로 드래그 → top_level=false·멤버 흡수(기존 SG4 + stale flag clear)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    // [A(마커 t0), a1(t1,멤버), TOP1(t2,top_level), X(t3, top카드 — top_level=true로 두고 그룹 안 드롭 시 clear 확인)].
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    session.tabs.items[3].top_level = true; // X도 top카드(그룹 안 드롭이 stale flag를 clear하는지 본다)
    const x = session.tabs.items[3];
    session.recomputeVisibleTabs();

    // X를 a1(멤버) row로 드래그 → 그룹 A 안(멤버). 분류: 타겟 a1이 멤버 → 전이 의도 false(그룹 안).
    var a1_row: usize = 0;
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .card => |c| if (c.tab == 1) {
            a1_row = s;
        },
        .group_header => {},
    };
    try std.testing.expect(!session.sidebarCardDropTopLevel(a1_row)); // 타겟 멤버 → false(그룹 안)
    const target = session.sidebarGroupDropTargetTab(a1_row, 3).?;
    const plan: AppSession.DropPlan = .{ .card = .{ .target_tab = target, .top_level = false } };

    try expectCardDropTopLevelEquivalent(session, 3, plan);

    // 확정: X가 그룹 A 멤버로 흡수 — top_level=false(stale flag clear)·depth>0·enclosing=A마커.
    var x_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == x) {
        x_idx = i;
    };
    try std.testing.expect(!x.top_level); // ★ 그룹 안 드롭 = top_level clear(멤버 전이)
    try std.testing.expect(session.tabIsInGroup(x)); // 그룹 소속
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(x_idx).?); // A 마커 소속
    try std.testing.expect(session.effectiveDepthAt(x_idx, null, null) >= 1); // 멤버 depth
}

test "SR4(c): 프리뷰=확정 등가 — 전이(그룹 밖/안)·no-op·none 모두 vl.top_level == commit 후(model-2 이중경로 게이트)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    // [A(마커 t0), a1(t1), TOP1(t2,top_level), X(t3), t4(flat top)].
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    session.recomputeVisibleTabs();

    // (1) 그룹 밖 전이(X를 TOP1 옆으로, top_level=true 의도).
    try expectCardDropTopLevelEquivalent(session, 3, .{ .card = .{ .target_tab = 2, .top_level = true } });
    // (2) flat 드래그(t4를 t3 자리로, top_level 의도 false) — 그룹 마커 위 없음 리전이면 게이트가 false라 write 0(byte-identical).
    try expectCardDropTopLevelEquivalent(session, session.tabs.items.len - 1, .{ .card = .{ .target_tab = 0, .top_level = true } });
    // (3) none plan — 제자리(전이 없음).
    try expectCardDropTopLevelEquivalent(session, 1, .none);
}

test "SR4(d): 고정 리전 인터리빙 — 고정 top카드를 고정 그룹 뒤로 = pin 유지·top_level 전이·clampMoveToGroup 정합(§14.6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    // 고정 리전 [A(마커 t0,pin,group), a1(t1,pin 멤버), TOP1(t2,pin,top_level), X(t3,pin sticky top)] + 비고정 [t4].
    inline for (0..4) |i| {
        session.tabs.items[i].pinned = true;
    }
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    const x = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    session.recomputeVisibleTabs();

    // 구조 방어: 고정 리전 인터리빙 프리뷰가 **정확히 그룹 헤더 1개**(A)만 낸다(top_level 전이가 유령 헤더를 안 만듦).
    {
        var arena2 = std.heap.ArenaAllocator.init(allocator);
        defer arena2.deinit();
        try session.refreshDragPreview(3, .{ .card = .{ .target_tab = 2, .top_level = true } }, 0, arena2.allocator());
        var hdrs: usize = 0;
        for (session.sidebar_preview_rows.items) |row| switch (row) {
            .group_header => hdrs += 1,
            .card => {},
        };
        try std.testing.expectEqual(@as(usize, 1), hdrs); // ★ 프리뷰에 그룹 헤더 1개(A)만
        session.clearSidebarDragPreview();
    }

    // X(고정 top, index3)를 TOP1 옆으로 → 고정 리전 안 인터리빙(top_level 전이, pin 유지). 등가.
    try expectCardDropTopLevelEquivalent(session, 3, .{ .card = .{ .target_tab = 2, .top_level = true } });
    session.recomputeVisibleTabs();
    {
        var hdrs: usize = 0;
        for (session.sidebar_rows.items) |row| switch (row) {
            .group_header => hdrs += 1,
            .card => {},
        };
        try std.testing.expectEqual(@as(usize, 1), hdrs); // ★ 확정에도 그룹 헤더 1개(A)만
    }
    var x_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == x) {
        x_idx = i;
    };
    try std.testing.expectEqual(@as(usize, 2), x_idx); // TOP1 앞(그룹 뒤 gap) 안착
    try std.testing.expect(x.pinned); // ★ 고정 유지(비고정 리전으로 안 샘)
    try std.testing.expect(x.top_level); // 고정 top카드로 전이
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned); // 그룹 A 고정 프리픽스 유지
    try std.testing.expect(!t4.pinned); // 비고정 t4 불변
    try std.testing.expectEqual(@as(usize, 4), session.countPinnedTabs()); // 고정 4개 유지(전이가 pin 깨지 않음)

    // clampMoveToGroup 정합: X(고정, index2)를 비고정 t4(index4)로 끌어도 고정 리전 [0,4)에 clamp(비고정 못 감).
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const vl = try session.simulateDrop(2, .{ .card = .{ .target_tab = 4, .top_level = false } }, arena.allocator());
    try std.testing.expectEqual(@as(usize, 3), vl.ghost_lo); // raw 4가 아니라 고정 리전 끝(pinned_count-1=3)으로 clamp
}

test "SR4(e): VirtualLayout.top_level[] 가상화가 projectRowsCore 프리뷰 depth와 정합(프리뷰=확정 렌더 depth)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].top_level = true;
    const x = session.tabs.items[3];
    session.recomputeVisibleTabs();

    // 프리뷰: X(origin=3)를 TOP1(t2) 옆으로 — 가상 top_level[to]=true. refreshDragPreview가 preview_rows에 투영.
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    try session.refreshDragPreview(3, .{ .card = .{ .target_tab = 2, .top_level = true } }, 0, arena.allocator());
    // 프리뷰 고스트(X)가 depth 0(그룹 밖 최상위)로 투영되는가 — 가상 top_level[]이 pass1 depth를 몰았는지.
    var preview_depth: u8 = 255;
    for (session.sidebar_preview_rows.items) |row| switch (row) {
        .card => |c| if (c.tab == 3) {
            preview_depth = c.depth;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(u8, 0), preview_depth); // ★ 가상 top_level → 프리뷰 depth 0
    // self.tabs는 불변(비커밋).
    try std.testing.expect(!x.top_level);

    // 확정 후 같은 카드 depth 0 == 프리뷰 depth(프리뷰=확정 렌더 정합).
    session.sidebar_drag_preview = .{ .origin = 3, .origin_len = 1, .plan = .{ .card = .{ .target_tab = 2, .top_level = true } }, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    var x_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == x) {
        x_idx = i;
    };
    var confirmed_depth: u8 = 255;
    for (session.sidebar_rows.items) |row| switch (row) {
        .card => |c| if (c.tab == x_idx) {
            confirmed_depth = c.depth;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(preview_depth, confirmed_depth); // 프리뷰 depth == 확정 depth
    try std.testing.expect(x.top_level); // 확정에서 실제 전이
}

// §14.6 SR5 요구2 완성 — "그룹 뒤 빈 gap"(그룹 사이 top카드 없음) 첫 인터리브. row 모델엔 gap row가 없어, 마지막 멤버(또는
// 접힌 헤더)의 **아래 경계 영역** 드롭으로 그룹 밖 top카드를 만든다(sidebarCardDropAfterGroup). SR4가 기존 top카드 옆 드롭만
// 열었던 한계(빈 gap 불가)를 닫는다. 아래 경계 판정은 rowTop/rowHeight(가변 높이 chrome 단일 출처)를 공유한다.
test "SR5(a): 빈 gap 첫 인터리브 — 마지막 멤버 아래 경계 드롭 = 그룹 밖 top카드 (요구2 완성)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    // 인접 두 최상위 그룹 A=[t0(마커),t1], B=[t2(마커),t3] — 사이에 top카드 없는 "빈 gap"(옛 SR4로는 드래그 인터리브 불가).
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "B");
    session.tabs.items[2].group_depth = 1;
    // 사이드바 가변 높이 메트릭(아래 경계 판정 rowTop/rowHeight가 필요) — 헤더=20·카드=40.
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 0;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();

    // a1(t1) row + 그 row의 아래/위 경계 y(production과 같은 rowTop/rowHeight 누적).
    var a1_row: usize = 0;
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .card => |c| if (c.tab == 1) {
            a1_row = s;
        },
        .group_header => {},
    };
    const rows = session.sidebar_rows.items;
    const top = chrome.components.sidebar.rowTop(rows, a1_row, session.sidebar_header_height_px, session.sidebar_slot_height_px, session.sidebar_header_row_h_px, session.sidebar_scroll_offset_px);
    const h = chrome.components.sidebar.rowHeight(rows[a1_row], session.sidebar_slot_height_px, session.sidebar_header_row_h_px);
    const y_lower = @as(f64, @floatFromInt(top)) + @as(f64, @floatFromInt(h)) * 0.8; // 아래 40% 안 → gap 존
    const y_upper = @as(f64, @floatFromInt(top)) + @as(f64, @floatFromInt(h)) * 0.2; // 상단 → 일반 멤버 드롭

    // (1) 아래 경계: b1(from=3)을 a1 아래 경계로 → gap plan(target=groupSubtreeEnd(A)=2, top_level=true).
    const gap = session.sidebarCardDropAfterGroup(a1_row, 3, y_lower).?;
    try std.testing.expectEqual(@as(usize, 2), gap.target_tab);
    try std.testing.expect(gap.top_level);
    // (2) 상단 경계는 아래 경계 아님 → null(호출자가 기존 멤버 드롭 경로로 폴백).
    try std.testing.expect(session.sidebarCardDropAfterGroup(a1_row, 3, y_upper) == null);
    // (3) 같은 그룹 안 카드(from=1=a1 자신)는 아래 경계여도 null(그룹 안 재정렬 — gap-promote는 밖에서 끌어올 때만).
    try std.testing.expect(session.sidebarCardDropAfterGroup(a1_row, 1, y_lower) == null);

    // 확정: b1을 gap plan으로 커밋 → [A, a1, b1(top), B]. b1이 A·B 사이 top카드(첫 인터리브).
    const b1 = session.tabs.items[3];
    try expectCardDropTopLevelEquivalent(session, 3, .{ .card = .{ .target_tab = gap.target_tab, .top_level = gap.top_level } });
    var b1_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == b1) {
        b1_idx = i;
    };
    try std.testing.expectEqual(@as(usize, 2), b1_idx); // A(=[0,2)) 뒤·B(마커) 앞
    try std.testing.expect(b1.top_level); // ★ 빈 gap 첫 top카드
    try std.testing.expect(!session.tabIsInGroup(b1)); // 그룹 밖(최상위)
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(b1_idx, null, null)); // depth 0
    try std.testing.expectEqual(@as(usize, 2), session.groupSubtreeEnd(0, null, null)); // A={t0,t1} 그대로(b1 안 흡수)
    try std.testing.expect(session.tabs.items[3].group_start != null); // B 마커 유지(index3으로 밀림)
}

test "SR5(b): 접힌 그룹 헤더 아래 경계 gap drop + skip 엣지(펼친 헤더·중첩 헤더·그룹 밖 카드)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    // A=[t0(마커, 접힘),t1], B=[t2(마커),t3]. A 접힘 → 멤버 t1 숨김, 헤더만.
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[0].group_collapsed = true;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "B");
    session.tabs.items[2].group_depth = 1;
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 0;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();

    // 접힌 헤더 A row + 아래 경계 y.
    var ha_row: usize = 0;
    var hb_row: usize = 0;
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .group_header => |gh| {
            if (gh.tab == 0) ha_row = s;
            if (gh.tab == 2) hb_row = s;
        },
        .card => {},
    };
    const rows = session.sidebar_rows.items;
    const ta = chrome.components.sidebar.rowTop(rows, ha_row, session.sidebar_header_height_px, session.sidebar_slot_height_px, session.sidebar_header_row_h_px, session.sidebar_scroll_offset_px);
    const hh = chrome.components.sidebar.rowHeight(rows[ha_row], session.sidebar_slot_height_px, session.sidebar_header_row_h_px);
    const y_lower_a = @as(f64, @floatFromInt(ta)) + @as(f64, @floatFromInt(hh)) * 0.8;

    // 접힌 A 헤더 아래 경계로 b1(from=3) 드롭 → gap plan(target=groupSubtreeEnd(A)=2, top_level=true).
    const gap = session.sidebarCardDropAfterGroup(ha_row, 3, y_lower_a).?;
    try std.testing.expectEqual(@as(usize, 2), gap.target_tab);
    try std.testing.expect(gap.top_level);

    // 펼친 B 헤더 아래 경계는 null(첫 멤버와 모호 — 접힌 헤더만).
    const tb = chrome.components.sidebar.rowTop(rows, hb_row, session.sidebar_header_height_px, session.sidebar_slot_height_px, session.sidebar_header_row_h_px, session.sidebar_scroll_offset_px);
    const hb = chrome.components.sidebar.rowHeight(rows[hb_row], session.sidebar_slot_height_px, session.sidebar_header_row_h_px);
    try std.testing.expect(session.sidebarCardDropAfterGroup(hb_row, 3, @as(f64, @floatFromInt(tb)) + @as(f64, @floatFromInt(hb)) * 0.8) == null);

    // 확정: b1이 접힌 A 뒤 top카드. [A(접힘), a1(숨김), b1(top), B].
    const b1 = session.tabs.items[3];
    try expectCardDropTopLevelEquivalent(session, 3, .{ .card = .{ .target_tab = gap.target_tab, .top_level = gap.top_level } });
    var b1_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == b1) {
        b1_idx = i;
    };
    try std.testing.expectEqual(@as(usize, 2), b1_idx);
    try std.testing.expect(b1.top_level);
    try std.testing.expect(!session.tabIsInGroup(b1));
    try std.testing.expect(session.tabs.items[0].group_collapsed); // A 접힘 유지
}

test "SR5(c): promote 마커 숨김 — leaf 멤버=여기서 최상위로 분리 포함(full)·마커 카드=remove만(§14.8 결정 (a))" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    // A=[t0(마커),t1,t2] 흡수(다중 멤버 — leaf 멤버 t1·t2 존재).
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    const marker = session.tabs.items[0];
    const leaf = session.tabs.items[1];
    try std.testing.expect(marker.group_start != null);
    try std.testing.expect(session.tabIsInGroup(marker)); // 마커도 tabIsInGroup=true(자기 그룹)
    try std.testing.expect(session.tabIsInGroup(leaf));

    // leaf 멤버: remove + promote **둘 다**(full 메뉴, promote=ctx_menu_group_promote).
    session.context_menu_target = .{ .workspace = leaf };
    const leaf_items = session.buildContextMenuItems();
    try std.testing.expectEqual(ctx_menu_count, leaf_items.len);
    try std.testing.expectEqualStrings("그룹에서 빼기", leaf_items[ctx_menu_group_remove]);
    try std.testing.expectEqualStrings("여기서 최상위로 분리", leaf_items[ctx_menu_group_promote]);

    // 마커 카드: remove만(promote 숨김 — promoteTabToTopLevelInPlace no-op이라 죽은 항목 방지). len=ctx_menu_group_promote.
    session.context_menu_target = .{ .workspace = marker };
    const marker_items = session.buildContextMenuItems();
    try std.testing.expectEqual(ctx_menu_group_promote, marker_items.len);
    try std.testing.expectEqualStrings("그룹에서 빼기", marker_items[ctx_menu_group_remove]);
    // 마커에도 promote를 강제 dispatch하면 no-op(방어 — 숨겨도 인덱스 도달 불가지만 액션 자체가 안전).
    session.promoteTabToTopLevelInPlace(marker);
    try std.testing.expect(!marker.top_level); // 마커엔 top_level 안 씀(leaf-only §13.8)
}

// §14.7·§14.8 SR5 — pin × local_pinned × top_level **3축 공존**(중첩·고정 리전 하드닝). 세 축이 한 고정 그룹 안에서 함께
// 성립: 전역 pin 프리픽스(I1)·그룹-로컬 pin 프리픽스(subtree 안)·top_level 서브파티션(그룹 밖 복귀)이 직교하며 canonical.
test "SR5(d): pin × local_pinned × top_level 3축 공존 — 고정 그룹 안 정합(§14.7 하드닝)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    // 고정 리전 [A(마커,pin,d1), lp(pin,멤버,local_pinned), m1(pin,멤버), TOP(pin,top_level), sticky(pin,sticky top)].
    inline for (0..5) |i| {
        session.tabs.items[i].pinned = true;
    }
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[1].local_pinned = true; // 그룹-로컬 pin 멤버(marker+1 float)
    session.tabs.items[3].top_level = true; // 고정 top카드(그룹 뒤 인터리브)
    // 세 축 동기(비프리뷰 경로) — normalize(C2 top_level 인식)·float(로컬 pin)·위생(전이 stale).
    session.normalizePinnedFromGroups();
    session.floatLocalPinsAllGroups();
    session.clearStaleLocalPins();

    // 축1 전역 pin(I1): 5개 전부 고정 프리픽스(비고정 0개).
    try std.testing.expectEqual(@as(usize, 5), session.countPinnedTabs());
    for (session.tabs.items) |t| try std.testing.expect(t.pinned);
    // 축3 top_level 서브파티션: A subtree=[0,3)(TOP에서 끊김), TOP·sticky는 그룹 밖 depth 0.
    try std.testing.expectEqual(@as(usize, 3), session.groupSubtreeEnd(0, null, null));
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(3, null, null)); // TOP depth 0
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(4, null, null)); // sticky depth 0
    try std.testing.expect(session.enclosingGroupMarkerIndex(3) == null); // TOP 그룹 밖
    try std.testing.expect(session.enclosingGroupMarkerIndex(4) == null); // sticky 그룹 밖
    try std.testing.expect(session.tabs.items[3].top_level and session.tabs.items[3].pinned); // 고정 top카드(pin×top_level)
    // 축2 그룹-로컬 pin: lp(index1)은 여전히 A 멤버·local_pinned 유지(그룹 밖 안 나감 → 위생이 안 지움).
    try std.testing.expect(session.tabIsInGroup(session.tabs.items[1]));
    try std.testing.expect(session.tabs.items[1].local_pinned);
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(1).?); // A 소속
    try std.testing.expect(session.tabIsInGroup(session.tabs.items[2])); // m1도 A 멤버
    // C2 정합: 고정 리전 안 top_level이 핀 경계와 어긋나지 않음(§14.4·§14.7 (1)).
    try std.testing.expect(session.pinBoundariesAlignGroups());
    // 렌더 힌트 3축 정합: lp는 local_pinned=true(📌 선두 분기 살림)·멤버 m1은 pin_derived(멤버 📌 억제)·TOP은 개별 pin.
    session.recomputeVisibleTabs();
    var saw_lp = false;
    var saw_top_card = false;
    for (session.sidebar_rows.items) |row| switch (row) {
        .card => |c| {
            if (c.tab == 1) {
                saw_lp = c.local_pinned; // lp 카드 local_pinned 힌트
            }
            if (c.tab == 3) saw_top_card = (c.depth == 0 and !c.pin_derived and !c.local_pinned); // TOP=최상위 개별 pin
        },
        .group_header => {},
    };
    try std.testing.expect(saw_lp); // 로컬 pin 렌더 힌트 살아있음(그룹째 고정 아니어도)
    try std.testing.expect(saw_top_card); // 고정 top카드는 depth0·개별 pin(pin_derived/local 아님)
}

test "SR5(e): 중첩 안 top_level — subgroup 뒤 top카드는 depth 0(부모 복귀 없음, §14.7 제약) + topLevelGroupMarkerIndex 상향" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    // [A(마커,d1), a1(A 멤버,d1), B(마커,d2 중첩), b1(B 멤버,d2), TOP(top_level)].
    session.tabs.items[0].group_start = try allocator.dupe(u8, "A");
    session.tabs.items[0].group_depth = 1;
    session.tabs.items[2].group_start = try allocator.dupe(u8, "B");
    session.tabs.items[2].group_depth = 2;
    session.tabs.items[4].top_level = true;
    session.recomputeVisibleTabs();

    // 중첩 파생: a1 depth1(A)·B 마커 depth2·b1 depth2(B)·TOP depth0(그룹 밖).
    try std.testing.expectEqual(@as(u8, 1), session.effectiveDepthAt(1, null, null));
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(2, null, null));
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null));
    // §14.7 제약: TOP은 **depth 0**(부모 A depth 1로 "복귀" 불가 — sticky-reset은 항상 0으로만 되돌린다).
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(4, null, null));
    try std.testing.expect(session.enclosingGroupMarkerIndex(4) == null); // TOP 그룹 밖(A·B 어디도 아님)
    // subtree 끝: A=[0,4)(TOP에서 끊김, 중첩 B 포함)·B=[2,4)(TOP에서 끊김).
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(0, null, null));
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(2, null, null));
    // directCardCount: TOP이 (N) 배지에 안 세짐(top_level break — OR=min). A 직접=a1 1개.
    // topLevelGroupMarkerIndex: 중첩 subgroup B의 멤버 b1(index3)도 **최상위 A(0)**로 상향(gap 드롭이 부모 그룹 끝 기준).
    try std.testing.expectEqual(@as(usize, 0), session.topLevelGroupMarkerIndex(3).?);
    try std.testing.expectEqual(@as(usize, 0), session.topLevelGroupMarkerIndex(2).?); // 중첩 마커 B → 최상위 A
    try std.testing.expect(session.topLevelGroupMarkerIndex(4) == null); // TOP 최상위 카드 → null
}

test "SG8b: 카드 드래그 등가 — 넣기/빼기 + ghost 범위 + self.tabs 불변 (simulateDrop == moveTab)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    session.createGroupAbsorbForTab(session.tabs.items[2]); // A=[t2,t3], 최상위=[t0,t1]

    // 직접 simulateDrop으로 ghost·순열·불변 확인(넣기: t0(index0)를 t3(index3) 자리로 = 그룹 A 안).
    {
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        const vl = try session.simulateDrop(0, .{ .card = .{ .target_tab = 3 } }, arena.allocator());
        // 핀 없음 → clamp 무영향, rotateMove(0→3): order [0,1,2,3] → [1,2,3,0]. 카드는 위치 3에 착지.
        try std.testing.expectEqualSlices(usize, &[_]usize{ 1, 2, 3, 0 }, vl.order);
        try std.testing.expectEqual(@as(usize, 3), vl.ghost_lo);
        try std.testing.expectEqual(@as(usize, 4), vl.ghost_hi);
        // self.tabs 원본 순서는 그대로.
        for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(t, session.tabs.items[i]);
        try std.testing.expectEqual(@as(usize, 4), session.tabs.items.len);
    }

    // 등가(넣기 커밋): t0를 A 안으로. after=[t1,t2,t3,t0].
    try expectDropEquivalent(session, 0, .{ .card = .{ .target_tab = 3 } });
    // 등가(빼기 커밋): t0(현재 index3)를 최상위 카드 자리(index0)로. after=[t0,t1,t2,t3].
    try expectDropEquivalent(session, 3, .{ .card = .{ .target_tab = 0 } });
}

test "SG8b: 핀 경계 카드 드롭 — clamp 일치(프리뷰가 핀 경계에서 정직) + 등가" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    session.tabs.items[0].pinned = true;
    session.tabs.items[1].pinned = true; // 고정 [t0,t1], 비고정 [t2,t3] (pinned_count=2)

    // 비고정 t3(index3)를 고정 영역 target 0으로 드롭 → clampMoveToGroup(0,false,2,4)=2로 클램프(핀 경계에서 정직).
    {
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        const vl = try session.simulateDrop(3, .{ .card = .{ .target_tab = 0 } }, arena.allocator());
        try std.testing.expectEqual(@as(usize, 2), vl.ghost_lo); // raw 0이 아니라 clamp된 2에 착지
        try std.testing.expectEqual(@as(usize, 3), vl.ghost_hi);
        try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 1, 3, 2 }, vl.order); // t3가 비고정 영역 시작(2)으로만
    }
    // 등가: moveTab(3,0)도 같은 clamp → 프리뷰-확정 일치.
    try expectDropEquivalent(session, 3, .{ .card = .{ .target_tab = 0 } });

    // 고정 t0(index0)를 비고정 영역 target 3으로 드롭 → clamp(3,true,pinned,4)=1(고정 영역 [0,1]). (커밋 후 t1은 index0.)
    {
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        const vl = try session.simulateDrop(0, .{ .card = .{ .target_tab = 3 } }, arena.allocator());
        try std.testing.expectEqual(@as(usize, 1), vl.ghost_lo); // 고정 영역 끝(1)으로 clamp
    }
    try expectDropEquivalent(session, 0, .{ .card = .{ .target_tab = 3 } });
}

test "SG8b: 그룹 통째 형제 이동 등가 (SG5-1, simulateDrop == moveGroupSibling)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    // A=[t0,t1], B=[t2,t3], C=[t4,t5] 형제 3그룹(전부 depth1).
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "B", 1);
    try setGroupMarker(session, 4, "C", 1);

    // A(m=0)를 B 뒤(insert_before=groupSubtreeEnd(B)=4)로 = B와 C 사이로. 같은 레벨이라 depth 무변(SG5-1 보존).
    {
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        const vl = try session.simulateDrop(0, .{ .group_sibling = .{ .insert_before = 4 } }, arena.allocator());
        // Rest=[t2,t3,t4,t5], 블록 [0,2)=(t0,t1)을 rest_insert=4-2=2 앞에 → [t2,t3,t0,t1,t4,t5].
        try std.testing.expectEqualSlices(usize, &[_]usize{ 2, 3, 0, 1, 4, 5 }, vl.order);
        try std.testing.expectEqual(@as(usize, 2), vl.ghost_lo); // A 블록이 위치 2에 착지
        try std.testing.expectEqual(@as(usize, 4), vl.ghost_hi);
        for (vl.group_depth) |d| if (d != 0) try std.testing.expectEqual(@as(u8, 1), d); // 형제라 depth 무변(비마커=원래값)
    }
    try expectDropEquivalent(session, 0, .{ .group_sibling = .{ .insert_before = 4 } });
}

test "SG8b: 중첩 넣기 등가 (SG5-4, simulateDrop == moveGroupNesting) + subtree 상대 depth" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    // A=[t0,t1] 직접 + C 중첩=[t2,t3](depth2, A 안), B=[t4,t5](depth1, A 형제).
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "C", 2);
    try setGroupMarker(session, 4, "B", 1);

    // A(m=0)를 B 헤더에 드롭 → B 자식으로 중첩(target_depth=B eff1+1=2, insert_before=groupSubtreeEnd(B)=6).
    {
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        const vl = try session.simulateDrop(0, .{ .group_nest = .{ .insert_before = 6, .target_depth = 2 } }, arena.allocator());
        // 블록 [0,4)=(A,·,C,·)을 B(=[4,6)) 뒤로 → order [4,5,0,1,2,3]. A는 위치 2에서 시작.
        try std.testing.expectEqualSlices(usize, &[_]usize{ 4, 5, 0, 1, 2, 3 }, vl.order);
        try std.testing.expectEqual(@as(usize, 2), vl.ghost_lo);
        try std.testing.expectEqual(@as(usize, 6), vl.ghost_hi);
        // 상대 depth 유지: A(위치2)=2, C(위치4)=3(A보다 1 깊음). B(위치0)=1 불변.
        try std.testing.expectEqual(@as(u8, 1), vl.group_depth[0]); // B
        try std.testing.expectEqual(@as(u8, 2), vl.group_depth[2]); // A → B 자식
        try std.testing.expectEqual(@as(u8, 3), vl.group_depth[4]); // C → A 자식(상대 유지)
    }
    try expectDropEquivalent(session, 0, .{ .group_nest = .{ .insert_before = 6, .target_depth = 2 } });
}

test "SG8b: 형제 빼기 등가 — gap-clamp로 depth 얕아짐 (SG5-4 un-nest, simulateDrop == moveGroupSibling)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
