    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
    // t0 최상위, A=[t1,t2](마커 t1, depth1) 접힘(§2.1 연속 파티션: 최상위 카드는 첫 마커 이전만).
    try setGroupMarker(session, 1, "A", 1);
    session.tabs.items[1].group_collapsed = true;

    // 라이브(원본) 투영 — t0는 최상위 카드로 보이고(존재), A 헤더는 접힘(t2 숨김). 길이 비교의 기준(move 모델).
    session.recomputeVisibleTabs();
    const live_len = session.sidebar_rows.items.len;
    try std.testing.expect(sg8cFindCardDepth(session.sidebar_rows.items, 0) != null);

    // self.tabs 불변 스냅샷(포인터·순서).
    const n = session.tabs.items.len;
    var before: [8]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    // plan: t0(index0)를 A 안(t2 자리 index2)으로 = 접힌 그룹 안 드롭.
    const plan = AppSession.DropPlan{ .card = .{ .target_tab = 2 } };
    const vl = try session.simulateDrop(0, plan, arena.allocator());

    // (원본=커밋 레이아웃) 프리뷰 예외 없이 가상 order를 그대로 투영하면 t0가 접힘 게이트로 **사라진다**(라이브 확정 시 증상).
    session.projectRowsFrom(vl.order, vl.group_depth);
    try std.testing.expect(sg8cFindCardDepth(session.sidebar_rows.items, 0) == null); // 고스트 예외 없으면 사라짐
    try std.testing.expect(sg8cFindHeader(session.sidebar_rows.items, 1).?.group_header.collapsed); // flip 없음(접힘 그대로)

    // (프리뷰) 고스트 강제 방출 + 헤더 flip + order-aware member_count.
    try session.refreshDragPreview(0, plan, 0, arena.allocator());
    const prows = session.sidebar_preview_rows.items;
    try std.testing.expectEqual(@as(?u8, 1), sg8cFindCardDepth(prows, 0)); // (a) 고스트 존재 + depth 정확(A 안=depth 1)
    const phdr = sg8cFindHeader(prows, 1).?.group_header;
    try std.testing.expect(!phdr.collapsed); // 타겟 헤더 collapsed=false(flip)
    try std.testing.expectEqual(@as(u16, 3), phdr.member_count); // 고스트 반영(t1·t2·t0 = 3, 라이브는 2였음)
    try std.testing.expectEqual(live_len, prows.len); // (d) move(순열) 모델 — 길이 동일

    // 고스트 range(표시-row 도메인)가 실제 고스트 카드 row를 가리킨다(order 위치가 아니라 방출 row 인덱스).
    const dp = session.sidebar_drag_preview.?;
    try std.testing.expect(dp.ghost_lo < dp.ghost_hi);
    try std.testing.expect(prows[dp.ghost_lo] == .card);
    try std.testing.expectEqual(@as(usize, 0), prows[dp.ghost_lo].card.tab);

    // (e) self.tabs 불변(순서·포인터).
    try std.testing.expectEqual(n, session.tabs.items.len);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t);
}

// SG8c 케이스 (b): 펼친 그룹을 다른 펼친 그룹 헤더에 드롭(중첩)하는 plan을 프리뷰 투영하면 옮겨진 subtree 전체가
// 고스트로 방출되고 **상대 depth**가 유지된다(A→B 자식=depth2, A의 자식 C=depth3). 접힘 없음이라 강제 방출은 없지만
// 순열/depth 재투영과 표시-row 고스트 range·길이 동일(move 모델)을 함께 고정한다.
test "SG8c: 펼친 그룹 nest 프리뷰 → subtree 고스트 상대 depth(A=2·C=3)·길이 동일·range" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    // A=[t0,t1] 직접 + C 중첩=[t2,t3](depth2, A 안), B=[t4,t5](depth1, A 형제). (SG8b nest 테스트와 동형 배치)
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "C", 2);
    try setGroupMarker(session, 4, "B", 1);

    session.recomputeVisibleTabs();
    const live_len = session.sidebar_rows.items.len;
    const n = session.tabs.items.len;
    var before: [8]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    // A(m=0)를 B 헤더에 드롭 → B 자식으로 중첩(target_depth=B eff1+1=2, insert_before=groupSubtreeEnd(B)=6).
    const plan = AppSession.DropPlan{ .group_nest = .{ .insert_before = 6, .target_depth = 2 } };
    try session.refreshDragPreview(0, plan, 0, arena.allocator());
    const prows = session.sidebar_preview_rows.items;

    // 상대 depth 유지: A(마커 tab0)=2(B 자식), C(마커 tab2)=3(A 자식). 헤더·카드 모두.
    try std.testing.expectEqual(@as(u8, 2), sg8cFindHeader(prows, 0).?.group_header.depth);
    try std.testing.expectEqual(@as(?u8, 2), sg8cFindCardDepth(prows, 0));
    try std.testing.expectEqual(@as(u8, 3), sg8cFindHeader(prows, 2).?.group_header.depth);
    try std.testing.expectEqual(@as(?u8, 3), sg8cFindCardDepth(prows, 2));
    // B(마커 tab4)는 부모라 depth1 불변.
    try std.testing.expectEqual(@as(u8, 1), sg8cFindHeader(prows, 4).?.group_header.depth);
    try std.testing.expectEqual(live_len, prows.len); // move 모델 — 길이 동일(접힘 없어 순열만)

    // 고스트 range: subtree(A·A직접카드·C) 전체가 표시-row 연속 구간으로 방출됐다(비어있지 않음).
    const dp = session.sidebar_drag_preview.?;
    try std.testing.expect(dp.ghost_lo < dp.ghost_hi);
    try std.testing.expect(sg8cFindHeader(prows[dp.ghost_lo..dp.ghost_hi], 0) != null); // A 헤더가 고스트 구간 안

    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변
    try std.testing.expectEqual(n, session.tabs.items.len);
}

// SG8c 케이스 (c): none plan(제자리·무효)은 고스트가 없다 — preview_rows가 라이브 sidebar_rows와 byte-identical하고
// 프리뷰 ghost range가 비어있다(lo==hi). 프리뷰가 "아무것도 안 옮김"을 정직하게 표시함을 고정한다.
test "SG8c: none plan 프리뷰 → preview_rows == 원본 rows·ghost range 비어있음" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    try setGroupMarker(session, 0, "A", 1); // A=[t0,t1,t2] 전부 한 그룹(펼침)

    session.recomputeVisibleTabs();
    var live: [16]chrome.components.sidebar.Row = undefined;
    const live_len = session.sidebar_rows.items.len;
    try std.testing.expect(live_len > 0 and live_len <= live.len);
    for (session.sidebar_rows.items, 0..) |row, i| live[i] = row;

    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    try session.refreshDragPreview(0, .none, 0, arena.allocator());
    const prows = session.sidebar_preview_rows.items;

    // preview == 라이브(byte-identical) — 태그·핵심 필드.
    try std.testing.expectEqual(live_len, prows.len);
    for (prows, 0..) |got, i| {
        const want = live[i];
        try std.testing.expectEqual(std.meta.activeTag(want), std.meta.activeTag(got));
        switch (want) {
            .card => |wc| {
                try std.testing.expectEqual(wc.tab, got.card.tab);
                try std.testing.expectEqual(wc.depth, got.card.depth);
            },
            .group_header => |wh| {
                try std.testing.expectEqual(wh.tab, got.group_header.tab);
                try std.testing.expectEqual(wh.collapsed, got.group_header.collapsed);
                try std.testing.expectEqual(wh.member_count, got.group_header.member_count);
                try std.testing.expectEqual(wh.depth, got.group_header.depth);
            },
        }
    }
    const dp = session.sidebar_drag_preview.?;
    try std.testing.expectEqual(dp.ghost_lo, dp.ghost_hi); // 고스트 없음(range 비어있음)
}

test "code-review #6: 검색 중 접힌 그룹은 헤더도 펼침 표시(collapsed=false) — 강제 펼친 카드와 정합" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
    session.createGroupAbsorbForTab(session.tabs.items[0]); // 전부 한 그룹(연속 파티션)
    session.tabs.items[0].group_collapsed = true; // 그룹 접힘(영속 의도)
    session.tabs.items[1].custom_name = try allocator.dupe(u8, "findme"); // 그룹 안 카드 하나에 매치용 이름

    // 검색 활성 + 매치 쿼리 → 접힘을 일시 무시하고 매치 카드를 펼쳐 보여야 하고(docs §1), 헤더도 펼침 표시(collapsed=false).
    session.sidebar_search_active = true;
    try session.sidebar_search_input.query.appendSlice(allocator, "findme");
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header);
    try std.testing.expect(!session.sidebar_rows.items[0].group_header.collapsed); // 검색 중 = 펼침 표시(삼각 ▾·배지 없음)
    // 매치 카드(t1)가 접힘 무시하고 펼쳐 보인다.
    var saw_t1_card = false;
    for (session.sidebar_rows.items) |row| switch (row) {
        .card => |c| if (c.tab == 1) {
            saw_t1_card = true;
        },
        .group_header => {},
    };
    try std.testing.expect(saw_t1_card);

    // 검색을 지우면 원래 접힘 상태로 복귀(헤더 collapsed=true, 카드 숨김).
    session.sidebar_search_active = false;
    session.sidebar_search_input.clear();
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed); // 영속 접힘 복원
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len); // 헤더만(카드 접힘)
}

test "SG3c: create_group·헤더 클릭 접기 토글·ungroup·closeTab 마커 승계 (세션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // 탭 3개: [t0, t1, t2]

    // create_group(t0) → group_start 세팅 + projectRows에 group_header(소스 tab=0) 삽입, 아래 카드 depth 1(연속 파티션으로 t0~t2 한 그룹).
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    try std.testing.expect(session.tabs.items[0].group_start != null);
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_rows.items[0].group_header.tab); // 소스 탭 인덱스(#8·토글 대상)
    try std.testing.expectEqual(@as(u16, 3), session.sidebar_rows.items[0].group_header.member_count);
    try std.testing.expect(session.sidebar_rows.items[1] == .card);
    try std.testing.expectEqual(@as(u8, 1), session.sidebar_rows.items[1].card.depth); // 그룹 안 들여쓰기

    // 중복 create_group은 no-op(이름 보존).
    const marker_ptr = session.tabs.items[0].group_start.?.ptr;
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    try std.testing.expectEqual(marker_ptr, session.tabs.items[0].group_start.?.ptr);

    // 헤더 클릭(slot 0) → group_collapsed 토글 → 카드 skip(헤더만).
    session.toggleGroupCollapsedAt(0);
    try std.testing.expect(session.tabs.items[0].group_collapsed);
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len); // 헤더만(카드 접힘)
    try std.testing.expect(session.sidebar_rows.items[0].group_header.collapsed);
    session.toggleGroupCollapsedAt(0); // 다시 → 펼침
    try std.testing.expect(!session.tabs.items[0].group_collapsed);

    // closeTab(0): 그룹 시작 탭이 닫히면 마커·접힘·그룹 색이 다음 탭(t1)으로 승계 → 그룹 유지.
    session.tabs.items[0].group_collapsed = true;
    session.tabs.items[0].group_color = 0x4A7BC4; // SG5-2: 그룹 색도 마커 따라 승계돼야 한다
    session.closeTab(0); // [t1, t2]
    try std.testing.expect(session.tabs.items[0].group_start != null); // t1이 마커 승계
    try std.testing.expect(session.tabs.items[0].group_collapsed); // 접힘도 승계
    try std.testing.expectEqual(@as(u32, 0x4A7BC4), session.tabs.items[0].group_color); // 그룹 색 승계(SG5-2)
    try std.testing.expectEqualStrings("그룹 1", session.tabs.items[0].group_start.?);

    // ungroup(t2, 그룹 소속) → 그 위 시작 마커(t1) 제거 → 그룹 소멸.
    session.ungroupTab(session.tabs.items[1]);
    try std.testing.expect(session.tabs.items[0].group_start == null);
}

test "code-review #1: 그룹 헤더 우클릭(context_menu_target=.group) 중 마커 탭 destroy → 대상 클리어(UAF 방지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    // std.testing.allocator는 leak/UAF 검출 allocator라, teardown 후 dangling *Tab을 남기면 후속 접근이 잡힌다.
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
    const marker_tab = session.tabs.items[0];
    session.createGroupAbsorbForTab(marker_tab); // t0=그룹 시작 마커

    // 그룹 헤더 우클릭 시뮬레이션 — context_menu_target을 마커 탭으로 잡는다(renameTargetAt/8154 경로).
    session.context_menu_target = .{ .group = marker_tab };

    // 마커 탭 destroy: closeTab(0)은 group_start를 t1로 승계하고 marker_tab(*Tab)을 통째 free한다. 옛 코드는
    // .workspace 대상만 클리어해 .group 대상이 dangling으로 남았다(메뉴 accept 시 startRename UAF).
    session.closeTab(0);
    try std.testing.expect(session.context_menu_target == null); // .group 대상이 클리어돼 dangling 없음

    // 메뉴 accept 경로가 stale 대상을 안 건드리는지(null이면 no-op) 확인 — 여기서 UAF면 leak-check가 잡는다.
    session.acceptContextMenu();
    try std.testing.expect(session.context_menu_target == null);
}

test "code-review #5: 그룹 rename 캐럿이 사이드바 indent_cols를 반영(헤더 삼각/이름과 정렬)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    _ = try session.newTab(); // [t0, t1]
    const marker = session.tabs.items[0];
    session.createGroupAbsorbForTab(marker); // t0 그룹 시작(depth1, 기본 이름 "그룹 1")
    session.startRename(.{ .group = marker }); // 그룹 이름 편집 시작(query=group_start 시드)
    session.recomputeVisibleTabs();

    const cw = session.cell_width_px;
    try std.testing.expect(cw > 0);
    const sp = session.buildChromeTokens().space;
    const indent_cols: u32 = (sp.card_gap_px + sp.accent_bar_width_px + cw - 1) / cw;
    try std.testing.expect(indent_cols > 0); // rich = accent_bar+card_gap>0 — 0이면 이 회귀를 못 잡으므로 전제 확인
    const qcols: u32 = session.rename_input.queryCols();
    const rect = session.renameCaretRect() orelse return error.NoCaret;
    // depth1(hindent=0): caret_col = indent_cols + 2(삼각+공백) + qcols. 옛 코드는 indent_cols가 빠져(=2+qcols)
    // 캐럿·IME 후보창이 indent_cols칸 왼쪽으로 어긋났다(code-review #5). buildSidebarTitleDrawList의 전역 shift와 정합.
    try std.testing.expectEqual(@as(i32, @intCast((indent_cols + 2 + qcols) * cw)), rect.x);
}

test "remove_from_group: 그룹 소속 카드→최상위(depth0·첫 그룹 앞)·최상위 no-op·마커 카드 승계·마지막 멤버 소멸(주입 조건)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3] 4개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // t1에 그룹 시작 → 연속 파티션으로 group=[t1,t2,t3], t0=최상위.
    session.createGroupAbsorbForTab(t1);
    try std.testing.expect(t1.group_start != null);

    // 주입 조건(tabIsInGroup): 최상위 t0=false, 그룹 소속 t1/t2/t3=true(마커 카드 t1 포함).
    try std.testing.expect(!session.tabIsInGroup(t0));
    try std.testing.expect(session.tabIsInGroup(t1));
    try std.testing.expect(session.tabIsInGroup(t2));
    try std.testing.expect(session.tabIsInGroup(t3));

    // (A) 최상위 카드 no-op: t0에 빼기 → 순서·그룹 불변.
    session.removeFromGroupForTab(t0);
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 제자리
    try std.testing.expect(t1.group_start != null); // 그룹 그대로

    // (B) 그룹 소속 **멤버** 카드 t2 빼기 → 첫 마커(t1) 직전으로 이동 = 최상위(depth 0). 그룹은 [t1,t3]로 유지.
    session.removeFromGroupForTab(t2);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t2)); // 완전 최상위
    try std.testing.expect(t1.group_start != null); // 그룹 유지(멤버 하나만 빠짐)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1)); // t1 여전히 그룹 안
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // t3 여전히 그룹 안
    // t2는 첫 마커(t1)보다 앞: tabs 순서 [t0, t2, t1, t3].
    try std.testing.expect(!session.tabIsInGroup(t2));

    // (C) 그룹 **시작 마커** 카드 t1 빼기 → 마커를 다음 소속 카드(t3)로 승계해 그룹 유지, t1은 최상위.
    session.removeFromGroupForTab(t1);
    try std.testing.expect(t1.group_start == null); // 마커 뗐다
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // t1 최상위
    try std.testing.expect(t3.group_start != null); // t3이 마커 승계 → 그룹 유지
    try std.testing.expectEqualStrings("그룹 1", t3.group_start.?); // 이름 승계(소유권 이전, 누수 없음)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // t3 그룹 시작 카드

    // (D) 마지막 멤버(=마커) t3 빼기 → 승계 대상 없어 그룹 소멸(마커 free — testing allocator 누수 감시). 전부 최상위.
    session.removeFromGroupForTab(t3);
    try std.testing.expect(t3.group_start == null);
    try std.testing.expect(session.firstGroupStartIndex() == null); // 그룹 전무
    try std.testing.expect(!session.tabIsInGroup(t3));
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t3));
}

test "SG5-3: 2단계 중첩(A>B) — projectRows depth 0/1/2·헤더 depth·member_count·부모 직접카드가 자식 앞 제약" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4] 5개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];

    // 구조: t0=최상위, A=t1(depth1)·직접카드 t1,t2, B=t3(depth2, A 안 중첩)·직접카드 t3,t4.
    // create_group 위치 파생: t1은 최상위 카드 → A depth 1. t3은 A 안 카드(depth1) → B depth 2(중첩).
    session.createGroupAbsorbForTab(t1);
    session.createGroupAbsorbForTab(t3);
    try std.testing.expectEqual(@as(u8, 2), t3.group_depth); // t3 create가 중첩 depth 2

    session.recomputeVisibleTabs();
    // 기대 rows: [card t0(d0), header A(d1), card t1(d1), card t2(d1), header B(d2), card t3(d2), card t4(d2)]
    const rows = session.sidebar_rows.items;
    try std.testing.expectEqual(@as(usize, 7), rows.len);
    try std.testing.expect(rows[0] == .card and rows[0].card.tab == 0 and rows[0].card.depth == 0); // 최상위
    try std.testing.expect(rows[1] == .group_header and rows[1].group_header.tab == 1 and rows[1].group_header.depth == 1); // A 헤더 depth1
    try std.testing.expectEqual(@as(u16, 2), rows[1].group_header.member_count); // A 직접카드 = t1,t2 (자식 B 카드 제외)
    try std.testing.expect(rows[2].card.depth == 1 and rows[2].card.tab == 1); // A 마커 카드
    try std.testing.expect(rows[3].card.depth == 1 and rows[3].card.tab == 2); // A 직접카드
    try std.testing.expect(rows[4] == .group_header and rows[4].group_header.tab == 3 and rows[4].group_header.depth == 2); // B 헤더 depth2(중첩)
    try std.testing.expectEqual(@as(u16, 2), rows[4].group_header.member_count); // B 직접카드 = t3,t4
    try std.testing.expect(rows[5].card.depth == 2 and rows[5].card.tab == 3); // B 마커 카드 depth2
    try std.testing.expect(rows[6].card.depth == 2 and rows[6].card.tab == 4); // B 직접카드 depth2

    // 부모 직접카드가 자식 앞 제약(§2.1 다단계): A의 depth1 카드(row2,3)가 B 헤더(row4)보다 앞. 자식 뒤 부모 복귀 없음.
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0));
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1));
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t3));
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t4));
}

test "SG5-3: 다단계 접기 — 부모 A 접으면 자식 B와 그 카드 통째 숨김·자식 B만 접으면 B 카드만 숨김" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 4개
    // A=t0(depth1)·카드 t0,t1, B=t2(depth2 중첩)·카드 t2,t3.
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    session.createGroupAbsorbForTab(session.tabs.items[2]);
    try std.testing.expectEqual(@as(u8, 2), session.tabs.items[2].group_depth);

    // 펼침 전체: [hA, c t0, c t1, hB, c t2, c t3] = 6 rows.
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 6), session.sidebar_rows.items.len);

    // ── 자식 B만 접기: B 카드(t2,t3)만 숨김, B 헤더는 남고 A는 그대로. [hA, c t0, c t1, hB(collapsed)] = 4 rows.
    session.tabs.items[2].group_collapsed = true;
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 4), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header); // A 헤더
    try std.testing.expect(session.sidebar_rows.items[3] == .group_header and session.sidebar_rows.items[3].group_header.collapsed); // B 접힘 헤더 남음
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[3].group_header.member_count); // (N)=B 직접카드 2
    session.tabs.items[2].group_collapsed = false;

    // ── 부모 A 접기: 자식 B 헤더까지 통째 숨김(부모 접기=자식 그룹 통째 숨김). [hA(collapsed)] = 1 row.
    session.tabs.items[0].group_collapsed = true;
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[0] == .group_header and session.sidebar_rows.items[0].group_header.collapsed);
    try std.testing.expectEqual(@as(u16, 2), session.sidebar_rows.items[0].group_header.member_count); // A 직접카드 2(자식 그룹 카드 제외)

    // ── 둘 다 접힘: 여전히 A 헤더 하나만(부모 접힘이 자식 헤더를 가림 — B 접힘 무관).
    session.tabs.items[2].group_collapsed = true;
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items.len);
}

test "SG5-3: ungroup 중첩 — 자식 ungroup은 부모로 재소속·부모 ungroup은 자식이 최상위로 승격(gap 클램프)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    // A=t0(depth1)·t0,t1, B=t2(depth2 중첩)·t2,t3.
    session.createGroupAbsorbForTab(session.tabs.items[0]);
    session.createGroupAbsorbForTab(t2);

    // ── 자식 B ungroup(t3 소속=B) → 가장 가까운 마커 B 제거 → t2,t3가 부모 A로 재소속(depth 1).
    session.ungroupTab(t3);
    try std.testing.expect(session.tabs.items[2].group_start == null); // B 마커 제거
    try std.testing.expect(session.tabs.items[0].group_start != null); // A 유지
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // A로 재소속(depth 1)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3));

    // 다시 B를 중첩 생성한 뒤, 부모 A ungroup → A 마커 제거 → t0,t1 최상위·B는 부모 없어 gap 클램프로 depth 1(최상위 그룹) 승격.
    session.createGroupAbsorbForTab(t2); // B 재생성(depth 2)
    try std.testing.expectEqual(@as(u8, 2), t2.group_depth);
    session.ungroupTab(session.tabs.items[0]); // A(t0) 마커 제거
    try std.testing.expect(session.tabs.items[0].group_start == null); // A 제거
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, session.tabs.items[1])); // 옛 A 카드 t1 → 최상위
    // B는 저장 depth 2지만 부모가 없어 projectRows가 depth 1로 정규화(gap 클램프) → 최상위 그룹.
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));
}

test "SG5-3: create_sibling_group(형제 같은 depth) vs create_group(중첩 depth+1) — 명시적 분리" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 4개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // ── 최상위 카드에서 두 액션은 결과 동일(depth 1). t0에 create_sibling_group → depth 1(create_group과 동일).
    session.createSiblingGroupAbsorbForTab(t0);
    try std.testing.expectEqual(@as(u8, 1), t0.group_depth);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 최상위 그룹 A

    // 이제 t0=그룹 A(depth1, [t0..t3] 전부). 그룹 안 카드 t2에서 두 액션을 대비한다.
    // ── create_group(t2) = **중첩**: t2 현재 depth 1 → B depth 2(A 자식). t3도 B(depth 2).
    session.createGroupAbsorbForTab(t2);
    try std.testing.expectEqual(@as(u8, 2), t2.group_depth); // 중첩 = depth+1
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t2)); // 중첩 자식
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t3)); // B 몸통(중첩)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1)); // A 직접카드는 그대로 depth 1

    // t2 그룹을 풀고(원복) 이번엔 create_sibling_group으로 대비.
    session.ungroupTab(t2); // B 마커 제거 → t2,t3 다시 A(depth1)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));

    // ── create_sibling_group(t2) = **형제**: t2 현재 depth 1 → C depth 1(A와 같은 depth 형제, 중첩 아님). t3도 C(depth 1).
    session.createSiblingGroupAbsorbForTab(t2);
    try std.testing.expectEqual(@as(u8, 1), t2.group_depth); // 형제 = 같은 depth
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // 형제 그룹 C(최상위, 중첩 아님)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // C 몸통(depth 1, 중첩 아님)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // A 유지

    // 연속 파티션: [A: t0,t1][C: t2,t3] 두 형제 최상위 그룹. 헤더 depth로 확인(둘 다 depth 1 = 중첩 아님).
    session.recomputeVisibleTabs();
    var header_depths: [4]u8 = undefined;
    var hc: usize = 0;
    for (session.sidebar_rows.items) |row| switch (row) {
        .group_header => |gh| {
            if (hc < header_depths.len) header_depths[hc] = gh.depth;
            hc += 1;
        },
        .card => {},
    };
    try std.testing.expectEqual(@as(usize, 2), hc); // 그룹 헤더 2개(A·C)
    try std.testing.expectEqual(@as(u8, 1), header_depths[0]); // A 최상위
    try std.testing.expectEqual(@as(u8, 1), header_depths[1]); // C 최상위 형제(중첩 아님 — 이게 tension 해소)
}

test "SG4: 카드 드래그 넣기/빼기 — drop row→탭 매핑 + 위치 파생 소속 + 연속 파티션 (moveTab 직접)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // 탭 4개: [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 그룹 A를 t2에서 시작 → t2·t3가 그룹 A(연속), t0·t1은 최상위(§2.1 첫 마커 이전 구간).
    session.createGroupAbsorbForTab(t2);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // 그룹 A 마커 카드
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // 그룹 A 몸통

    // rows(펼침): [card t0(d0), card t1(d0), header A(tab2), card t2(d1), card t3(d1)].
    session.recomputeVisibleTabs();
    try std.testing.expectEqual(@as(usize, 5), session.sidebar_rows.items.len);

    // ── ① 넣기(그룹 A 몸통 카드에 드롭): t0(최상위)를 t3(=row4, tab index 3)에 드롭 → moveTab이 t3 자리로.
    //    핸들러와 동형: sidebarGroupDropTargetTab(raw_row, from) → moveTab(from, target).
    {
        const from: usize = 0; // t0
        const target = session.sidebarGroupDropTargetTab(4, from).?; // 카드 row → 그 카드 탭(3)
        try std.testing.expectEqual(@as(usize, 3), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t1, t2(mk A), t3, t0] — t0가 그룹 A 안으로(위치 파생). 연속 파티션: 최상위=[t1], A=[t2,t3,t0].
    try std.testing.expectEqual(t1, session.tabs.items[0]);
    try std.testing.expectEqual(t2, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t0, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 넣기 성공 = depth 1
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // t1 여전히 최상위

    // ── ② 빼기(최상위 카드에 드롭): t0(그룹 A, index 3)를 t1(최상위, row0=tab index 0)에 드롭 → 최상위 구간으로.
    {
        const from: usize = 3; // t0 현재 인덱스
        const target = session.sidebarGroupDropTargetTab(0, from).?; // 최상위 카드 row → tab 0
        try std.testing.expectEqual(@as(usize, 0), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t0, t1, t2(mk A), t3] — t0가 첫 마커(t2@2) 이전으로 빠져 최상위. A=[t2,t3].
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 빼기 성공 = depth 0

    // ── ③ 넣기(펼친 그룹 헤더에 드롭, from<M): t1(최상위, index1)을 그룹 A 헤더(row2)에 → 그룹 최상단(마커 직후).
    session.recomputeVisibleTabs(); // rows: [card t0(d0), card t1(d0), header A(tab2), card t2(d1), card t3(d1)]
    {
        const from: usize = 1; // t1
        const target = session.sidebarGroupDropTargetTab(2, from).?; // 펼친 헤더 m=2, from<m → to=m=2
        try std.testing.expectEqual(@as(usize, 2), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t0, t2(mk A), t1, t3] — t1이 마커 직후(A 최상단). A=[t2,t1,t3], 최상위=[t0].
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t2, session.tabs.items[1]);
    try std.testing.expectEqual(t1, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t1)); // 그룹 안

    // ── ④ 접힌 그룹 헤더에 드롭 → 그룹 끝에 추가(§10, 드롭 위치가 안 보이니 끝). t0를 접힌 A 헤더에.
    session.tabs.items[1].group_collapsed = true; // t2가 마커(index1) — 접기
    session.recomputeVisibleTabs(); // rows: [card t0(d0), header A(tab1, collapsed)]
    try std.testing.expectEqual(@as(usize, 2), session.sidebar_rows.items.len);
    try std.testing.expect(session.sidebar_rows.items[1].group_header.collapsed);
    {
        const from: usize = 0; // t0
        const target = session.sidebarGroupDropTargetTab(1, from).?; // 접힌 헤더 → 그룹 끝(연속 파티션 [1,4)의 j-1=3)
        try std.testing.expectEqual(@as(usize, 3), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t2(mk A), t1, t3, t0] — t0가 그룹 A 끝. A=[t2,t1,t3,t0] 전부(최상위 없음).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[3]); // 그룹 끝
    // 펼쳐서 확인: t0는 그룹 안(depth 1)·마지막 카드.
    session.tabs.items[0].group_collapsed = false;
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0));
    // 연속 파티션 불변식: 마커는 index 0 하나뿐, 나머지 전부 그 그룹(중간에 최상위로 안 쪼개짐).
    var marker_count: usize = 0;
    for (session.tabs.items) |t| if (t.group_start != null) {
        marker_count += 1;
    };
    try std.testing.expectEqual(@as(usize, 1), marker_count);
}

test "code-review #2: 접힌 marker-only 그룹에 아래 카드 드롭(from>m) → 그룹 안(마커 뒤)에 들어간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // A=t1(그룹 시작), B=t2(형제 그룹 시작 같은 depth) → A는 marker-only([1,2))·B=[2,4)(t2,t3). A를 접는다.
    session.createGroupAbsorbForTab(t1); // A depth1, 연속상 [1,4)
    session.createSiblingGroupAbsorbForTab(t2); // t2 형제 마커(depth1) → A=[1,2) marker-only, B=[2,4)
    t1.group_collapsed = true;
    session.recomputeVisibleTabs();
    // rows: [card t0, header A(tab1,collapsed), header B(tab2), card t2(d1), card t3(d1)]
    try std.testing.expect(session.sidebar_rows.items[1].group_header.collapsed);
    try std.testing.expectEqual(@as(usize, 1), session.sidebar_rows.items[1].group_header.tab); // A 마커=t1

    // 아래 카드 t3(index 3, from>m=1)을 접힌 A 헤더(row1)에 드롭. 옛 코드는 j-1=1=m → moveTab(3,1)로 마커 앞에
    // 떨궈 t3가 최상위로 샜다. 수정 후 to=@min(j=2,len-1)=2 → 마커(t1@1) 뒤로.
    const from: usize = 3;
    const target = session.sidebarGroupDropTargetTab(1, from).?;
    try std.testing.expectEqual(@as(usize, 2), target);
    _ = session.moveTab(from, target);

    // 결과 [t0, t1(A), t3, t2(B)] — t3가 마커 A 바로 뒤(그룹 안). A=[1,3)=(t1,t3), B=[3,4)=(t2).
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    // t3는 그룹 A 안(depth1) — 펼쳐서 확인(접힌 상태론 숨겨져 null).
    t1.group_collapsed = false;
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // 밖으로 안 샘 = 그룹 안
}

test "code-review #3: pane grip을 그룹 헤더에 드롭 → 새 워크스페이스 안 생김(no-op)·카드=merge·빈 영역=new_workspace" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2], 활성=t2(마지막 생성)
    session.createGroupAbsorbForTab(session.tabs.items[1]); // t1=그룹 시작 → rows: [card t0, header(t1), card t1, card t2]
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebar_rows.items[1] == .group_header);

    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const header_row_h = session.sidebar_header_row_h_px;
    const slot_h = session.sidebar_slot_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 그룹 헤더 row(index 1) 중앙 y에 pane grip 드롭 → **null(no-op)**. 옛 코드는 new_workspace로 falls through했다.
    const hdr_top = sb.rowTop(session.sidebar_rows.items, 1, header_h, slot_h, header_row_h, 0);
    const hdr_y: f64 = @floatFromInt(hdr_top + @as(i64, @intCast(header_row_h / 2)));
    try std.testing.expect(session.computePaneDropDest(x, hdr_y) == null); // 헤더 드롭 = 무동작

    // 비활성 카드 row(index 0 = t0) → merge(그 워크스페이스에 합치기).
    const card_top = sb.rowTop(session.sidebar_rows.items, 0, header_h, slot_h, header_row_h, 0);
    const card_y: f64 = @floatFromInt(card_top + @as(i64, @intCast(slot_h / 2)));
    const dest = session.computePaneDropDest(x, card_y);
    try std.testing.expect(dest != null and dest.? == .merge);

    // 리스트 아래 빈 영역(past-end) → new_workspace(자연스러운 "빈 영역=새 워크스페이스" 보존).
    const past_end = sb.rowTop(session.sidebar_rows.items, session.sidebar_rows.items.len, header_h, slot_h, header_row_h, 0);
    const below_y: f64 = @floatFromInt(past_end + @as(i64, @intCast(slot_h)));
    const dest2 = session.computePaneDropDest(x, below_y);
    try std.testing.expect(dest2 != null and dest2.? == .new_workspace);
}

test "SG4/SG5-1: 두 그룹 사이 이동(펼친 헤더 from>M) + 마커 탭 카드 드래그=그룹 통째 이동 + 드롭 하이라이트 (mouse 시뮬레이션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 두 **형제**(sibling) 최상위 그룹: A=t0에서 시작(t0,t1), B=t2에서 시작(t2,t3). 연속 파티션 [A][B], 최상위 없음.
    // 주의(SG5-3): create_group은 이제 "그룹 안 카드에서 실행 → depth+1 중첩"이라(§9), A가 끝까지 뻗은 상태에서
    // t2에 create_group을 부르면 B가 A의 자식(depth 2)이 된다. 이 테스트는 **형제 그룹 통째 드래그**를 검증하므로
    // B의 group_depth를 1로 명시해 형제로 만든다(위치 파생 모델에서 첫 그룹 뒤 형제 최상위 그룹은 depth 힌트로 표현).
    session.createGroupAbsorbForTab(t0);
    session.createGroupAbsorbForTab(t2);
    t2.group_depth = 1; // B를 최상위 형제로(create_group 중첩 기본을 이 테스트 목적에 맞게 오버라이드)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // B 몸통

    // ── from>M 펼친 헤더 넣기: t3(그룹 B, index3)를 그룹 A 헤더(m=0)에 드롭 → A 최상단(마커 직후, to=m+1).
    {
        const from: usize = 3; // t3
        const target = session.sidebarGroupDropTargetTab(0, from).?; // 펼친 A 헤더 row0, m=0, from>m → to=m+1=1
        try std.testing.expectEqual(@as(usize, 1), target);
        _ = session.moveTab(from, target);
    }
    // 결과 [t0(mk A), t3, t1, t2(mk B)] — t3가 A로. A=[t0,t3,t1], B=[t2].
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t3, session.tabs.items[1]);
    try std.testing.expectEqual(t1, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // A로 넣기 성공

    // ── SG5-1: 마커 탭 카드 드래그 = **그룹 통째 이동**(옛 SG4 no-op을 대체). mouse로 t0(마커 A) 카드를 잡아 그룹 B
    //    카드(row 5) 위로 끌면 그룹 A 구간 전체가 B 뒤로 옮겨간다(연속 파티션 유지).
    session.recomputeVisibleTabs(); // rows: [header A(0), card t0(1), card t3(2), card t1(3), header B(4), card t2(5)]
    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const header_row_h = session.sidebar_header_row_h_px;
    const slot_h = session.sidebar_slot_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    // t0(마커 A) 카드 = row 1. row 상단 y = rowTop(rows,1,...). 그 중앙을 클릭해 드래그 arm.
    const marker_card_top = sb.rowTop(session.sidebar_rows.items, 1, header_h, slot_h, header_row_h, 0);
    const marker_card_y: f64 = @floatFromInt(marker_card_top + @as(i64, @intCast(slot_h / 2)));
    session.mouse(1, x, marker_card_y, 0, 0); // down → 마커 카드에서 드래그 arm
    try std.testing.expect(session.sidebar_drag_active);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_drag_index); // t0(마커 A) 잡음
    // 그룹 B 카드(row 5) 위로 드래그 → **SG8e 비커밋 프리뷰**(self.tabs 불변, subtree 고스트). 옛 라이브 재배치 대신
    // up이 마지막 plan(group_sibling)을 1회 커밋한다. 드롭 하이라이트(drop_slot)는 고스트+삽입선이 대체하므로 null.
    const groupb_card_top = sb.rowTop(session.sidebar_rows.items, 5, header_h, slot_h, header_row_h, 0);
    const groupb_card_y: f64 = @floatFromInt(groupb_card_top + @as(i64, @intCast(slot_h / 2)));
    var pre_grp: [8]*Tab = undefined; // 드래그 전 스냅샷(드래그 중 self.tabs 불변 확인)
    for (session.tabs.items, 0..) |t, i| pre_grp[i] = t;
    session.mouse(2, x, groupb_card_y, 0, 0);
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰 활성(subtree 고스트)
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(pre_grp[i], t); // 드래그 중 self.tabs 불변
    session.mouse(3, x, groupb_card_y, 0, 0); // up → 마지막 plan(group_sibling) 1회 커밋
    // 결과 [t2(mk B), t0(mk A), t3, t1] — 그룹 A 구간 전체가 B 뒤로. B=[t2], A=[t0,t3,t1](라이브 시절과 동일 = 등가).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[1]);
    try std.testing.expectEqual(t3, session.tabs.items[2]);
    try std.testing.expectEqual(t1, session.tabs.items[3]);
    try std.testing.expect(session.tabs.items[0].group_start != null); // B 마커(연속 파티션 유지)
    try std.testing.expect(session.tabs.items[1].group_start != null); // A 마커
    try std.testing.expect(session.tabs.items[2].group_start == null); // A 몸통
    try std.testing.expect(!session.sidebar_drag_active);
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨(원본 복귀)

    // ── SG8d 카드 드래그 고스트 프리뷰: 마커 없는 카드(t1, A 몸통)를 잡아 끌면 라이브 moveTab 대신 **비커밋 프리뷰**가
    // 뜬다(self.tabs 불변 + sidebar_drag_preview 존재 + preview_rows 고스트). up이 마지막 plan을 1회 커밋하고 프리뷰를 정리한다.
    // 현재 [t2(mk B), t0(mk A), t3, t1] → rows: [header B(0), card t2(1), header A(2), card t0(3), card t3(4), card t1(5)].
    // t1 카드 = row 5. 그 중앙을 down.
    session.recomputeVisibleTabs();
    const t1_card_top = sb.rowTop(session.sidebar_rows.items, 5, header_h, slot_h, header_row_h, 0);
    const t1_card_y: f64 = @floatFromInt(t1_card_top + @as(i64, @intCast(slot_h / 2)));
    // 드래그 전 self.tabs 스냅샷(드래그 중 불변 확인용).
    var pre_drag: [8]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| pre_drag[i] = t;
    session.mouse(1, x, t1_card_y, 0, 0);
    try std.testing.expect(session.sidebar_drag_active);
    try std.testing.expect(session.tabs.items[session.sidebar_drag_index].group_start == null); // 마커 아님(t1)
    // drag to some row → 프리뷰 활성(고스트) + 원본-도메인 drop_slot은 세팅 안 함(고스트+삽입선이 대체) + self.tabs 불변.
    session.mouse(2, x, @floatFromInt(header_h + slot_h + slot_h / 2), 0, 0);
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰 활성
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(pre_drag[i], t); // 드래그 중 self.tabs 불변
    session.mouse(3, x, @floatFromInt(header_h + slot_h + slot_h / 2), 0, 0); // up → 마지막 plan 1회 커밋 + 프리뷰 정리
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨(원본 복귀)
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_preview_rows.items.len);
    try std.testing.expect(!session.sidebar_drag_active);
}

test "GL1: stablePartitionSubtree — 로컬 pin 직접 멤버가 마커 직후로 float·자식 subgroup 통째 skip·경계 보존·드래그 게이트·no-op byte-identical" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // 최상위 그룹 A(마커 t0, depth1)와 그 **자식 subgroup** B(마커 t3, depth2). 위치 파생:
    //   [t0(mk A d1), t1(A 직접), t2(A 직접), t3(mk B d2), t4(B 멤버), t5(B 멤버)].
    // createGroupForTab(t3)는 t3가 A 멤버(depth1)라 자동 중첩 depth2 → B는 A의 자식. A subtree=[0,6), B subtree=[3,6).
    session.createGroupAbsorbForTab(t0);
    session.createGroupAbsorbForTab(t3);
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(0, null, null)); // A 전체
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B는 중첩 depth2
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6)

    // ── (a) no-op byte-identical: 로컬 pin 0개 → 재배열 없음(순서·active_tab 불변). GL1 회귀 0 안전망.
    var snap0: [6]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap0[i] = t;
    const active0 = session.app_window.active_tab;
    session.stablePartitionSubtree(0);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap0[i], t); // 순서 불변(byte-identical)
    try std.testing.expectEqual(active0, session.app_window.active_tab);

    // ── (b) 직접 멤버 로컬 pin float + 자식 subgroup 통째 skip. t2(A 직접 멤버, 첫째 아님)=로컬 pin,
    //    t5(B 멤버)=로컬 pin이지만 A의 직접 단위가 아니라(자식 subgroup 안) stablePartitionSubtree(0)에선 **안 뜬다**.
    t2.local_pinned = true;
    t5.local_pinned = true;
    session.stablePartitionSubtree(0);
    // 기대: [t0, t2(float), t1, t3(mk B), t4, t5] — t2가 마커 직후로, t1은 밀림, B subtree는 통째 유지(t5 제자리).
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 마커 A 앵커(제자리)
    try std.testing.expectEqual(t2, session.tabs.items[1]); // 로컬 pin 직접 멤버 → 마커 직후
    try std.testing.expectEqual(t1, session.tabs.items[2]); // 비-pin 직접 멤버 → 뒤로
    try std.testing.expectEqual(t3, session.tabs.items[3]); // B 마커(통째 skip — 자리 유지)
    try std.testing.expectEqual(t4, session.tabs.items[4]); // B 멤버
    try std.testing.expectEqual(t5, session.tabs.items[5]); // ★ B 멤버 로컬 pin은 A subtree float 대상 아님(자식 통째)
    // 경계·depth 보존(재배열이 subtree 안에서만 — I2/I3): A subtree·B subtree·B eff depth 불변.
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(0, null, null)); // A=[0,6) 유지
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B eff depth 2 유지
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6) 유지

    // ── (c) 자식 subtree 안 float은 그 자식 마커에 대해 **재귀** 호출(GL2 배선의 결) — heap-pin *Tab 재탐색으로 B 인덱스 얻음.
    var b_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == t3) {
        b_idx = i;
        break;
    };
    try std.testing.expectEqual(@as(usize, 3), b_idx); // B 마커 새 인덱스(재배열로 안 밀림 — A 직접 float만 있었음)
    session.stablePartitionSubtree(b_idx);
    // 기대: [t0, t2, t1, t3, t5(float), t4] — B subtree 안에서 t5가 B 마커 직후로.
    try std.testing.expectEqual(t3, session.tabs.items[3]); // B 마커 앵커
    try std.testing.expectEqual(t5, session.tabs.items[4]); // B 로컬 pin → B 마커 직후
    try std.testing.expectEqual(t4, session.tabs.items[5]); // B 비-pin 멤버 → 뒤로
    // A subtree 경계 여전히 [0,6) — 자식 재배열이 부모 밖으로 안 샘.
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(0, null, null));

    // ── (d) 드래그 게이트: sidebar_drag_preview 활성이면 float 안 함(SG8 self.tabs 불변). t1도 로컬 pin으로 만들지만 무시돼야.
    var snap_d: [6]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap_d[i] = t;
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = .none, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    t1.local_pinned = true; // 게이트가 없으면 t1이 float해 순서가 바뀔 상황
    session.stablePartitionSubtree(0);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap_d[i], t); // ★ 게이트로 순서 불변(드래그 중 float 금지)
    session.sidebar_drag_preview = null; // teardown
}

test "GL2(a): toggleLocalPin — 멤버가 마커 직후로 float·그룹 연속·활성 포인터 보존·재토글 원위치(인접 byte-identical)·최상위 no-op" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    session.createGroupAbsorbForTab(t0); // 그룹 [t0(마커), t1, t2, t3]
    session.app_window.active_tab = 3; // 활성 = t3(포인터 보존 검증용)

    // ── float: **마지막** 멤버 t3 로컬 pin → 마커 직후(index 1)로 stable float. 비-pin 멤버는 상대순서로 뒤에.
    session.toggleLocalPin(t3);
    try std.testing.expect(t3.local_pinned);
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 마커 앵커(제자리)
    try std.testing.expectEqual(t3, session.tabs.items[1]); // ★ 로컬 pin 멤버 = 마커 직후
    try std.testing.expectEqual(t1, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[3]);
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(0, null, null)); // ★ 그룹 연속 [0,4) 유지
    try std.testing.expectEqual(t3, session.tabs.items[session.app_window.active_tab]); // ★ 활성 *Tab 포인터 보존(인덱스 보정)

    // ── 재토글(off): 로컬 pin 해제. 전역 pinned는 직교(안 건드림) — 여전히 그룹 안(연속 유지).
    session.toggleLocalPin(t3);
    try std.testing.expect(!t3.local_pinned);
    try std.testing.expect(!t3.pinned); // ★ 전역 pin과 직교
    try std.testing.expectEqual(@as(usize, 4), session.groupSubtreeEnd(0, null, null));

    // ── 원위치(byte-identical round-trip): **마커 직후 인접 멤버**는 pin→unpin이 순서를 안 바꾼다(float 대상이 이미 그 자리).
    var snap: [4]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap[i] = t;
    const adj = session.tabs.items[1]; // 현재 마커 직후 멤버
    session.toggleLocalPin(adj); // pin → 이미 마커 직후라 float no-op
    session.toggleLocalPin(adj); // unpin → no-op
    try std.testing.expect(!adj.local_pinned);
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap[i], t); // ★ 원위치(byte-identical)

    // ── 최상위 카드 no-op: ungroup 후 그룹 미소속 카드는 enclosingGroupMarkerIndex=null → toggleLocalPin 무동작.
    session.ungroupTab(t0); // 전부 최상위
    session.toggleLocalPin(t1); // 최상위 → no-op(플래그도 안 세팅)
    try std.testing.expect(!t1.local_pinned);
}

test "GL2(c): 드래그 clamp — 로컬 pin 멤버가 subtree-로컬 프리픽스 밖으로 못 감(simulateDrop clamp = 프리뷰=확정, 비-pin은 무변경)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    session.createGroupAbsorbForTab(t0); // 그룹 [t0(마커), t1, t2, t3, t4]
    t1.local_pinned = true;
    t2.local_pinned = true;
    session.floatLocalPinsAllGroups(); // canonical: t1·t2 = 프리픽스 [1,3)(이미 그 자리라 no-op)

    // 프리픽스 경계 단위 단언: 로컬 pin leaf = [mi+1, mi+count] inclusive, 비-pin/마커 = null(clamp 무변경).
    try std.testing.expectEqual(@as(usize, 1), session.localPinPrefixBounds(1).?.lo);
    try std.testing.expectEqual(@as(usize, 2), session.localPinPrefixBounds(1).?.hi); // 프리픽스 [1,3) → 인덱스 1·2
    try std.testing.expect(session.localPinPrefixBounds(3) == null); // ★ 비-로컬-pin 멤버 → clamp 무변경
    try std.testing.expect(session.localPinPrefixBounds(0) == null); // 마커 → null

    // ── 프리뷰(simulateDrop): 로컬 pin t1(index 1)을 프리픽스 **밖(index 4)** 으로 드래그 → 프리픽스 끝(index 2)에 clamp.
    var before: [5]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const vl = try session.simulateDrop(1, .{ .card = .{ .target_tab = 4 } }, arena.allocator());
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변(SG8)
    try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 2, 1, 3, 4 }, vl.order); // ★ t1이 프리픽스 밖 못 가고 index 2에 clamp

    // ── 확정(commitSidebarDragPreview 재현: moveTab RAW target + normalize + floatLocalPins) == 프리뷰(re-partition-on-commit).
    _ = session.moveTab(1, 4); // RAW 프리픽스 밖 target — moveTab엔 로컬 clamp 없음(이동 함수 아님)
    session.normalizePinnedFromGroups();
    session.floatLocalPinsAllGroups(); // §13.5 snap-back
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[vl.order[i]], t); // ★ 프리뷰=확정
    try std.testing.expectEqual(t1, session.tabs.items[2]); // t1이 프리픽스 [1,3) 안(밖으로 못 감)
    try std.testing.expect(t1.local_pinned);
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(0, null, null)); // 그룹 연속 유지

    // ── 대조(비-로컬-pin 무변경): t3(비-pin, index 3)을 t4(index 4)로 드래그 = 자유 swap(프리픽스 밖이라 float 무간섭).
    var before2: [5]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before2[i] = t; // 현재 [t0,t2,t1,t3,t4]
    var arena2 = std.heap.ArenaAllocator.init(allocator);
    defer arena2.deinit();
    const vl2 = try session.simulateDrop(3, .{ .card = .{ .target_tab = 4 } }, arena2.allocator());
    try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 1, 2, 4, 3 }, vl2.order); // clamp 무적용 — t3↔t4 자유 swap
    _ = session.moveTab(3, 4);
    session.normalizePinnedFromGroups();
    session.floatLocalPinsAllGroups();
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before2[vl2.order[i]], t); // 프리뷰=확정(비-pin도 프리픽스 밖이라 일치)
}

// GL3(그룹-로컬 pin 렌더 📌 + 위생 + 드래그 프리뷰=확정 엣지 — docs/sidebar-groups.md §13.6·§13.7). 문서 §13.10은 render+
// 위생을 GL4로 라벨하지만, 이 작업은 GL3로 통합해 구현한다. 스크린샷(MARU_FORCE_GROUP_LOCALPIN)은 시각 마감 1급 검증으로 별도.
test "GL3(a): 렌더 📌 — 로컬 pin 멤버 sidebarRowShowsPin=true·비pin 멤버 억제(pin_derived 직교)·마커/최상위 억제(§13.6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t3 = session.tabs.items[3];

    session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3, t4] — t0는 최상위 카드
    session.toggleLocalPin(t3); // t3 로컬 pin → 마커 t1 직후(그룹 내 상단)로 float
    try std.testing.expectEqual(t3, session.tabs.items[2]); // ★ float: 마커(index1) 직후 index2로

    session.recomputeVisibleTabs();
    // 표시 rows(GL §13.6.1 — 로컬 pin이 그룹 **절대 최상단**, 마커 자기 카드는 그 **아래**):
    //   [card t0, header A, card t3(로컬 pin), card t1(마커카드), card t2, card t4]
    const rows = session.sidebar_rows.items;
    try std.testing.expectEqual(@as(usize, 6), rows.len);

    // ── ★ row 순서(§13.6.1): 로컬 pin 멤버 t3 카드가 마커 자기 카드(t1)보다 **앞**. 각 row.tab은 실제 tab index 그대로 ──
    try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // t3(로컬 pin) = self.tabs index 2 — 마커 직후로 float
    try std.testing.expectEqual(@as(usize, 1), rows[3].card.tab); // t1(마커 자기 카드) = index 1 — 로컬 pin **뒤**로 재배치

    // ── local_pinned 힌트(§13.6): 로컬 pin 멤버 카드만 true. 마커 카드·최상위 카드·비pin 멤버=false ──
    try std.testing.expect(!rows[0].card.local_pinned); // t0 최상위 카드
    try std.testing.expect(rows[2].card.local_pinned); // ★ t3 로컬 pin 멤버(절대 최상단)
    try std.testing.expect(!rows[3].card.local_pinned); // A 마커 자기 카드(§13.8 — 마커 로컬 pin은 GL5, 이제 로컬 pin 뒤)
    try std.testing.expect(!rows[4].card.local_pinned); // t2 비pin 멤버
    try std.testing.expect(!rows[5].card.local_pinned); // t4 비pin 멤버
    // pin_derived와 **직교**: 로컬 pin 멤버(t3)도 depth>0이라 pin_derived=true지만 local_pinned가 선두 분기로 우선한다.
    try std.testing.expect(rows[2].card.pin_derived); // t3도 멤버 파생 캐시 힌트 = true
    try std.testing.expect(rows[4].card.pin_derived); // t2 멤버(비pin) = true

    // ── sidebarRowShowsPin(§13.6 선두 분기): 로컬 pin 멤버만 📌. 비pin 멤버·마커·헤더·최상위(비고정)는 억제 ──
    try std.testing.expect(session.sidebarRowShowsPin(rows[2])); // ★ 로컬 pin 멤버 t3 → 📌(pin_derived 억제 우회)
    // (d) GP4(a) 회귀: pin_derived=true여도 local_pinned=false면 여전히 억제(멤버 📌 노이즈 0). 조건부화 검증.
    try std.testing.expect(!session.sidebarRowShowsPin(rows[4])); // t2 비pin 멤버 → 억제(pin_derived)
    try std.testing.expect(!session.sidebarRowShowsPin(rows[5])); // t4 비pin 멤버 → 억제
    try std.testing.expect(!session.sidebarRowShowsPin(rows[3])); // A 마커 카드 → 억제(헤더가 인디케이터)
    try std.testing.expect(!session.sidebarRowShowsPin(rows[1])); // A 헤더(그룹째 고정 아님) → 인디케이터 없음
    try std.testing.expect(!session.sidebarRowShowsPin(rows[0])); // t0 최상위(비고정) → 없음

    // 종합: 카드 📌는 로컬 pin 멤버(t3) 하나뿐, 헤더 📌는 0(그룹째 고정 없음).
    var card_pins: usize = 0;
    var header_pins: usize = 0;
    for (rows) |r| switch (r) {
        .card => if (session.sidebarRowShowsPin(r)) {
            card_pins += 1;
        },
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 1), card_pins); // 로컬 pin 멤버 t3만
    try std.testing.expectEqual(@as(usize, 0), header_pins);
    _ = t0;
}

test "GL3(a2): 공존 렌더 — 그룹째 고정 그룹 안 로컬 pin 멤버 = 헤더 그룹📌 + 멤버 로컬📌(단일 글리프 U+1F4CC 수용, §13.6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t1 = session.tabs.items[1];
    const t3 = session.tabs.items[3];

    session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3, t4]
    session.toggleLocalPin(t3); // t3 로컬 pin → 마커 직후
    session.toggleGroupPin(t1); // A를 그룹째 고정(전역 프리픽스 안착 — keystone §13.1로 subtree 내 float 순서 보존)
    // t3은 여전히 마커 직후(그룹 내 상단)이고 local_pinned 유지(그룹째 고정과 직교).
    try std.testing.expect(t3.local_pinned);
    try std.testing.expect(t1.pinned); // 그룹째 고정 = 마커 pinned

    session.recomputeVisibleTabs();
    // A가 프리픽스로 이동(t0 비고정보다 앞). GL §13.6.1로 로컬 pin이 마커 카드 위:
    //   rows: [header A, card t3(로컬 pin), card t1(마커), card t2, card t4, card t0]
    const rows = session.sidebar_rows.items;
    var header_pins: usize = 0;
    var member_pins: usize = 0;
    for (rows) |r| switch (r) {
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
        .card => |c| if (session.sidebarRowShowsPin(r)) {
            if (c.local_pinned) member_pins += 1; // 로컬 pin 멤버 카드 📌
        },
    };
    try std.testing.expectEqual(@as(usize, 1), header_pins); // ★ 그룹째 고정 헤더 인디케이터 📌
    try std.testing.expectEqual(@as(usize, 1), member_pins); // ★ 그 안 로컬 pin 멤버 카드 📌(공존 — 위치로 구별)
}

// GL §13.6.1 — 마커 자기 카드를 그룹의 로컬 pin 직접 멤버 **뒤**로 렌더(로컬 pin = 그룹 절대 최상단). projectRowsCore가
// 마커 카드 row를 버퍼링했다 로컬 pin run 뒤에 방출한다. 검증: (1) sidebar_rows 순서·row.tab·hit-test, (2) 로컬 pin 0개면
// byte-identical(마커 첫 카드), (3) 로컬 pin 멤버 드래그 프리뷰=확정, (4) 그룹 통째 드래그 프리뷰=확정 + 고스트 range가
// 재배치된 마커 카드까지 이어짐.
test "GL3(d): 마커 카드 로컬 pin 뒤 렌더(§13.6.1) — 순서·hit-test·byte-identical(0개)·프리뷰=확정" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const init_opts = SessionConfig{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    };

    // ── (1) 순서 + hit-test: 로컬 pin 멤버 카드가 마커 자기 카드보다 앞. 각 row.tab은 실제 tab index 그대로 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커=idx1), t2, t3, t4]
        session.toggleLocalPin(t3); // t3 → idx2(마커 직후로 float)
        try std.testing.expectEqual(t3, session.tabs.items[2]);
        session.recomputeVisibleTabs();
        const rows = session.sidebar_rows.items;
        // rows: [card t0, header A, card t3(로컬 pin, idx2), card t1(마커, idx1), card t2(idx3), card t4(idx4)]
        try std.testing.expectEqual(@as(usize, 6), rows.len);
        try std.testing.expect(rows[1] == .group_header);
        try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // ★ 로컬 pin t3 — 그룹 절대 최상단(헤더 직후)
        try std.testing.expectEqual(@as(usize, 1), rows[3].card.tab); // ★ 마커 자기 카드 — 로컬 pin 뒤
        // hit-test 정합: 마커 카드 row(slot 3) 클릭 → 마커 tab(1)이라 마커 워크스페이스 활성. 로컬 pin row(slot 2) → t3.
        try std.testing.expectEqual(@as(usize, 1), session.visibleTab(3).?); // ★ 마커 카드 slot → 마커 tab(클릭 정합)
        try std.testing.expectEqual(@as(usize, 2), session.visibleTab(2).?); // 로컬 pin slot → t3
        try std.testing.expectEqual(@as(?usize, 3), session.displaySlotOf(1)); // 마커 tab → slot 3(역방향 정합)
        try std.testing.expectEqual(@as(?usize, 2), session.displaySlotOf(2)); // t3 → slot 2
    }

    // ── (2) 로컬 pin 0개면 byte-identical — 마커 카드가 여전히 헤더 직후(첫 카드) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t1 = session.tabs.items[1];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3] — 로컬 pin 0개
        session.recomputeVisibleTabs();
        const rows = session.sidebar_rows.items;
        // rows: [card t0, header A, card t1(마커=첫 카드), card t2, card t3]
        try std.testing.expectEqual(@as(usize, 5), rows.len);
        try std.testing.expect(rows[1] == .group_header);
        try std.testing.expectEqual(@as(usize, 1), rows[2].card.tab); // ★ 마커 카드 = 헤더 직후 첫 카드(byte-identical)
        try std.testing.expectEqual(@as(usize, 2), rows[3].card.tab);
        try std.testing.expectEqual(@as(usize, 3), rows[4].card.tab);
    }

    // ── (3) 로컬 pin 멤버 드래그: 프리뷰=확정. `Row.card.tab`은 self.tabs **인덱스**(id 아님)라, 프리뷰(self.tabs 불변)와
    //    확정(self.tabs 재배열) 인덱스는 좌표계가 다르다 → 각 카드 row가 가리키는 **실제 *Tab 포인터**로 순서를 비교한다. ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
        const t1 = session.tabs.items[1];
        const t2 = session.tabs.items[2];
        const t3 = session.tabs.items[3];
        const t0 = session.tabs.items[0];
        const t4 = session.tabs.items[4];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커=idx1), t2, t3, t4]
        t2.local_pinned = true;
        t3.local_pinned = true;
        session.floatLocalPinsAllGroups(); // canonical: t2·t3 = 프리픽스 [2,4)(이미 그 자리)
        var pre: [8]*Tab = undefined; // 드래그 중 불변인 pre-move self.tabs 스냅샷(프리뷰 .tab 역참조용)
        for (session.tabs.items, 0..) |t, i| pre[i] = t;
        // 로컬 pin t2(origin idx2)를 t4(idx4) 위로 드래그 → 프리픽스 끝(idx3)에 clamp(프리픽스 밖 못 감).
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        try session.refreshDragPreview(2, .{ .card = .{ .target_tab = 4 } }, 0, arena.allocator());
        var preview_ptrs: [8]*Tab = undefined;
        var pn: usize = 0;
        for (session.sidebar_preview_rows.items) |r| switch (r) {
            .card => |c| {
                preview_ptrs[pn] = pre[c.tab]; // 프리뷰 .tab = pre-move self.tabs 인덱스
                pn += 1;
            },
            .group_header => {},
        };
        // preview 시각 순서: [t0, header, t3(lp), t2(lp, 드래그), 마커, t4] — 마커 카드가 두 로컬 pin **뒤**.
        try std.testing.expectEqual(@as(usize, 5), pn);
        try std.testing.expectEqual(t0, preview_ptrs[0]);
        try std.testing.expectEqual(t3, preview_ptrs[1]); // 로컬 pin(t2와 swap됐지만 여전히 마커 앞)
        try std.testing.expectEqual(t2, preview_ptrs[2]); // 로컬 pin(드래그된 것)
        try std.testing.expectEqual(t1, preview_ptrs[3]); // ★ 마커 자기 카드 — 로컬 pin 뒤
        try std.testing.expectEqual(t4, preview_ptrs[4]);
        session.commitSidebarDragPreview(); // 확정(clamp→moveTab→float→sweep→rebuild)
        var commit_ptrs: [8]*Tab = undefined;
        var cn: usize = 0;
        for (session.sidebar_rows.items) |r| switch (r) {
            .card => |c| {
                commit_ptrs[cn] = session.tabs.items[c.tab]; // 확정 .tab = post-move self.tabs 인덱스
                cn += 1;
            },
            .group_header => {},
        };
        try std.testing.expectEqual(pn, cn);
        try std.testing.expectEqualSlices(*Tab, preview_ptrs[0..pn], commit_ptrs[0..cn]); // ★ 프리뷰=확정(같은 Tab 순서)
    }

    // ── (4) 그룹 통째 드래그(마커 카드=그룹 이동): 프리뷰=확정 + 고스트 range가 재배치된 마커 카드까지 이어짐 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t0 = session.tabs.items[0];
        const t1 = session.tabs.items[1];
        const t2 = session.tabs.items[2];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커=idx1), t2, t3] — t0 최상위
        t2.local_pinned = true;
        session.floatLocalPinsAllGroups(); // A = [마커, t2(lp), t3]
        var pre: [8]*Tab = undefined;
        for (session.tabs.items, 0..) |t, i| pre[i] = t;
        // 그룹 A(마커 idx1)를 **최상위(insert_before=0)** 로 통째 이동 — 마커 카드 드래그(SG5)와 같은 코어.
        var arena = std.heap.ArenaAllocator.init(allocator);
        defer arena.deinit();
        try session.refreshDragPreview(1, .{ .group_sibling = .{ .insert_before = 0 } }, 0, arena.allocator());
        var preview_ptrs: [8]*Tab = undefined;
        var pn: usize = 0;
        for (session.sidebar_preview_rows.items) |r| switch (r) {
            .card => |c| {
                preview_ptrs[pn] = pre[c.tab];
                pn += 1;
            },
            .group_header => {},
        };
        // preview 시각 순서: [header, t2(lp), 마커, t3, t0] — A가 앞으로, 그 안 t2(lp)가 마커 위.
        try std.testing.expectEqual(@as(usize, 4), pn);
        try std.testing.expectEqual(t2, preview_ptrs[0]); // 로컬 pin
        try std.testing.expectEqual(t1, preview_ptrs[1]); // ★ 마커 자기 카드 — 로컬 pin 뒤
        try std.testing.expectEqual(t3, preview_ptrs[2]); // 비pin 멤버
        try std.testing.expectEqual(t0, preview_ptrs[3]); // 최상위(그룹 밖)
        // 고스트 range(표시-row 도메인)는 옮겨진 A 전체 = header(0)·t2(1)·마커카드(2)·t3(3) → [0,4). 재배치된 마커 카드
        // (row 2)가 range 안이라 그룹 통째 고스트에 마커 카드가 빠지지 않는다(flushMarkerCard의 ghost range 확장 검증).
        try std.testing.expectEqual(@as(usize, 0), session.sidebar_drag_preview.?.ghost_lo);
        try std.testing.expectEqual(@as(usize, 4), session.sidebar_drag_preview.?.ghost_hi);
        session.commitSidebarDragPreview();
        var commit_ptrs: [8]*Tab = undefined;
        var cn: usize = 0;
        for (session.sidebar_rows.items) |r| switch (r) {
            .card => |c| {
                commit_ptrs[cn] = session.tabs.items[c.tab];
                cn += 1;
            },
            .group_header => {},
        };
        try std.testing.expectEqual(pn, cn);
        try std.testing.expectEqualSlices(*Tab, preview_ptrs[0..pn], commit_ptrs[0..cn]); // ★ 프리뷰=확정(그룹 드래그)
    }
}

// GL3(b) 위생(§13.7) — 멤버→top-level 전이 3경로에서 local_pinned:=false(고아 📌 방지). 각 전이를 독립 세션으로 검증한다
// (closeTab은 마지막 탭에서 창 닫기 latch라 재사용 teardown이 불가 — 세션 분리가 정직).
test "GL3(b1): 위생 ungroup — 로컬 pin 멤버가 그룹 해제로 top-level 전이 시 local_pinned:=false(§13.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    session.createGroupAbsorbForTab(t0); // A = [t0(마커), t1, t2]
    session.toggleLocalPin(t1);
    try std.testing.expect(t1.local_pinned);
    session.ungroupTab(t1); // A 해제 → t0·t1·t2 전부 top-level
    try std.testing.expect(!t1.local_pinned); // ★ 위생: top-level 전이 → 클리어
    try std.testing.expect(!session.tabIsInGroup(t1));
}

test "GL3(b2): 위생 removeFromGroup — 빠진 로컬 pin 멤버만 클리어·남은 그룹 멤버는 로컬 pin 유지(§13.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    session.createGroupAbsorbForTab(t0); // A = [t0(마커), t1, t2]
    session.toggleLocalPin(t1);
    session.toggleLocalPin(t2); // t1·t2 둘 다 로컬 pin
    try std.testing.expect(t1.local_pinned and t2.local_pinned);
    session.removeFromGroupForTab(t1); // t1만 빼기 → top-level
    try std.testing.expect(!t1.local_pinned); // ★ 빠진 카드 = 클리어
    try std.testing.expect(!session.tabIsInGroup(t1));
    try std.testing.expect(t2.local_pinned); // ★ 남은 그룹 멤버 t2는 로컬 pin 유지(밖으로 안 나감)
    try std.testing.expect(session.tabIsInGroup(t2));
}

test "GL3(b3): 위생 드래그 out — commitSidebarDragPreview 스윕이 top-level 카드 stale local_pinned 클리어·멤버 보존(§13.7)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    // commit clamp가 로컬 pin **멤버**의 실제 그룹 밖 eject를 막으므로(§13.5, GL3(c)), 이 스윕은 top-level 전이한 카드의
    // desync/잔재 local_pinned를 지우는 **불변식 net**이다(§13.7 "그룹 밖으로 나가면"의 commit 지점). 그룹 멤버 로컬 pin은 보존.
    inline for (0..3) |_| _ = try session.newTab(); // [c0, c1, t2, t3]
    const c0 = session.tabs.items[0];
    session.createGroupAbsorbForTab(session.tabs.items[2]); // A = [t2(마커), t3] — c0·c1 최상위 카드
    const t3 = session.tabs.items[3];
    session.toggleLocalPin(t3); // 진짜 그룹 멤버 로컬 pin(보존 대상)
    c0.local_pinned = true; // stale: top-level 카드에 남은 로컬 pin(전이 잔재 시뮬레이션)
    // c0(top-level, origin=0)을 c1(index1)로 드래그 = top-level↔top-level. commit이 위생 스윕으로 c0 stale 클리어.
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = .{ .card = .{ .target_tab = 1 } }, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    try std.testing.expect(!c0.local_pinned); // ★ top-level 카드 stale local_pinned 스윕(고아 📌 방지)
    try std.testing.expect(t3.local_pinned); // ★ 진짜 그룹 멤버 로컬 pin은 보존
}

test "GL3(b4): 위생 create group — 로컬 pin 멤버로 그룹 생성 시 마커 local_pinned=0 + break_next top카드도 스윕(§13.7·leaf-only)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
    session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[Gm=t0, m1=t1, m2=t2]
    const m1 = session.tabs.items[1];
    const m2 = session.tabs.items[2];
    session.toggleLocalPin(m1); // m1 로컬 pin(leaf 멤버 — float은 이미 마커 직후라 제자리)
    session.toggleLocalPin(m2); // m2 로컬 pin
    try std.testing.expect(m1.local_pinned and m2.local_pinned); // 사전: 둘 다 leaf 로컬 pin

    // m1로 (중첩) 그룹 생성 → m1은 마커(leaf 아님), break_next가 다음 카드 m2에 top_level write(그룹 밖 leaf 아님).
    session.createGroupForTab(m1);
    try std.testing.expect(m1.group_start != null); // m1이 새 마커
    try std.testing.expect(!m1.local_pinned); // ★ 마커 전이 → local_pinned 클리어(leaf-only §13.8, revert하면 true로 실패)
    try std.testing.expect(m2.top_level); // break_next로 m2 = 그룹 밖 top카드
    try std.testing.expect(!m2.local_pinned); // ★ top-level 전이 카드 stale local_pinned 스윕(clearStaleLocalPins)
}

test "GL3(c): 드래그 엣지 — 로컬 pin 멤버를 마커 자기 카드 위로 드래그해도 프리뷰=확정(commit clamp, eject 없음, §13.5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    session.createGroupAbsorbForTab(t1); // A = [t1(마커, index1), t2, t3, t4] — t0 최상위
    t2.local_pinned = true;
    const t3 = session.tabs.items[3];
    t3.local_pinned = true;
    session.floatLocalPinsAllGroups(); // canonical: t2·t3 = 프리픽스 [2,4)(이미 그 자리라 no-op)
    // 프리픽스 경계: 로컬 pin leaf t2(index2) → [mi+1, mi+count] = [2,3].
    try std.testing.expectEqual(@as(usize, 2), session.localPinPrefixBounds(2).?.lo);
    try std.testing.expectEqual(@as(usize, 3), session.localPinPrefixBounds(2).?.hi);

    // ── 마커 자기 카드(index1) 위로 t2(origin=2, 로컬 pin) 드래그 → 프리픽스 시작(index2)에 clamp(마커 앞 eject 금지).
    var before: [5]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| before[i] = t;
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const plan: AppSession.DropPlan = .{ .card = .{ .target_tab = 1 } }; // 마커 카드 = index1
    const vl = try session.simulateDrop(2, plan, arena.allocator());
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[i], t); // self.tabs 불변(SG8)
    try std.testing.expectEqualSlices(usize, &[_]usize{ 0, 1, 2, 3, 4 }, vl.order); // 프리뷰: t2가 마커 앞 못 가고 index2 유지

    // ── 확정: **실제 commitSidebarDragPreview 경로**(commit clamp 포함). raw moveTab이면 t2가 마커(index1) 앞으로 eject됐을 것.
    session.sidebar_drag_preview = .{ .origin = 2, .origin_len = 1, .plan = plan, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(before[vl.order[i]], t); // ★ 프리뷰=확정(eject 없음)
    try std.testing.expectEqual(t2, session.tabs.items[2]); // t2가 그룹 안(마커 직후) 유지 — top-level로 안 샘
    try std.testing.expect(t2.local_pinned); // 로컬 pin 유지(그룹 안 이동은 해제 아님)
    try std.testing.expect(session.tabIsInGroup(t2));
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(1, null, null)); // 그룹 A=[1,5) 연속 유지
}

// GL4(a) — 공존(그룹째 고정 C2 × 그룹-로컬 pin GL)의 keystone 보조정리 실증(docs/sidebar-groups.md §13.1·§13.4). 그룹째
// 고정은 그룹 subtree를 **전역 [고정][비고정] 프리픽스**로 통째 옮기고(stablePartitionPinned), 그 안 로컬 pin float는
// **마커 직후**를 유지해야 한다. keystone: stablePartitionPinned는 pin-uniform 블록의 **내부 상대순서를 보존**(stable)하므로
// subtree 축 위에서 무연산 → 로컬 float가 살아남는다. 배선 순서(§13.4): (1)normalize→(2)stablePartitionPinned→(3)float가
// 항상 이 순서라, 전역 프리픽스 안착과 subtree float가 서로를 안 흩뜨린다. 비고정 최상위 카드 t0를 둬 **전역 partition이
// 실제로 그룹을 옮기게**(t0가 뒤로 밀림) 만들어 keystone을 눈에 보이게 검증한다.
test "GL4(a): 공존 keystone — 그룹째 고정이 로컬 pin 그룹을 전역 프리픽스로 옮겨도 subtree 로컬 float 보존·배선 순서·재토글·idempotent·렌더" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    session.createGroupAbsorbForTab(t1); // A = [t1(마커 d1), t2, t3, t4, t5] — t0는 **비고정 최상위 카드**(전역 partition의 대조)
    // 두 멤버(t4·t5)를 로컬 pin → 마커 직후로 float(상대순서 t4,t5 유지). 그룹 안 상단 프리픽스 [1,3) = t4·t5.
    session.toggleLocalPin(t4);
    session.toggleLocalPin(t5);
    try std.testing.expectEqual(t4, session.tabs.items[2]); // t4 = 마커 직후
    try std.testing.expectEqual(t5, session.tabs.items[3]); // t5 = 그 다음(로컬 float 상대순서)

    // ── ★ keystone: A를 그룹째 고정. stablePartitionPinned가 pinned 블록[t1,t4,t5,t2,t3]을 프리픽스로 옮기고 t0(비고정)를
    //    뒤로 민다. 블록 **내부 순서 보존**이라 t4·t5가 여전히 마커 직후. float((3)단계)는 이미 그 자리라 no-op.
    session.toggleGroupPin(t1);
    try std.testing.expectEqual(t1, session.tabs.items[0]); // 그룹 마커 = 전역 프리픽스 선두(그룹이 앞으로 이동)
    try std.testing.expectEqual(t4, session.tabs.items[1]); // ★ 로컬 pin float 보존(마커 직후) — keystone
    try std.testing.expectEqual(t5, session.tabs.items[2]); // ★ 로컬 pin float 상대순서 보존
    try std.testing.expectEqual(t2, session.tabs.items[3]); // 비-로컬-pin 멤버
    try std.testing.expectEqual(t3, session.tabs.items[4]);
    try std.testing.expectEqual(t0, session.tabs.items[5]); // ★ 비고정 최상위 카드 = 뒤로 밀림(전역 partition이 실제로 옮김)
    // 축 직교: 그룹째 고정(마커 pinned)과 로컬 pin(local_pinned)이 **다른 비트**로 공존.
    try std.testing.expect(t1.pinned); // 그룹째 고정 = 마커 pinned(권위)
    try std.testing.expect(t4.pinned and t4.local_pinned); // 멤버 = 파생 pinned 캐시 + 로컬 pin(둘 다)
    try std.testing.expect(t5.pinned and t5.local_pinned);
    try std.testing.expect(!t0.pinned); // 비고정 카드
    try std.testing.expectEqual(@as(usize, 5), session.groupSubtreeEnd(0, null, null)); // A=[0,5) 통째 고정 프리픽스

    // ── idempotent(배선 표준 순서 재실행이 안정): normalize→partition→float를 한 번 더 돌려도 순서 불변.
    var snap: [6]*Tab = undefined;
    for (session.tabs.items, 0..) |t, i| snap[i] = t;
    session.normalizePinnedFromGroups();
    session.stablePartitionPinned();
    session.floatLocalPinsAllGroups();
    for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap[i], t); // ★ idempotent(공존 canonical 고정점)

    // ── 렌더(§13.6): 헤더 그룹📌 + 로컬 pin 멤버 카드 📌(마커 카드 위). 위치로 구별(단일 글리프 U+1F4CC 수용).
    session.recomputeVisibleTabs();
    const rows = session.sidebar_rows.items;
    // rows: [header A(📌), card t4(lp,📌), card t5(lp,📌), card t1(마커카드), card t2, card t3, card t0]
    try std.testing.expectEqual(@as(usize, 7), rows.len);
    try std.testing.expect(rows[0] == .group_header);
    try std.testing.expectEqual(@as(usize, 1), rows[1].card.tab); // t4 = self.tabs index1(마커 직후)
    try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // t5
    try std.testing.expectEqual(@as(usize, 0), rows[3].card.tab); // ★ A 마커 자기 카드(index0) = 로컬 pin **뒤**
    try std.testing.expect(session.sidebarRowShowsPin(rows[0])); // ★ 그룹째 고정 헤더 인디케이터 📌
    try std.testing.expect(session.sidebarRowShowsPin(rows[1])); // ★ 로컬 pin 멤버 t4 📌
    try std.testing.expect(session.sidebarRowShowsPin(rows[2])); // ★ 로컬 pin 멤버 t5 📌
    try std.testing.expect(!session.sidebarRowShowsPin(rows[3])); // 마커 카드 억제(헤더가 인디케이터)
    var header_pins: usize = 0;
    var member_pins: usize = 0;
    for (rows) |r| switch (r) {
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
        .card => |c| if (session.sidebarRowShowsPin(r)) {
            if (c.local_pinned) member_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 1), header_pins); // 그룹째 고정 헤더 하나
    try std.testing.expectEqual(@as(usize, 2), member_pins); // 로컬 pin 멤버 둘

    // ── 재토글(그룹째 고정 해제 = 그룹 리셋): 멤버의 로컬 pin도 **함께 클리어**된다(사용자 리포트 버그2 — §13.1 리셋
    //    시맨틱). 로컬 pin은 그룹째 고정과 직교라 **고정 켜는 동안엔 보존**(위 keystone)하되, **끄는 순간** 그룹을 깨끗한
    //    멤버 상태로 되돌려 자식이 개별 📌로 남지 않게 한다. self.tabs 위치는 float된 자리(마커 직후)에 그대로 남되(재배열
    //    안 함) local_pinned=false·📌 억제로 "그냥 그룹 멤버"가 된다.
    session.toggleGroupPin(t1);
    try std.testing.expect(!t1.pinned); // 그룹째 고정 해제
    try std.testing.expect(!t4.pinned and !t5.pinned); // 멤버 파생 캐시도 해제
    try std.testing.expect(!t4.local_pinned and !t5.local_pinned); // ★ 그룹 해제 = 로컬 pin 리셋(개별 📌 제거, 버그2)
    try std.testing.expectEqual(t4, session.tabs.items[1]); // 위치는 float된 자리에 남음(재배열 없음 — 데이터만 클리어)
    try std.testing.expectEqual(t5, session.tabs.items[2]);
    // C2 그룹째 고정/해제는 top-card 위치의 완전 round-trip이 **아니다**(GL과 직교): 고정 때 프리픽스로 옮기며 비고정 t0를
    // 뒤로 밀었고(위), 해제하면 t0가 그룹 A 꼬리에 남아 위치 파생상 A로 흡수된다(A=[0,6)). 이는 C2(§12) 성질이다.
    // 로컬 pin 멤버(였던 t4·t5)는 여전히 A 소속(위치 파생)이고, 이제 📌 없는 평범한 멤버다.
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(1).?); // t4의 enclosing 마커 = t1(index0)
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(2).?); // t5의 enclosing 마커 = t1
    // ★ 렌더 확인: 해제 후 어떤 멤버 카드도 📌를 안 그린다(개별 📌 0 — 버그2 desired outcome).
    session.recomputeVisibleTabs();
    var member_pins_after: usize = 0;
    for (session.sidebar_rows.items) |r| switch (r) {
        .card => if (session.sidebarRowShowsPin(r)) {
            member_pins_after += 1;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(usize, 0), member_pins_after); // 해제 후 카드 📌 0(그냥 그룹 멤버)
}

// GL4(b) — 중첩(자식 subgroup 안 leaf 멤버 로컬 pin)의 하드닝(docs/sidebar-groups.md §13.3·§13.6.1·§13.8). `floatLocalPinsAllGroups`
// 가 부모→자식 **순차 스캔**(= 포인터 재탐색 동형, §13.4)으로 부모 A·자식 B 두 subtree를 각자 float하고, 마커 위 배치가
// 자식 그룹서도 성립(자식 마커 카드 위로 자식 로컬 pin)하며 I3(중첩 depth)이 보존됨을 검증한다. **subgroup-as-member는 범위
// 밖(GL5)** — 여기선 leaf 멤버만.
test "GL4(b): 중첩 — 자식 subgroup 안 leaf 로컬 pin float(부모→자식 순차)·자식 마커 카드 위 배치·I3 depth 보존" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // 2단계 중첩: A(마커 t1, d1) ⊃ [t2(A 직접), B(마커 t3, d2) ⊃ [t4, t5]]. t0는 최상위 카드.
    session.createGroupAbsorbForTab(t1); // A = [t1, t2, t3, t4, t5]
    session.createGroupAbsorbForTab(t3); // t3은 A 안 카드(d1) → 자식 B(d2) 흡수 t4·t5. A 직접 = t2.
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(1, null, null)); // A=[1,6)
    try std.testing.expectEqual(@as(u8, 1), session.effectiveDepthAt(1, null, null)); // A d1
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B d2(중첩)
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6)

    // A 직접 멤버 t2·자식 B leaf 멤버 t5를 로컬 pin(직접 필드 세팅 후 **floatLocalPinsAllGroups 한 번**으로 순차 스캔 검증).
    t2.local_pinned = true;
    t5.local_pinned = true;
    session.floatLocalPinsAllGroups(); // i=1(A)→A subtree float(t2 이미 마커 직후=no-op), i=3(B)→B subtree float(t5→B 마커 직후)
    // 기대 물리 순서: [t0, t1(A마커), t2(A lp), t3(B마커), t5(B lp), t4] — 부모·자식 둘 다 각자 마커 직후로 float.
    try std.testing.expectEqual(t0, session.tabs.items[0]); // 최상위 카드
    try std.testing.expectEqual(t1, session.tabs.items[1]); // A 마커 앵커
    try std.testing.expectEqual(t2, session.tabs.items[2]); // ★ A 직접 로컬 pin = A 마커 직후
    try std.testing.expectEqual(t3, session.tabs.items[3]); // B 마커(자식 subgroup 통째 — 부모 float서 안 쪼개짐)
    try std.testing.expectEqual(t5, session.tabs.items[4]); // ★ 자식 B leaf 로컬 pin = B 마커 직후(자식 subtree 안 float)
    try std.testing.expectEqual(t4, session.tabs.items[5]); // B 비-pin 멤버 → 뒤로
    // ── I3 보존: 자식 float이 부모 밖으로 안 새고 중첩 depth·subtree 경계 불변 ──
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(1, null, null)); // A=[1,6) 유지
    try std.testing.expectEqual(@as(usize, 6), session.groupSubtreeEnd(3, null, null)); // B=[3,6) 유지
    try std.testing.expectEqual(@as(u8, 1), session.effectiveDepthAt(1, null, null)); // A d1
    try std.testing.expectEqual(@as(u8, 2), session.effectiveDepthAt(3, null, null)); // B d2

    // ── 렌더(§13.6.1 재귀 동형): 각 마커 카드가 **자기 그룹의 로컬 pin 뒤**. 부모 A 카드·자식 B 카드 모두 로컬 pin 아래 ──
    session.recomputeVisibleTabs();
    const rows = session.sidebar_rows.items;
    // rows: [card t0, header A, card t2(A lp), card t1(A마커카드), header B, card t5(B lp), card t3(B마커카드), card t4]
    try std.testing.expectEqual(@as(usize, 8), rows.len);
    try std.testing.expectEqual(@as(usize, 0), rows[0].card.tab); // t0 최상위(d0)
    try std.testing.expect(rows[1] == .group_header); // A 헤더(d1)
    try std.testing.expectEqual(@as(u8, 1), rows[1].group_header.depth);
    try std.testing.expectEqual(@as(usize, 2), rows[2].card.tab); // ★ A 직접 로컬 pin t2(마커 카드 위)
    try std.testing.expect(rows[2].card.local_pinned);
    try std.testing.expectEqual(@as(u8, 1), rows[2].card.depth); // A depth
    try std.testing.expectEqual(@as(usize, 1), rows[3].card.tab); // A 마커 자기 카드(로컬 pin 뒤)
    try std.testing.expect(!rows[3].card.local_pinned);
    try std.testing.expect(rows[4] == .group_header); // B 헤더(§2.1 부모 직접 카드 뒤·자식 그룹)
    try std.testing.expectEqual(@as(u8, 2), rows[4].group_header.depth); // ★ I3: B 중첩 depth2
    try std.testing.expectEqual(@as(usize, 4), rows[5].card.tab); // ★ 자식 B 로컬 pin t5(B 마커 카드 위 — 자식서도 성립)
    try std.testing.expect(rows[5].card.local_pinned);
    try std.testing.expectEqual(@as(u8, 2), rows[5].card.depth); // ★ I3: B 멤버 depth2
    try std.testing.expectEqual(@as(usize, 3), rows[6].card.tab); // B 마커 자기 카드(자식 로컬 pin 뒤)
    try std.testing.expect(!rows[6].card.local_pinned);
    try std.testing.expectEqual(@as(usize, 5), rows[7].card.tab); // B 비-pin 멤버 t4
    // 로컬 pin 📌: A 직접(t2)·자식 B(t5) 둘. 마커 카드·최상위·헤더는 억제.
    var member_pins: usize = 0;
    for (rows) |r| switch (r) {
        .card => |c| if (session.sidebarRowShowsPin(r)) {
            if (c.local_pinned) member_pins += 1;
        },
        .group_header => {},
    };
    try std.testing.expectEqual(@as(usize, 2), member_pins); // 부모·자식 각 1개
}

// GL4(c) — 회귀 매트릭스: 로컬 pin이 기존 기능 전부와 공존(안 부딪힘)함을 독립 블록으로 검증한다. 그룹 색(setGroupColor)·
// rename(startRenameGroup)·검색(sidebar_search)·pane 분리(promotePaneToNewWorkspace) 각각에서 로컬 pin float/플래그가
// 보존되는지 확인한다(그룹째 고정·드래그 프리뷰=확정·ungroup/removeFromGroup 위생은 GL3(a2)·GL3(d)·GL3(b*)가 이미 커버).
test "GL4(c): 회귀 매트릭스 — 로컬 pin이 그룹 색·rename·검색·pane 분리와 공존(float/플래그 보존)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const init_opts = SessionConfig{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 12,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    };

    // ── (1) 그룹 색 + 로컬 pin: setGroupColorForTab이 색만 얹고 float·local_pinned를 안 건드린다 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3]
        session.toggleLocalPin(t3); // t3 → 마커 직후(index2)
        try std.testing.expectEqual(t3, session.tabs.items[2]);
        session.setGroupColorForTab(t3, 0x4A7BC4); // 색은 enclosing 마커(t1)에 저장
        try std.testing.expectEqual(@as(u32, 0x4A7BC4), t1.group_color); // ★ 색 얹힘
        try std.testing.expect(t3.local_pinned); // ★ 로컬 pin 보존
        try std.testing.expectEqual(t3, session.tabs.items[2]); // ★ float 순서 보존
    }

    // ── (2) rename + 로컬 pin: startRenameGroupForTab이 편집 상태만 세우고 순서·local_pinned를 안 건드린다 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab();
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1);
        session.toggleLocalPin(t3);
        var snap: [4]*Tab = undefined;
        for (session.tabs.items, 0..) |t, i| snap[i] = t;
        session.startRenameGroupForTab(t3); // 그룹 A 이름 인라인 편집 시작(마커 t1)
        for (session.tabs.items, 0..) |t, i| try std.testing.expectEqual(snap[i], t); // ★ 순서 불변
        try std.testing.expect(t3.local_pinned); // ★ 로컬 pin 보존
        session.rename = null; // 편집 상태 teardown(escape 경로와 동형)
        session.rename_input.clear();
    }

    // ── (3) 검색 + 로컬 pin: 매치되는 로컬 pin 멤버가 검색 중에도 float 위치·📌 유지(검색은 가시성 필터일 뿐 순서·플래그 무변) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        const t1 = session.tabs.items[1];
        const t3 = session.tabs.items[3];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2, t3]
        session.toggleLocalPin(t3); // t3 → 마커 직후(index2)
        t3.custom_name = try allocator.dupe(u8, "findlp"); // 검색 매치용 이름(session.deinit이 free)
        session.sidebar_search_active = true;
        try session.sidebar_search_input.query.appendSlice(allocator, "findlp");
        session.recomputeVisibleTabs();
        // 매치 카드 t3(로컬 pin)이 접힘 무시하고 보이며, local_pinned 힌트·📌 유지.
        var saw_lp = false;
        for (session.sidebar_rows.items) |row| switch (row) {
            .card => |c| if (c.tab == 2) { // t3 = float 후 self.tabs index2
                saw_lp = true;
                try std.testing.expect(c.local_pinned); // ★ 검색 중에도 로컬 pin 힌트
                try std.testing.expect(session.sidebarRowShowsPin(row)); // ★ 📌 유지
            },
            .group_header => {},
        };
        try std.testing.expect(saw_lp);
        try std.testing.expect(t3.local_pinned); // ★ 검색이 플래그·순서 무변
        try std.testing.expectEqual(t3, session.tabs.items[2]);
        session.sidebar_search_active = false;
        session.sidebar_search_input.clear();
    }

    // ── (4) pane 분리 + 로컬 pin: promotePaneToNewWorkspace가 새 비고정 top-level 탭을 첫 마커 앞에 끼워도 그룹 안 로컬 pin
    //    float가 보존된다(새 카드=그룹 밖, local_pinned=false; 기존 그룹 내부 순서 불변). ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, init_opts);
        defer session.deinit();
        // split은 backing이 잡혀야 의미 있음(termRect 입력) — resized 창을 흉내.
        session.backing_width_px = session.sidebar_width_px + 800;
        session.backing_height_px = 600;
        session.window_padding_px = .{};
        inline for (0..2) |_| _ = try session.newTab(); // [t0, t1, t2]
        const t1 = session.tabs.items[1];
        const t2 = session.tabs.items[2];
        session.createGroupAbsorbForTab(t1); // A = [t1(마커), t2] — t0 최상위(분리 소스로 쓴다)
        session.toggleLocalPin(t2); // t2 로컬 pin → 마커 직후(index2, 이미 그 자리)
        try std.testing.expect(t2.local_pinned);
        // 최상위 t0(index0)을 활성으로 만들고 split → 2 pane → 그 새 pane을 새 워크스페이스로 분리.
        session.app_window.active_tab = 0;
        try session.splitActivePane(.horizontal); // t0 = [p0, p1], 활성 p1
        try std.testing.expectEqual(@as(usize, 2), session.tabs.items[0].panes.items.len);
        const before_len = session.tabs.items.len;
        session.promotePaneToNewWorkspace(session.activePane()); // p1 → 새 비고정 top-level 탭(첫 마커 앞 삽입)
        try std.testing.expectEqual(before_len + 1, session.tabs.items.len); // 새 탭 삽입됨
        // ★ 기존 그룹 A의 로컬 pin 보존: t2가 여전히 그룹 안·로컬 pin·마커 직후(index 이동은 됐어도 상대순서 불변).
        try std.testing.expect(t2.local_pinned); // ★ 로컬 pin 플래그 보존
        try std.testing.expect(session.tabIsInGroup(t2)); // 여전히 그룹 안
        const mi = session.enclosingGroupMarkerIndex(blk: {
            var idx: usize = 0;
            for (session.tabs.items, 0..) |t, i| if (t == t2) {
                idx = i;
                break;
            };
            break :blk idx;
        }).?;
        try std.testing.expectEqual(t1, session.tabs.items[mi]); // enclosing 마커 = t1(그룹 A 무결)
        // t2가 마커 직후(로컬 float 유지) — 삽입이 그룹 앞이라 subtree 내부 순서 불변.
        var t2_idx: usize = 0;
        for (session.tabs.items, 0..) |t, i| if (t == t2) {
            t2_idx = i;
            break;
        };
        try std.testing.expectEqual(mi + 1, t2_idx); // ★ 마커 직후(subtree-로컬 float 보존)
    }
}

// ── pin 회귀 매트릭스(사용자 경로 — cardPinRole 라우팅 + projectRowsCore 실제 row 소속) ─────────────────────────
// **왜 필요한가(그룹핀 리뷰 #9 갭)**: #9는 "self.tabs 인덱스"만 단언했고 **고정 그룹**(toggleGroupPin) 앞 top카드 흡수만
// 다뤘다. 실제 재발 경로는 (1) **비고정 그룹**이 있을 때 새 워크스페이스(Cmd+T)가 끝에 append돼 위치 파생상 마지막 그룹
// 멤버로 **흡수**되고, 그 카드 우클릭 pin이 cardPinRole=.local로 **그룹 안 float**되는 것 — index-only 단언은 이걸 놓친다
// (흡수는 **렌더 소속**=projectRowsCore depth/enclosing로만 잡힌다). 이 매트릭스는 두 축을 **실제 사용자 경로**로 통과한다:
// cardPinRole(우클릭 진입점 라우팅) + projectRowsCore(렌더된 카드가 그룹 밖 최상위인가).

/// 카드 `tab`이 **그룹 밖 최상위 고정 카드로 렌더**되는지 사용자 경로로 단언한다(pin 회귀 매트릭스 공용). self.tabs 인덱스가
/// 아니라 (1) cardPinRole=.individual(우클릭 pin이 개별 전역 pin으로 라우팅), (2) enclosing 마커 null·tabIsInGroup false
/// (소속 파생상 그룹 밖), (3) projectRowsCore가 이 카드를 depth 0·비파생·📌로 방출(렌더 소속=최상위)을 함께 본다.
fn expectCardTopLevelPinned(session: *AppSession, tab: *Tab) !void {
    try std.testing.expect(session.cardPinRole(tab) == .individual); // 우클릭 pin = 개별 전역 pin(그룹 위임/로컬 아님)
    try std.testing.expect(tab.group_start == null); // 마커 아님
    try std.testing.expect(tab.pinned); // 개별 pin 상태
    var idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == tab) {
        idx = i;
        break;
    };
    try std.testing.expect(session.enclosingGroupMarkerIndex(idx) == null); // 어느 그룹에도 안 속함
    try std.testing.expect(!session.tabIsInGroup(tab)); // 그룹 밖(흡수 없음)
    session.recomputeVisibleTabs();
    var found = false;
    for (session.sidebar_rows.items) |r| switch (r) {
        .card => |c| if (c.tab == idx) {
            found = true;
            try std.testing.expectEqual(@as(u8, 0), c.depth); // ★ 렌더 depth 0 = 최상위(그룹 흡수 없음)
            try std.testing.expect(!c.pin_derived); // 개별 pin(그룹 파생 캐시 아님)
            try std.testing.expect(!c.local_pinned); // 로컬 pin 아님(최상위엔 무의미)
            try std.testing.expect(session.sidebarRowShowsPin(r)); // ★ 📌 표시(개별 pin 카드)
        },
        .group_header => {},
    };
    try std.testing.expect(found); // 카드가 실제로 렌더됨(숨김 아님)
}

/// 우클릭 "위치 고정" 실제 진입점을 태운다(라벨·dispatch 공유 cardPinRole 라우팅) — acceptContextMenu의 ctx_menu_pin 경로.
fn rightClickPin(session: *AppSession, tab: *Tab) void {
    session.context_menu_target = .{ .workspace = tab };
    session.chrome_host.context_menu.selected = ctx_menu_pin;
    session.acceptContextMenu();
}

/// 워크스페이스 카드 우클릭 메뉴의 pin 라벨(cardPinRole 분기 결과) — context_menu_target 세팅 후 buildContextMenuItems 공유.
fn pinMenuLabel(session: *AppSession, tab: *Tab) []const u8 {
    session.context_menu_target = .{ .workspace = tab };
    return session.buildContextMenuItems()[ctx_menu_pin];
}

test "pin매트릭스 #1(버그1 회귀): 최상위 카드 위치 고정 — 5 배치 모두 그룹 밖 최상위 유지(cardPinRole=.individual·projectRows depth0·enclosing null·📌)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    // ── (a) 그룹 없음: 순수 최상위 카드끼리 pin은 위치만.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..1) |_| _ = try session.newTab(); // [t0,t1]
        const x = session.tabs.items[0];
        try std.testing.expectEqualStrings("위치 고정", pinMenuLabel(session, x));
        rightClickPin(session, x);
        try expectCardTopLevelPinned(session, x);
    }

    // ── (b) 비고정 그룹 **앞** 최상위 카드: [X, G(비고정), A, B]. pin X → 그룹 밖 유지.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        session.createGroupAbsorbForTab(session.tabs.items[1]); // G=[t1,t2,t3], t0=최상위
        const x = session.tabs.items[0];
        rightClickPin(session, x);
        try expectCardTopLevelPinned(session, x);
    }

    // ── (c) **비고정 그룹 뒤 = 새 워크스페이스**(버그1 핵심): 비고정 그룹이 있을 때 Cmd+T로 새 탭을 만들면 끝 append로
    //    마지막 그룹에 흡수되던 버그. createTab 삽입점을 첫 그룹 앞으로 고쳐(promotePaneToNewWorkspace 동형) 새 탭이
    //    **최상위**로 뜬다. cardPinRole=.individual(그룹 내 위치 고정 아님)·pin 후 그룹 밖 유지. 옛 버그면 .local→흡수(fail).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..1) |_| _ = try session.newTab(); // [t0,t1]
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1]
        const y = try session.newTab(); // ★ 그룹 존재 시 새 워크스페이스 — 흡수 방지로 그룹 **앞**에 삽입돼야
        try std.testing.expect(session.cardPinRole(y) == .individual); // ★ 흡수 안 됨(옛 버그면 .local)
        try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null); // ★ y가 index0(그룹 앞)·그룹 밖
        try std.testing.expectEqualStrings("위치 고정", pinMenuLabel(session, y)); // "그룹 내 위치 고정" 아님
        rightClickPin(session, y);
        try expectCardTopLevelPinned(session, y);
    }

    // ── (d)/(e) 고정 그룹과 최상위 카드: 고정 그룹 존재 시 새 top카드(비고정 리전)를 pin → 고정 그룹 **앞**으로 안착
    //    (#1195 의도 — subtree 뒤 흡수 방지). "고정 그룹 뒤(비고정 리전)"→pin→"고정 그룹 앞"(둘 다 그룹 밖 최상위).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1,t2]
        session.toggleGroupPin(session.tabs.items[0]); // G 고정 → 프리픽스
        const y = try session.newTab(); // 새 top카드 — 고정 프리픽스 뒤(비고정 리전)
        try std.testing.expect(session.cardPinRole(y) == .individual); // 비고정 리전 top카드(고정 그룹 뒤) = 개별
        rightClickPin(session, y); // pin → 고정 그룹 **앞**으로(흡수 없음)
        try expectCardTopLevelPinned(session, y);
        // y가 고정 그룹 마커보다 **앞**(subtree 밖).
        var yidx: usize = 0;
        var gidx: usize = 0;
        for (session.tabs.items, 0..) |t, i| {
            if (t == y) yidx = i;
            if (t.group_start != null) gidx = i;
        }
        try std.testing.expect(yidx < gidx); // ★ 고정 그룹 앞(subtree 안 아님)
    }

    // ── 재토글(on→off): pin한 최상위 카드를 다시 우클릭 해제 → 개별 pin 풀림(흡수/잔류 없음, 그냥 top카드).
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab(); // [t0..t2]
        session.createGroupAbsorbForTab(session.tabs.items[1]); // G=[t1,t2], t0=최상위
        const x = session.tabs.items[0];
        rightClickPin(session, x);
        try expectCardTopLevelPinned(session, x);
        try std.testing.expectEqualStrings("고정 해제", pinMenuLabel(session, x));
        rightClickPin(session, x); // 해제
        try std.testing.expect(!x.pinned); // 개별 pin 풀림
        try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null); // 여전히 최상위(그룹 흡수 없음)
        try std.testing.expect(x.group_start == null and !x.local_pinned); // 마커 아님·로컬 pin 아님
    }
}

test "pin매트릭스 #2(버그2 회귀): 그룹째 고정/해제 — 고정 멤버 pinned=1·📌억제, 해제 멤버 pinned=0·local_pinned=0·📌 0(그냥 그룹 멤버)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;

    const countCardPins = struct {
        fn f(s: *AppSession) usize {
            s.recomputeVisibleTabs();
            var n: usize = 0;
            for (s.sidebar_rows.items) |r| switch (r) {
                .card => if (s.sidebarRowShowsPin(r)) {
                    n += 1;
                },
                .group_header => {},
            };
            return n;
        }
    }.f;

    // ── 기본(로컬 pin 없음): 고정→멤버 pinned=1·📌억제(헤더 인디케이터만)·해제→멤버 pinned=0·📌 0.
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab();
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1,t2]
        const g = session.tabs.items[0];
        session.toggleGroupPin(g);
        try std.testing.expect(g.pinned and session.tabs.items[1].pinned and session.tabs.items[2].pinned); // 멤버 pinned=1
        try std.testing.expectEqual(@as(usize, 0), countCardPins(session)); // 카드 📌 0(멤버 억제·헤더 인디케이터가 표시)
        session.toggleGroupPin(g); // 해제
        try std.testing.expect(!g.pinned and !session.tabs.items[1].pinned and !session.tabs.items[2].pinned); // 멤버 pinned=0
        try std.testing.expect(!session.tabs.items[1].local_pinned and !session.tabs.items[2].local_pinned); // local_pinned 오염 없음
        try std.testing.expectEqual(@as(usize, 0), countCardPins(session)); // ★ 해제 후 카드 📌 0(그냥 그룹 멤버)
        try std.testing.expect(session.tabIsInGroup(session.tabs.items[1])); // 여전히 그룹 멤버(그냥 그룹 안)
    }

    // ── ★ 버그2 핵심: 멤버가 **로컬 pin**된 상태로 그룹째 고정 → 해제 시, 로컬 pin(📌)이 잔류하면 자식이 개별 고정으로
    //    남는다. 해제 = 그룹 리셋이라 멤버 local_pinned도 클리어돼 카드 📌 0이어야 한다("그냥 그룹 멤버로 복귀").
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 10, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab();
        session.createGroupAbsorbForTab(session.tabs.items[0]); // G=[t0,t1,t2]
        const g = session.tabs.items[0];
        const member = session.tabs.items[2];
        session.toggleLocalPin(member); // 멤버 로컬 pin(📌·마커 직후 float)
        try std.testing.expect(member.local_pinned);
        try std.testing.expectEqual(@as(usize, 1), countCardPins(session)); // 로컬 pin 카드 1개 📌(비고정 그룹)
        session.toggleGroupPin(g); // 그룹째 고정(로컬 pin은 켜는 동안 보존 — keystone)
        try std.testing.expect(member.local_pinned); // 고정 중 보존
        session.toggleGroupPin(g); // ★ 해제 = 그룹 리셋
        try std.testing.expect(!member.pinned); // 파생 pin 해제
        try std.testing.expect(!member.local_pinned); // ★ 로컬 pin도 클리어(버그2 fix — 개별 📌 잔류 방지)
        try std.testing.expectEqual(@as(usize, 0), countCardPins(session)); // ★ 해제 후 카드 📌 0(그냥 그룹 멤버)
        try std.testing.expect(session.tabIsInGroup(member)); // 여전히 그룹 멤버(그룹 밖으로 안 나감)
    }
}

test "pin매트릭스 #3(조합): 최상위 개별 pin + 그룹째 고정 + 멤버 로컬 pin 공존 — 렌더 소속·📌 카운트(축 3개 독립)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{ .abi_version = abi_version, .cols = 40, .rows = 12, .queue_capacity = 16, .command_kind = @intFromEnum(CommandKind.controlled_smoke) });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    // t0=최상위 개별 pin 카드, A=[t1(마커), t2, t3] 그룹째 고정, t3=로컬 pin 멤버.
    session.createGroupAbsorbForTab(session.tabs.items[1]); // A=[t1,t2,t3]
    const top = session.tabs.items[0];
    const marker = session.tabs.items[1];
    const lp = session.tabs.items[3];
    session.toggleLocalPin(lp); // A 멤버 로컬 pin
    rightClickPin(session, top); // t0 개별 전역 pin(.individual)
    session.toggleGroupPin(marker); // A 그룹째 고정
    // 세 축 독립: 개별 pin(top.pinned)·그룹째(marker.pinned)·로컬(lp.local_pinned) 공존.
    try std.testing.expect(top.pinned and top.group_start == null); // 개별 최상위
    try std.testing.expect(marker.pinned); // 그룹째 고정 권위
    try std.testing.expect(lp.pinned and lp.local_pinned); // 파생 캐시 + 로컬 pin
    try expectCardTopLevelPinned(session, top); // 최상위 카드는 흡수 없이 그룹 밖 최상위 📌
    // 렌더 📌 카운트: 최상위 카드 1(개별) + 헤더 1(그룹째 인디케이터) + 로컬 pin 멤버 1 = 카드 2·헤더 1.
    session.recomputeVisibleTabs();
    var card_pins: usize = 0;
    var header_pins: usize = 0;
    for (session.sidebar_rows.items) |r| switch (r) {
        .card => if (session.sidebarRowShowsPin(r)) {
            card_pins += 1;
        },
        .group_header => if (session.sidebarRowShowsPin(r)) {
            header_pins += 1;
        },
    };
    try std.testing.expectEqual(@as(usize, 2), card_pins); // 최상위 개별 + 로컬 pin 멤버
    try std.testing.expectEqual(@as(usize, 1), header_pins); // 그룹째 고정 헤더 인디케이터
}

test "SG5-1: 그룹 통째 이동(moveGroupRange + sidebarGroupDropBoundary) — 위/아래·최상위·끝 + 자기그룹 no-op + 연속 파티션" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // 최상위 카드 t0·t1 + 두 **형제** 그룹 A=[t2,t3], B=[t4,t5](§2.1: 최상위는 첫 마커 이전 구간에만).
    // SG5-3: create_group은 그룹 안 카드에서 depth+1 중첩이라, A가 끝까지 뻗은 뒤 t4에 부르면 B가 A 자식(depth 2)이 된다.
    // 이 테스트는 형제 그룹 통째 이동을 보므로 B의 depth를 1로 명시해 형제 최상위 그룹으로 둔다(§9 tension 문서화).
    session.createGroupAbsorbForTab(t2); // A(마커 index2)
    session.createGroupAbsorbForTab(t4); // B(마커 index4) — 중첩 기본
    t4.group_depth = 1; // B를 최상위 형제로 오버라이드
    // 마커 수·초기 순서 확인.
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // 최상위
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // A 마커 카드
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B 마커 카드

    const markerCount = struct {
        fn f(s: *AppSession) usize {
            var n: usize = 0;
            for (s.tabs.items) |t| if (t.group_start != null) {
                n += 1;
            };
            return n;
        }
    }.f;
    try std.testing.expectEqual(@as(usize, 2), markerCount(session)); // 항상 마커 2개(그룹 2개)

    // ── ① 그룹 B를 **최상위 카드에 드롭** → 그룹들 최상단(첫 그룹 앞, 최상위 뒤). row0=최상위 카드 t0.
    session.recomputeVisibleTabs(); // [c t0(0), c t1(1), hA(2), c t2(3), c t3(4), hB(5), c t4(6), c t5(7)]
    {
        const m: usize = 4; // 그룹 B 마커(t4)
        const boundary = session.sidebarGroupDropBoundary(0, m).?; // 최상위 카드 row0 → 첫 그룹 앞 = 2
        try std.testing.expectEqual(@as(usize, 2), boundary);
        const nm = session.moveGroupRange(m, boundary, false);
        try std.testing.expectEqual(@as(usize, 2), nm); // 새 마커 인덱스(t4가 index2로)
    }
    // 결과 [t0, t1, t4(B), t5, t2(A), t3] — B가 그룹들 최상단, 최상위 t0·t1는 앞에 그대로.
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t4, session.tabs.items[2]);
    try std.testing.expectEqual(t5, session.tabs.items[3]);
    try std.testing.expectEqual(t2, session.tabs.items[4]);
    try std.testing.expectEqual(t3, session.tabs.items[5]);
    try std.testing.expectEqual(@as(usize, 2), markerCount(session)); // 여전히 그룹 2개(쪼개짐 없음)
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위 보존
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t1)); // 최상위 보존
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t5)); // B 몸통(연속)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // A 몸통(연속)

    // ── ② 그룹 A(마커 index4)를 **다른 그룹 헤더(B) 위에 드롭** → 그 그룹 앞으로(위로 이동). rows: [c t0, c t1, hB(2), c t4, c t5, hA(5), c t2, c t3].
    session.recomputeVisibleTabs();
    {
        const m: usize = 4; // 그룹 A 마커(t2)
        const boundary = session.sidebarGroupDropBoundary(2, m).?; // B 헤더 row2, gi=2<m=4 → B 앞(2)
        try std.testing.expectEqual(@as(usize, 2), boundary);
        _ = session.moveGroupRange(m, boundary, false);
    }
    // 결과 [t0, t1, t2(A), t3, t4(B), t5] — A가 B 앞으로(원래 순서 복귀).
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t4, session.tabs.items[4]);
    try std.testing.expectEqual(@as(usize, 2), markerCount(session));

    // ── ③ 그룹 A(마커 index2)를 **다른 그룹(B)의 카드에 드롭** → 그 그룹 뒤(끝)로(아래로 이동). rows: [c t0, c t1, hA(2), c t2, c t3, hB(5), c t4, c t5].
    session.recomputeVisibleTabs();
    {
        const m: usize = 2; // 그룹 A 마커(t2)
        const boundary = session.sidebarGroupDropBoundary(7, m).?; // B 카드 t5(row7), gi=4>m=2 → B 뒤(끝)=6
        try std.testing.expectEqual(@as(usize, 6), boundary);
        const nm = session.moveGroupRange(m, boundary, false);
        try std.testing.expectEqual(@as(usize, 4), nm); // A가 끝(index4)으로
    }
    // 결과 [t0, t1, t4(B), t5, t2(A), t3] — A가 리스트 끝 그룹.
    try std.testing.expectEqual(t4, session.tabs.items[2]);
    try std.testing.expectEqual(t2, session.tabs.items[4]);
    try std.testing.expectEqual(t3, session.tabs.items[5]);
    try std.testing.expectEqual(@as(usize, 2), markerCount(session));

    // ── ④ 자기 그룹에 드롭 = no-op(boundary null). A(마커 index4)의 자기 카드(t3, row?)에 드롭. rows: [c t0, c t1, hB(2), c t4, c t5, hA(5), c t2, c t3].
    session.recomputeVisibleTabs();
    try std.testing.expect(session.sidebarGroupDropBoundary(5, 4) == null); // A 헤더(자기) → null
    try std.testing.expect(session.sidebarGroupDropBoundary(7, 4) == null); // A 몸통 카드(자기) → null
    // moveGroupRange도 자기 자리 boundary(구간 안)면 no-op으로 m을 그대로 돌려준다.
    try std.testing.expectEqual(@as(usize, 4), session.moveGroupRange(4, 4, false)); // insert_before==m → no-op
    try std.testing.expectEqual(@as(usize, 4), session.moveGroupRange(4, 6, false)); // insert_before==j(=len) → no-op(이미 끝)
    // 비-마커 인덱스로 moveGroupRange 호출 방어(가드). t5(index3)는 마커 아님 → m 그대로.
    try std.testing.expectEqual(@as(usize, 3), session.moveGroupRange(3, 0, false));
}

// ── §14.6 SR4 인터리빙 회귀 — 그룹 통째 드래그 ↔ top_level 탭 순서 교환 ──────────────────────────────────────────
// 증상: §2.1 재설계(§14)로 top_level 탭이 그룹 뒤/사이에 오는데, `sidebarGroupDropBoundary`가 최상위 카드를 전부 "리딩
// zone"(첫 그룹 이전)으로만 보고 `first_group`으로 clamp해 **그룹이 top_level 탭 위/사이로 못 갔다**(카드 드래그 SR4는
// 되는데 그룹 드래그만 안 됨). 아래 테스트는 그룹 드래그가 top_level 탭과 자유롭게 순서를 교환하고(그룹↔탭 인터리빙),
// top_level 불변·프리뷰=확정·고정 리전 clamp가 정합함을 고정한다. 리딩 카드(플래그 없음)는 옛 clamp 폴백이라 SG5-1 회귀 0.

/// 표시 카드 row 인덱스를 tab 인덱스로 찾는다(그룹 드래그 경계 테스트가 커서 hit-test 대신 쓰는 헤드리스 헬퍼).
fn cardRowOf(session: *AppSession, tab_idx: usize) usize {
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .card => |c| if (c.tab == tab_idx) return s,
        .group_header => {},
    };
    return 0;
}

/// 표시 row의 화면 y(backing px)를 그 row 안 frac 위치로 — cardDropPlan 실좌표(y_px) 테스트가 커서 y를 구성한다.
fn sidebarDragScreenY(session: *AppSession, row: usize, frac: f64) f64 {
    const rows = session.sidebar_rows.items;
    const top = chrome.components.sidebar.rowTop(rows, row, session.sidebar_header_height_px, session.sidebar_slot_height_px, session.sidebar_header_row_h_px, session.sidebar_scroll_offset_px);
    const h = chrome.components.sidebar.rowHeight(rows[row], session.sidebar_slot_height_px, session.sidebar_header_row_h_px);
    return @as(f64, @floatFromInt(top)) + @as(f64, @floatFromInt(h)) * frac;
}

// ── (A) 카드 드래그 실좌표(y_px→cardDropPlan) — 고정 탭을 그룹 꼬리로 끌면 top_level 탈출(흡수 아님) ────────────────
// 증상 A: 실앱에서 고정 탭을 드래그하면 그룹 안 멤버로 **흡수**(top_level=false). 기존 헤드리스는 raw_row·y를 직접 넣어
// (SR5(a)) hit-test **함수**만 봤고, mouse 핸들러의 y_px→raw_row→plan **실경로**(특히 드래그 소스가 프리뷰에서 빠져 그
// 아래가 위로 밀리는 시프트)를 안 탔다. 이 테스트는 cardDropPlan(실 핸들러가 부르는 단일 출처)을 커서 y로 태워 그 갭을
// 메운다: 사용자가 프리뷰의 그룹 꼬리를 겨냥하면 top_level 탈출이 발화하고, 보정 없던 옛 판정은 흡수였음을 대비로 고정한다.
test "(A) 카드 드래그 실좌표: 고정 탭을 그룹 꼬리로 끌면 top_level 탈출 (cardDropPlan y_px 실경로·프리뷰 시프트 보정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2] 고정 리전
    inline for (0..3) |i| session.tabs.items[i].pinned = true;
    // X=t0(고정 leading 탭, top_level=false — createGroup이 남기는 실제 상태), A=[a0=t1(마커), a1=t2(멤버)].
    try setGroupMarker(session, 1, "A", 1);
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.sidebar_drag_index = 0; // X가 드래그 소스

    // 표시 행(원본): [card X(0), header A(1), card a0(2), card a1(3)]. a1=마지막 멤버(그룹 꼬리).
    const a1_row = cardRowOf(session, 2);
    try std.testing.expectEqual(@as(usize, 3), a1_row);

    // ① 그룹 꼬리(마지막 멤버 a1의 상단 frac 0.15) 겨냥 — 프리뷰에선 X가 빠져 그룹이 위로 밀리므로 사용자가 보는
    //    "그룹 꼬리"는 원본 a1 상단쯤이다. 옛 판정(보정 없이 이 y로 sidebarCardDropAfterGroup)은 하단 40% 밖이라 흡수였다.
    const y_tail = sidebarDragScreenY(session, a1_row, 0.15);
    // 옛 경로(보정 없음) 대비: raw_row=a1, 하단 경계 아님 → 탈출 null(흡수). 이게 헤드리스가 못 잡던 실패다.
    const raw_uncomp = chrome.components.sidebar.dragTargetSlot(y_tail, session.sidebar_header_height_px, session.sidebar_rows.items, session.sidebar_slot_height_px, session.sidebar_header_row_h_px, session.sidebar_scroll_offset_px);
    try std.testing.expect(session.sidebarCardDropAfterGroup(raw_uncomp, 0, y_tail) == null); // 보정 없으면 탈출 안 함(흡수)
    // 새 경로(cardDropPlan, 프리뷰 시프트 보정) → top_level 탈출.
    const plan_tail = session.cardDropPlan(0, y_tail);
    switch (plan_tail) {
        .card => |c| {
            try std.testing.expect(c.top_level); // ★ 흡수 아님 — 그룹 밖 top_level
            try std.testing.expectEqual(@as(usize, 2), c.target_tab); // a1(그룹 꼬리) 자리
        },
        else => return error.TestUnexpectedResult,
    }

    // ② 실제 commit → X가 그룹 A 뒤 최상위(흡수 안 됨).
    session.sidebar_drag_preview = .{ .origin = 0, .origin_len = 1, .plan = plan_tail, .cursor_y = y_tail, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();
    const x = session.tabs.items[2]; // X가 [a0, a1, X]로 밀림
    try std.testing.expect(x.top_level); // ★ top_level 유지(그룹 밖)
    try std.testing.expect(session.enclosingGroupMarkerIndex(2) == null); // 그룹 A에 흡수 안 됨
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(2, null, null));
    try std.testing.expect(session.tabs.items[0].group_start != null); // A 마커(a0)가 index0으로

    // ③ 새 정책(고정 흡수 금지): 같은 **고정** 탭을 그룹 상단(첫 멤버)에 드롭해도 흡수 안 됨 = top_level=true.
    //    옛 동작은 위치가 그룹 안이면 멤버 흡수(false)였으나, 고정 소스는 위치 무관하게 top_level 강제 — "고정된 건 어디에도
    //    흡수 안 됨". 비고정 소스의 멤버 넣기 능력(회귀 0)은 아래 별도 테스트(SR-PIN 비고정 대비)가 지킨다.
    const s2 = try allocator.create(AppSession);
    defer allocator.destroy(s2);
    try s2.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer s2.deinit();
    inline for (0..2) |_| _ = try s2.newTab();
    inline for (0..3) |i| s2.tabs.items[i].pinned = true;
    try setGroupMarker(s2, 1, "A", 1);
    s2.sidebar_slot_height_px = 40;
    s2.sidebar_header_row_h_px = 20;
    s2.sidebar_header_height_px = 30;
    s2.sidebar_scroll_offset_px = 0;
    s2.recomputeVisibleTabs();
    s2.sidebar_drag_index = 0;
    const a0_row = cardRowOf(s2, 1); // a0(첫 멤버) row
    const y_head = sidebarDragScreenY(s2, a0_row, 0.2); // 첫 멤버 상단 = 그룹 안이지만 고정 소스라 흡수 금지
    const plan_head = s2.cardDropPlan(0, y_head);
    switch (plan_head) {
        .card => |c| try std.testing.expect(c.top_level), // ★ 고정 소스 = 그룹 안 드롭이어도 흡수 금지(top_level 강제)
        else => return error.TestUnexpectedResult,
    }
}

// ── SR-PIN: "고정된 건 어디에도 흡수 안 됨" — 고정 탭/그룹은 고정 리전 안 top_level(그룹 밖)로만 존재(사용자 정책) ──────
// 4개 규율을 헤드리스로 고정한다: (1) 프리뷰=확정 유실 수정(commit이 저장 plan.top_level 그대로 씀), (2) 고정 탭 그룹 흡수
// 금지(위치 무관 top_level 강제), (3) 고정 그룹 nest 흡수 금지(Cmd nest여도 sibling), (4) 고정 리전 clamp(비고정으로 안 넘어감).
// 특히 (1)(2)는 **전체 마우스 경로**(cardDropPlan=mouseMoved 산출 → refreshDragPreview=sidebar_drag_preview.plan 저장 →
// commitSidebarDragPreview=up 확정)를 태워, 헤드리스가 commit을 직접 호출하던 사각(실앱 mouse→preview→commit 체인)을 메운다.

test "SR-PIN1: 고정 탭을 그룹 한복판에 드롭 → 흡수 금지(전체 마우스 경로 cardDropPlan→저장→commit, 프리뷰=확정)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 4개, 전부 고정 리전
    inline for (0..4) |i| session.tabs.items[i].pinned = true;
    // X=t0(고정 leading 탭, 드래그 소스), A=[Am=t1(마커), a1=t2, a2=t3]. a1=**한복판 멤버**(꼬리/헤더 아님, gap 미발화).
    try setGroupMarker(session, 1, "A", 1);
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.sidebar_drag_index = 0;
    const x_ptr = session.tabs.items[0];
    const am_ptr = session.tabs.items[1];
    const a1_ptr = session.tabs.items[2];
    const a2_ptr = session.tabs.items[3]; // 한복판 뒤 멤버 — [2] 그룹 무결(안 eject) 검증 대상

    // 표시 행: [card X(0), header A(1), card a1(2), card a2(3)]. a1(=tab2) 한복판을 frac 0.3(상단)로 겨냥 →
    // 하단 경계(gap) 미발화라 sidebarGroupDropTargetTab(멤버 자리)+sidebarCardDropTopLevel(그룹 멤버=false) 경로.
    const a1_row = cardRowOf(session, 2);
    const y_mid = sidebarDragScreenY(session, a1_row, 0.3);
    // ① mouseMoved 산출(cardDropPlan): 고정 소스라 흡수 금지(top_level=true 강제) + **[2] 그룹 안 착지 금지** — target을
    // 그룹 A subtree 밖 경계로 clamp. origin=0(그룹 위)이라 그룹 뒤 끝(ge-1=3)으로 착지(한복판 2가 아니라 경계).
    const plan_mid = session.cardDropPlan(0, y_mid);
    switch (plan_mid) {
        .card => |c| {
            try std.testing.expectEqual(@as(usize, 3), c.target_tab); // ★ [2] 그룹 subtree 밖 경계(뒤 끝)로 clamp(한복판 2 아님)
            try std.testing.expect(c.top_level); // ★ 고정 소스 = 흡수 금지(위치 무관 top_level 강제)
        },
        else => return error.TestUnexpectedResult,
    }
    // ② refreshDragPreview가 그 plan을 sidebar_drag_preview.plan에 **저장**(실 핸들러 mouseMoved의 저장 지점).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try session.refreshDragPreview(0, plan_mid, y_mid, arena_state.allocator());
    try std.testing.expect(session.sidebar_drag_preview != null);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .card);
    try std.testing.expect(session.sidebar_drag_preview.?.plan.card.top_level); // ★ 저장된 plan에 top_level=true 온전

    // ③ up 확정(commitSidebarDragPreview): 저장 plan을 그대로 replay — X가 그룹 경계(뒤)에 착지, 그룹 A는 무결.
    session.commitSidebarDragPreview();
    // 확정 배치 [Am, a1, a2, X] — X는 그룹 A **뒤** 고정 top카드(흡수 아님), 그룹 A=[Am,a1,a2] 온전(a2 안 eject).
    try std.testing.expectEqual(am_ptr, session.tabs.items[0]);
    try std.testing.expectEqual(a1_ptr, session.tabs.items[1]);
    try std.testing.expectEqual(a2_ptr, session.tabs.items[2]);
    try std.testing.expectEqual(x_ptr, session.tabs.items[3]); // X가 그룹 뒤 경계(position 3)
    try std.testing.expect(session.tabs.items[3].top_level); // ★ 흡수 금지(top_level 확정 write)
    try std.testing.expect(session.enclosingGroupMarkerIndex(3) == null); // X는 그룹 A 멤버 아님
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(3, null, null)); // 그룹 밖(depth0)
    try std.testing.expect(session.tabs.items[3].pinned); // 고정 유지(고정 리전 안)
    // ★ [2] 그룹 무결 — 뒤 멤버 a2가 그룹에서 eject되지 않았다(revert하면 X가 한복판에 착지해 a2가 top-level로 튕겨나감).
    try std.testing.expectEqual(@as(usize, 0), session.enclosingGroupMarkerIndex(2).?); // a2는 여전히 A(마커 index0) 멤버
    try std.testing.expect(!a2_ptr.top_level); // a2 안 eject
    try std.testing.expectEqual(@as(usize, 3), session.groupSubtreeEnd(0, null, null)); // A=[0,3) 완전 subtree(쪼개짐 없음)
}

test "SR-PIN2: 비고정 탭을 같은 그룹 한복판에 드롭 → 흡수 유지(top_level=false, 비고정 회귀 0)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3], 전부 **비고정**(기본)
    try setGroupMarker(session, 1, "A", 1); // X=t0(top카드), A=[Am=t1, a1=t2, a2=t3]
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.sidebar_drag_index = 0;
    const a1_row = cardRowOf(session, 2);
    const y_mid = sidebarDragScreenY(session, a1_row, 0.3);
    const plan_mid = session.cardDropPlan(0, y_mid);
    switch (plan_mid) {
        .card => |c| {
            try std.testing.expectEqual(@as(usize, 2), c.target_tab);
            try std.testing.expect(!c.top_level); // ★ 비고정 소스 = 그룹 안 = 멤버 흡수(top_level=false, 기존 동작)
        },
        else => return error.TestUnexpectedResult,
    }
    // 전체 경로 확정 후에도 흡수(그룹 A 멤버).
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try session.refreshDragPreview(0, plan_mid, y_mid, arena_state.allocator());
    session.commitSidebarDragPreview();
    try std.testing.expect(!session.tabs.items[2].top_level); // 멤버(흡수)
    try std.testing.expect(session.enclosingGroupMarkerIndex(2) != null); // ★ 그룹 A에 흡수됨(비고정 능력 보존)
}

test "SR-PIN3: 고정 그룹은 다른 그룹에 nest 흡수 금지(Cmd nest여도 sibling) + 비고정 그룹은 nest 유지" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    // ── Part 1: 고정 그룹 A를 고정 그룹 B 헤더에 Cmd 드롭 → sibling(nest 안 됨) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        inline for (0..4) |i| session.tabs.items[i].pinned = true; // 전부 고정
        try setGroupMarker(session, 0, "A", 1); // A=[Am=t0, a1=t1]
        try setGroupMarker(session, 2, "B", 1); // B=[Bm=t2, b1=t3]
        session.recomputeVisibleTabs();
        var b_header_row: usize = 0;
        for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
            .group_header => |gh| if (gh.tab == 2) {
                b_header_row = s;
            },
            .card => {},
        };
        // groupNestPlan 직접: 드래그 그룹 마커(0)가 고정이라 nest 불가 → null(형제 폴백).
        try std.testing.expect(session.groupNestPlan(b_header_row, 0) == null); // ★ 고정 그룹 nest 금지
        // 전체 프레임(Cmd 눌림): nest 시도해도 sibling으로 폴백.
        const y_b = sidebarDragScreenY(session, b_header_row, 0.5);
        session.groupDragPreviewFrame(0, y_b, true); // cmd_held=true
        try std.testing.expect(session.sidebar_drag_preview != null);
        try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling); // ★ Cmd여도 sibling(중첩 아님)
        session.clearSidebarDragPreview();
    }
    // ── Part 2: 비고정 그룹 A를 비고정 그룹 B 헤더에 Cmd 드롭 → nest(중첩 유지, 회귀 0) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3] 전부 비고정
        try setGroupMarker(session, 0, "A", 1);
        try setGroupMarker(session, 2, "B", 1);
        session.recomputeVisibleTabs();
        var b_header_row: usize = 0;
        for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
            .group_header => |gh| if (gh.tab == 2) {
                b_header_row = s;
            },
            .card => {},
        };
        try std.testing.expect(session.groupNestPlan(b_header_row, 0) != null); // 비고정 = nest 가능(기존 동작)
        const y_b = sidebarDragScreenY(session, b_header_row, 0.5);
        session.groupDragPreviewFrame(0, y_b, true); // cmd_held=true
        try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_nest); // ★ 비고정 Cmd = 중첩(회귀 0)
        session.clearSidebarDragPreview();
    }
}

test "SR-PIN4: 고정 탭을 비고정 리전 위치로 드래그 → 고정 리전 끝으로 clamp(비고정 안 넘어감, 전체 경로)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
    session.tabs.items[0].pinned = true; // X=t0(고정, 드래그 소스)
    session.tabs.items[1].pinned = true; // P1=t1(고정)
    // u2=t2 비고정. 고정 리전 [0,2), 비고정 [2,3).
    session.sidebar_slot_height_px = 40;
    session.sidebar_header_row_h_px = 20;
    session.sidebar_header_height_px = 30;
    session.sidebar_scroll_offset_px = 0;
    session.recomputeVisibleTabs();
    session.sidebar_drag_index = 0;
    const x_ptr = session.tabs.items[0];
    const u2_ptr = session.tabs.items[2];
    // X(고정)를 u2(비고정, position 2) 위로 드래그. target=2(비고정 리전)여도 clampMoveToGroup이 고정 리전 끝(1)로 가둔다.
    const u2_row = cardRowOf(session, 2);
    const y_u2 = sidebarDragScreenY(session, u2_row, 0.5);
    const plan = session.cardDropPlan(0, y_u2);
    var arena_state = std.heap.ArenaAllocator.init(allocator);
    defer arena_state.deinit();
    try session.refreshDragPreview(0, plan, y_u2, arena_state.allocator());
    session.commitSidebarDragPreview();
    // X는 고정 리전 끝(position 1)까지만 — 비고정(position 2)으로 못 넘어간다. u2는 여전히 position 2.
    try std.testing.expectEqual(x_ptr, session.tabs.items[1]); // ★ X가 고정 리전 끝(1)로 clamp
    try std.testing.expect(session.tabs.items[1].pinned); // 고정 유지
    try std.testing.expectEqual(u2_ptr, session.tabs.items[2]); // u2 비고정 자리 불변(X 안 넘어옴)
    try std.testing.expect(!session.tabs.items[2].pinned);
}

test "SR-PIN5: 프리뷰=확정 등가 — 고정 탭 그룹 한복판 drop plan을 simulateDrop vs commitSidebarDragPreview 동일" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    inline for (0..4) |i| session.tabs.items[i].pinned = true; // 전부 고정
    try setGroupMarker(session, 1, "A", 1); // X=t0, A=[Am=t1, a1=t2, a2=t3]
    session.recomputeVisibleTabs();
    // 고정 소스 X를 그룹 경계(뒤 끝 position 3 — [2] cardDropPlan이 그룹 밖으로 clamp할 값)로, top_level=true.
    // simulateDrop 가상 top_level[] == commitSidebarDragPreview 후 실제 top_level[] (프리뷰=확정 게이트 동일).
    try expectCardDropTopLevelEquivalent(session, 0, .{ .card = .{ .target_tab = 3, .top_level = true } });
}

// ── (3) 드래그 중 접힌 그룹은 접힌 헤더로만 — 대상=접힌 그룹이면 subtree force-emit 억제, 타깃=접힌 그룹은 유지 ────────
// SG8은 고스트가 접힌 그룹 subtree에 들어가면 "드롭 시 사라짐" 방지로 force-emit했다. 사용자 요청: 접힌 그룹을 **통째로
// 드래그**하면 고스트도 접힌 헤더 한 줄이어야(펼쳐 보이면 안 됨). 단 접힌 **타깃** 그룹 안으로 카드를 드롭할 때의
// force-emit(사라짐 방지)는 유지한다(대상 vs 타깃 구분).
test "(3) 드래그 대상이 접힌 그룹이면 프리뷰=접힌 헤더만 (타깃 접힌 그룹 드롭의 force-emit는 유지)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    // ── Part 1: 접힌 그룹 A를 통째 드래그 → 프리뷰에 A는 접힌 헤더 1줄, 멤버 카드 0 ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
        try setGroupMarker(session, 0, "A", 1); // A=[a0=t0(접힘), a1=t1]
        session.tabs.items[0].group_collapsed = true;
        try setGroupMarker(session, 2, "B", 1); // B=[b0=t2, b1=t3]
        session.recomputeVisibleTabs();
        var arena_state = std.heap.ArenaAllocator.init(allocator);
        defer arena_state.deinit();
        const insert_before = session.groupSubtreeEnd(2, null, null);
        try session.refreshDragPreview(0, .{ .group_sibling = .{ .insert_before = insert_before } }, 0, arena_state.allocator());
        var a_header_rows: usize = 0;
        var a_card_rows: usize = 0;
        var a_header_collapsed = false;
        for (session.sidebar_preview_rows.items) |row| switch (row) {
            .group_header => |h| if (h.tab == 0) {
                a_header_rows += 1;
                a_header_collapsed = h.collapsed;
            },
            .card => |c| if (c.tab == 0 or c.tab == 1) {
                a_card_rows += 1;
            },
        };
        try std.testing.expectEqual(@as(usize, 1), a_header_rows); // A 헤더 1줄
        try std.testing.expectEqual(@as(usize, 0), a_card_rows); // ★ 멤버 카드 방출 안 됨(접힌 채)
        try std.testing.expect(a_header_collapsed); // ★ 헤더 접힘 유지(펼침 flip 안 함)
        session.clearSidebarDragPreview();
    }
    // ── Part 2: 접힌 **타깃** 그룹 B 안으로 카드 X를 드롭 → force-emit 유지(카드 고스트 방출·사라짐 방지) ──
    {
        const session = try allocator.create(AppSession);
        defer allocator.destroy(session);
        try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
            .abi_version = abi_version,
            .cols = 40,
            .rows = 10,
            .queue_capacity = 16,
            .command_kind = @intFromEnum(CommandKind.controlled_smoke),
        });
        defer session.deinit();
        inline for (0..2) |_| _ = try session.newTab(); // [t0,t1,t2]
        // B=[b0=t0(접힘), b1=t1], X=t2(최상위 카드)
        try setGroupMarker(session, 0, "B", 1);
        session.tabs.items[0].group_collapsed = true;
        session.recomputeVisibleTabs();
        var arena_state = std.heap.ArenaAllocator.init(allocator);
        defer arena_state.deinit();
        // X(t2)를 접힌 B 끝으로 드롭(카드 드래그, dragged_collapsed=false).
        const target = session.groupSubtreeEnd(0, null, null) - 1; // 접힌 B subtree 끝
        try session.refreshDragPreview(2, .{ .card = .{ .target_tab = target } }, 0, arena_state.allocator());
        var x_visible = false;
        for (session.sidebar_preview_rows.items) |row| switch (row) {
            .card => |c| if (c.tab == 2) {
                x_visible = true;
            },
            .group_header => {},
        };
        try std.testing.expect(x_visible); // ★ 접힌 타깃 안 드롭이라도 X 고스트 방출(force-emit 유지 — 사라짐 방지)
        session.clearSidebarDragPreview();
    }
}

test "SR4 그룹드래그(a): [탭X, 그룹A]에서 A를 X 앞으로 → [그룹A, 탭X](순서 교환·X top_level 유지, 실제 commit 경로)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // init 기본 탭 1개 + 2개 = [t0, t1, t2] 3개
    // [X(t0, top_level 탭), A=[a0(t1,마커), a1(t2,멤버)]]. X는 첫 그룹 이전이지만 top_level 플래그가 서 있어 인터리브 대상.
    const x = session.tabs.items[0];
    x.top_level = true;
    try setGroupMarker(session, 1, "A", 1);
    session.recomputeVisibleTabs();
    try std.testing.expect(session.enclosingGroupMarkerIndex(0) == null); // X 그룹 밖 최상위
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(0, null, null));

    // A(마커 index1)를 X row로 드래그 → 인터리빙 경계 = X 앞(0). 옛 코드는 target<first_group=1이라 first_group(1)로 clamp,
    // m==first_group이라 no-op(안 움직임)이었다. 이제 X가 top_level 인터리브 단위라 그 앞(0)을 낸다.
    const boundary = session.sidebarGroupDropBoundary(cardRowOf(session, 0), 1).?;
    try std.testing.expectEqual(@as(usize, 0), boundary);
    const plan: AppSession.DropPlan = .{ .group_sibling = .{ .insert_before = session.clampGroupMoveToRegion(1, boundary) } };

    // 실제 앱 경로로 1회 확정(groupDragPreviewFrame이 굽는 plan을 commitSidebarDragPreview가 재사용 — normalize/float/sweep 포함).
    session.sidebar_drag_preview = .{ .origin = 1, .origin_len = 2, .plan = plan, .cursor_y = 0, .ghost_lo = 0, .ghost_hi = 0 };
    session.commitSidebarDragPreview();

    // 결과 [A=[a0,a1], X] — 순서 교환. X는 그룹 A 뒤 최상위(top_level 유지·흡수 안 됨).
    try std.testing.expect(session.tabs.items[0].group_start != null); // index0 = A 마커(a0)
    const x_idx = blk: {
        for (session.tabs.items, 0..) |t, i| if (t == x) break :blk i;
        break :blk session.tabs.items.len;
    };
    try std.testing.expectEqual(@as(usize, 2), x_idx); // X가 그룹 뒤(index2)로
    try std.testing.expect(x.top_level); // ★ top_level 유지(그룹 이동은 top_level 불변, §14.6)
    try std.testing.expect(session.enclosingGroupMarkerIndex(x_idx) == null); // 흡수 안 됨(그룹 밖 최상위)
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(x_idx, null, null)); // depth 0
    var markers: usize = 0;
    for (session.tabs.items) |t| if (t.group_start != null) {
        markers += 1;
    };
    try std.testing.expectEqual(@as(usize, 1), markers); // 마커 1개(쪼개짐/유령 마커 없음)
}

test "SR4 그룹드래그(b): [그룹A, 탭X, 그룹B]에서 그룹이 X를 넘나들며 순서 변경(X 사이 유지·top_level 불변)·프리뷰=확정 등가" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..2) |_| _ = try session.newTab(); // init 기본 탭 1개 + 2개 = [t0, t1, t2] 3개
    // [A=[a0(t0,마커)], X(t1, top_level 탭), B=[b0(t2,마커)]] — 단일 카드 형제 그룹 사이에 top카드.
    try setGroupMarker(session, 0, "A", 1);
    const x = session.tabs.items[1];
    x.top_level = true;
    try setGroupMarker(session, 2, "B", 1);
    session.recomputeVisibleTabs();
    try std.testing.expect(session.enclosingGroupMarkerIndex(1) == null); // X = A·B 사이 최상위

    // ── ① B(마커 index2)를 X 위로 드래그 → B가 X 앞으로 = [A, B, X]. 경계=run_lo(X=1)<m(2) → 1. 프리뷰=확정 등가.
    const b1 = session.sidebarGroupDropBoundary(cardRowOf(session, 1), 2).?;
    try std.testing.expectEqual(@as(usize, 1), b1);
    try expectDropEquivalent(session, 2, .{ .group_sibling = .{ .insert_before = b1 } });
    try std.testing.expectEqual(x, session.tabs.items[2]); // X가 뒤로 밀림
    try std.testing.expect(x.top_level); // top_level 유지
    try std.testing.expect(session.enclosingGroupMarkerIndex(2) == null); // 흡수 안 됨

    // ── ② B(이제 index1)를 X(이제 index2) 아래로 드래그 → B가 X 뒤로 = [A, X, B](복귀, X가 다시 A·B 사이). 경계=run_hi=len=3.
    session.recomputeVisibleTabs();
    const b2 = session.sidebarGroupDropBoundary(cardRowOf(session, 2), 1).?;
    try std.testing.expectEqual(@as(usize, 3), b2);
    try expectDropEquivalent(session, 1, .{ .group_sibling = .{ .insert_before = b2 } });
    try std.testing.expectEqual(x, session.tabs.items[1]); // X가 다시 A·B 사이(index1)
    try std.testing.expect(x.top_level); // top_level 불변
    try std.testing.expect(session.enclosingGroupMarkerIndex(1) == null);
    try std.testing.expectEqual(@as(u8, 0), session.effectiveDepthAt(1, null, null)); // depth 0
    var markers: usize = 0;
    for (session.tabs.items) |t| if (t.group_start != null) {
        markers += 1;
    };
    try std.testing.expectEqual(@as(usize, 2), markers); // 형제 그룹 2개 유지
}

test "SR4 그룹드래그(d): 고정 리전 인터리빙 clamp — 고정 그룹은 고정 top카드와 순서 교환하되 비고정 리전으로 못 넘어간다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4] 5개 사용
    // 고정 리전 [Xp(t0,pin,top_level), A=[a0(t1,pin,마커), a1(t2,pin,멤버)]] + 비고정 [t3, t4].
    inline for (0..3) |i| {
        session.tabs.items[i].pinned = true;
    }
    const xp = session.tabs.items[0];
    xp.top_level = true;
    try setGroupMarker(session, 1, "A", 1);
    session.recomputeVisibleTabs();

    // ① 고정 그룹 A(마커1)를 고정 top카드 Xp 앞으로 → 경계 0, clamp 유지(고정 리전 [0, pinned_count] 안). 프리뷰=확정 등가.
    const b1 = session.sidebarGroupDropBoundary(cardRowOf(session, 0), 1).?;
    try std.testing.expectEqual(@as(usize, 0), b1);
    try std.testing.expectEqual(@as(usize, 0), session.clampGroupMoveToRegion(1, b1)); // 고정 리전 안이라 clamp no-op
    try expectDropEquivalent(session, 1, .{ .group_sibling = .{ .insert_before = session.clampGroupMoveToRegion(1, b1) } });
    // 결과 [A=[a0,a1], Xp, t3, t4] — Xp 고정·top_level 유지, 그룹 A 고정 프리픽스 유지.
    const xp_idx = blk: {
        for (session.tabs.items, 0..) |t, i| if (t == xp) break :blk i;
        break :blk session.tabs.items.len;
    };
    try std.testing.expectEqual(@as(usize, 2), xp_idx);
    try std.testing.expect(xp.pinned); // ★ 고정 유지(비고정 리전으로 안 샘)
    try std.testing.expect(xp.top_level);
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned); // A 고정 프리픽스

    // ② 고정 그룹을 **비고정 타겟**(t3)으로 끌어도 clamp가 고정 경계(pinned_count)로 가둔다(비고정 리전 침범 방지, GP3 정합).
    session.recomputeVisibleTabs();
    const raw = session.sidebarGroupDropBoundary(cardRowOf(session, 3), 0) orelse 0; // A 마커는 이제 index0
    const clamped = session.clampGroupMoveToRegion(0, raw);
    try std.testing.expect(clamped <= session.countPinnedTabs()); // ★ 고정 리전 경계 넘지 않음(프리뷰=확정 공통 clamp)
    _ = session.moveGroupRange(0, clamped, false);
    try std.testing.expect(session.tabs.items[0].pinned and session.tabs.items[1].pinned and session.tabs.items[2].pinned); // 고정 3개 유지
    try std.testing.expect(!session.tabs.items[3].pinned and !session.tabs.items[4].pinned); // 비고정 2개 유지
}

test "SG5-1: 헤더 클릭(접기 토글) vs 헤더 드래그(그룹 통째 이동)를 threshold로 구분 (mouse 시뮬레이션)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0, t1, t2, t3]
    const t0 = session.tabs.items[0];
    const t1 = session.tabs.items[1];
    const t2 = session.tabs.items[2];
    const t3 = session.tabs.items[3];

    // 두 **형제** 그룹: A=t0에서 시작(t0,t1), B=t2에서 시작(t2,t3). 연속 파티션 [A][B], 최상위 없음.
    // SG5-3: create_group은 그룹 안 카드에서 depth+1 중첩이라, t2에 부르면 B가 A 자식이 된다. 형제 헤더 드래그/접기
    // 토글을 보는 테스트라 B의 depth를 1로 명시해 형제 최상위 그룹으로 둔다(§9 create_group 중첩 tension 문서화).
    session.createGroupAbsorbForTab(t0); // A(마커 index0)
    session.createGroupAbsorbForTab(t2); // B(마커 index2) — 중첩 기본
    t2.group_depth = 1; // B를 최상위 형제로 오버라이드

    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const header_row_h = session.sidebar_header_row_h_px;
    const slot_h = session.sidebar_slot_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const rowCenterY = struct {
        fn f(s: *AppSession, row: usize, hh: u32, sh: u32, hrh: u32) f64 {
            const top = sb.rowTop(s.sidebar_rows.items, row, hh, sh, hrh, 0);
            const rh = sb.rowHeight(s.sidebar_rows.items[row], sh, hrh);
            return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
        }
    }.f;

    // ── ① 헤더 드래그(threshold 초과) = 그룹 통째 이동. 헤더 A(row0)를 잡아 그룹 B 카드(row4) 위로 끈다.
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]
    const headerA_y = rowCenterY(session, 0, header_h, slot_h, header_row_h);
    session.mouse(1, x, headerA_y, 0, 0); // down on 헤더 A → 접기 토글 후보로 arm(즉시 토글 아님)
    try std.testing.expect(session.sidebar_group_drag_armed);
    try std.testing.expect(!session.sidebar_group_drag_active); // 아직 threshold 전
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_group_drag_marker); // 마커 A(t0, index0)
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // 아직 토글 안 됨(down만으론)
    const groupB_card_y = rowCenterY(session, 4, header_h, slot_h, header_row_h);
    session.mouse(2, x, groupB_card_y, 0, 0); // drag 멀리 → threshold 초과 → 그룹 통째 드래그(SG8e 비커밋 프리뷰)
    try std.testing.expect(session.sidebar_group_drag_active); // 승격됨
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰(subtree 고스트)
    // self.tabs는 드래그 중 불변 — 확정은 up. 원래 순서 [t0(A),t1,t2(B),t3] 유지.
    try std.testing.expectEqual(t0, session.tabs.items[0]);
    try std.testing.expectEqual(t1, session.tabs.items[1]);
    try std.testing.expectEqual(t2, session.tabs.items[2]);
    try std.testing.expectEqual(t3, session.tabs.items[3]);
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // 드래그는 접기 토글 아님
    session.mouse(3, x, groupB_card_y, 0, 0); // up → 마지막 plan(group_sibling) 1회 커밋
    // 결과 [t2(B), t3, t0(A), t1] — A 그룹 통째가 B 뒤로. 연속 파티션 유지(라이브 시절과 동일 = 등가).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t3, session.tabs.items[1]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    try std.testing.expectEqual(t1, session.tabs.items[3]);
    try std.testing.expect(session.tabs.items[0].group_start != null); // B 마커
    try std.testing.expect(session.tabs.items[2].group_start != null); // A 마커
    try std.testing.expect(!session.sidebar_group_drag_armed);
    try std.testing.expect(!session.sidebar_group_drag_active);
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨

    // ── ② 헤더 클릭(threshold 미달 = move 없음) = 접기 토글. 헤더 B(현 row0)를 down→up(움직임 없음).
    session.recomputeVisibleTabs(); // [hB(0), c t2(1), c t3(2), hA(3), c t0(4), c t1(5)]
    const headerB_y = rowCenterY(session, 0, header_h, slot_h, header_row_h);
    const order_before = [_]*Tab{ session.tabs.items[0], session.tabs.items[1], session.tabs.items[2], session.tabs.items[3] };
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // B(index0) 펼침
    session.mouse(1, x, headerB_y, 0, 0); // down → arm
    try std.testing.expect(session.sidebar_group_drag_armed);
    session.mouse(3, x, headerB_y, 0, 0); // up(움직임 없음) → 접기 토글
    try std.testing.expect(session.tabs.items[0].group_collapsed); // B 접힘(클릭=토글)
    try std.testing.expect(!session.sidebar_group_drag_armed);
    for (order_before, 0..) |p, i| try std.testing.expectEqual(p, session.tabs.items[i]); // 순서 불변(이동 없음)

    // ── ③ 헤더 살짝만 움직이고 up(threshold 미달) = 여전히 접기 토글(그룹 이동 아님). B는 접힘 상태 → 펼치기 토글.
    session.recomputeVisibleTabs(); // [hB(0,collapsed), hA(1), c t0(2), c t1(3)]
    const headerB2_y = rowCenterY(session, 0, header_h, slot_h, header_row_h);
    const order_before2 = [_]*Tab{ session.tabs.items[0], session.tabs.items[1], session.tabs.items[2], session.tabs.items[3] };
    session.mouse(1, x, headerB2_y, 0, 0); // down → arm
    session.mouse(2, x, headerB2_y + 1, 0, 0); // 아주 살짝(dy=1 < threshold) → active 승격 안 됨
    try std.testing.expect(!session.sidebar_group_drag_active); // threshold 미달
    for (order_before2, 0..) |p, i| try std.testing.expectEqual(p, session.tabs.items[i]); // 순서 불변
    session.mouse(3, x, headerB2_y + 1, 0, 0); // up → 접기 토글(threshold 미달이라 클릭 취급)
    try std.testing.expect(!session.tabs.items[0].group_collapsed); // B 다시 펼침(토글)
    try std.testing.expect(!session.sidebar_group_drag_armed);
}

/// SG5-4 테스트 헬퍼 — 탭 idx에 그룹 시작 마커(owned dup) + depth를 세팅한다. 위치 파생 구조를 정밀하게 짜기 위해
/// create_group의 위치 의존 depth 계산 대신 직접 마커를 얹는다(session.deinit이 group_start를 free).
fn setGroupMarker(session: *AppSession, idx: usize, name: []const u8, depth: u8) !void {
    session.tabs.items[idx].group_start = try session.allocator.dupe(u8, name);
    session.tabs.items[idx].group_depth = depth;
}

test "SG5-4: 그룹을 다른 그룹 헤더에 드롭 → 중첩(depth+1) + subtree 상대 depth 유지 (moveGroupNesting)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..5) |_| _ = try session.newTab(); // [t0..t5] 6개
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    const t4 = session.tabs.items[4];
    const t5 = session.tabs.items[5];

    // A=[t0,t1] 직접 + C 중첩=[t2,t3](depth2, A 안), B=[t4,t5](depth1, A 형제). 위치 파생 정밀 구성(마커 직접).
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "C", 2); // A 안 중첩
    try setGroupMarker(session, 4, "B", 1); // A 형제(최상위)
    // 초기 depth 확인.
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // A 마커 카드
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t2)); // C(A 자식)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B(최상위)

    // ── 드래그: A(마커 index0)를 B 헤더에 드롭 → B의 자식으로 중첩. projectRows로 B 헤더 row를 찾아 groupNestPlan에 넘긴다.
    session.recomputeVisibleTabs();
    var b_header_row: usize = 0;
    for (session.sidebar_rows.items, 0..) |row, s| switch (row) {
        .group_header => |gh| if (gh.tab == 4) {
            b_header_row = s;
        },
        .card => {},
    };
    const plan = session.groupNestPlan(b_header_row, 0).?; // B 헤더 → 중첩 계획
    try std.testing.expectEqual(@as(u8, 2), plan.target_depth); // B eff1 + 1
    const r = session.moveGroupNesting(0, plan.insert_before, plan.target_depth);
    try std.testing.expect(r.changed);

    // 결과: A가 B의 자식(depth2), C는 A의 자식(depth3) — **상대 depth 유지**(C는 A보다 1 깊음 유지).
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t0)); // A → B 자식(depth2)
    try std.testing.expectEqual(@as(?u8, 3), sidebarCardDepth(session, t2)); // C → A 자식(depth3, 상대 유지)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B 최상위 유지
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t5)); // B 직접 카드

    // 트리 연속(gap 없음)·연속 파티션: projectRows가 유효 트리를 낸다(부모 직접 카드가 자식 헤더 앞). 헤더 depth로 확인.
    session.recomputeVisibleTabs();
    var depths: [3]u8 = undefined;
    var hc: usize = 0;
    var prev_marker_ok = true;
    for (session.sidebar_rows.items) |row| switch (row) {
        .group_header => |gh| {
            if (hc < depths.len) depths[hc] = gh.depth;
            hc += 1;
            if (gh.depth > 2 and hc == 1) prev_marker_ok = false; // 첫 헤더가 갑자기 깊으면 gap
        },
        .card => {},
    };
    try std.testing.expectEqual(@as(usize, 3), hc); // B·A·C 세 헤더
    try std.testing.expectEqual(@as(u8, 1), depths[0]); // B 최상위
    try std.testing.expectEqual(@as(u8, 2), depths[1]); // A(B 자식)
    try std.testing.expectEqual(@as(u8, 3), depths[2]); // C(A 자식) — 1,2,3 연속(gap 없음)
}

test "SG5-4: 중첩 그룹을 최상위 카드에 드롭 → 빼기(depth 1) (moveGroupSibling + gap-clamp)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4] 5개
    const t3 = session.tabs.items[3];
    const t4 = session.tabs.items[4];

    // t0 최상위, A=[t1,t2](depth1), B 중첩=[t3,t4](depth2, A 안).
    try setGroupMarker(session, 1, "A", 1);
    try setGroupMarker(session, 3, "B", 2); // A 안 중첩
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t3)); // B 중첩(depth2)

    // ── 드래그: B(마커 index3)를 최상위 카드 t0(row0)에 드롭 → 빼기(최상위 depth1로). 카드 드롭이라 형제 경로.
    session.recomputeVisibleTabs(); // [c t0(0), hA(1), c t1(2), c t2(3), hB(4), c t3(5), c t4(6)]
    try std.testing.expect(session.groupNestPlan(0, 3) == null); // row0=카드 → 중첩 아님(형제 경로)
    const boundary = session.sidebarGroupDropBoundary(0, 3).?; // 최상위 카드 → 첫 그룹 앞
    const r = session.moveGroupSibling(3, boundary);
    try std.testing.expect(r.changed);

    // B가 최상위(depth1)로 빠짐. 저장 group_depth도 gap-clamp eff(1)로 맞춰진다(gap 제거).
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t3)); // 빼기 성공(depth1)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t4)); // B 직접 카드
    // B 마커 탭의 저장 depth가 1로 정규화됐는지(releveel).
    var b_stored: ?u8 = null;
    for (session.tabs.items) |t| if (t.group_start != null and std.mem.eql(u8, t.group_start.?, "B")) {
        b_stored = t.group_depth;
    };
    try std.testing.expectEqual(@as(?u8, 1), b_stored); // releveel로 저장 depth도 1
}

test "SG5-4: 카드 드래그 — 중첩 자식 그룹 안(자식 depth)·최상위(depth0)로 depth 파생 (sidebarGroupDropTargetTab)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 40,
        .rows = 10,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    inline for (0..4) |_| _ = try session.newTab(); // [t0..t4]
    const t0 = session.tabs.items[0];

    // t0 최상위, A=[t1,t2](depth1), B 중첩=[t3,t4](depth2). t0를 B 안으로 / 최상위로 옮겨 depth 파생 확인.
    try setGroupMarker(session, 1, "A", 1);
    try setGroupMarker(session, 3, "B", 2);
    session.recomputeVisibleTabs(); // [c t0(0), hA(1), c t1(2), c t2(3), hB(4), c t3(5), c t4(6)]

    // ── ① t0를 B의 카드(t4, row6)에 드롭 → B 소속(depth2, 중첩 자식). 카드 row → 그 위치로 위치 파생.
    {
        const target = session.sidebarGroupDropTargetTab(6, 0).?; // B 카드 t4(index4)
        _ = session.moveTab(0, target);
    }
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t0)); // 자식 B 안 = depth2

    // ── ② 다시 t0(현재 B 안)를 최상위로 — 재정렬로 첫 그룹 앞으로 빼기. moveTab(현 index → 0)로 최상위 앞.
    var t0_idx: usize = 0;
    for (session.tabs.items, 0..) |t, i| if (t == t0) {
        t0_idx = i;
    };
    _ = session.moveTab(t0_idx, 0); // 맨 앞(첫 마커 이전 = 최상위)
    try std.testing.expectEqual(@as(?u8, 0), sidebarCardDepth(session, t0)); // 최상위 = depth0
}

test "SG5-4/N2: 그룹 헤더를 다른 그룹 헤더에 Cmd(⌘) 드롭 → 중첩 (mouse 시뮬레이션 — 통합)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];

    // 두 형제 그룹 A=[t0,t1](depth1), B=[t2,t3](depth1).
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "B", 1);
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]

    const sb = chrome.components.sidebar;
    const header_h = session.sidebar_header_height_px;
    const header_row_h = session.sidebar_header_row_h_px;
    const slot_h = session.sidebar_slot_height_px;
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);
    const rowCenterY = struct {
        fn f(s: *AppSession, row: usize, hh: u32, shh: u32, hrh: u32) f64 {
            const top = sb.rowTop(s.sidebar_rows.items, row, hh, shh, hrh, 0);
            const rh = sb.rowHeight(s.sidebar_rows.items[row], shh, hrh);
            return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
        }
    }.f;

    // 헤더 A(row0)를 잡아 헤더 B(row3) 위로 **Cmd(⌘, mods=32) 드래그** → A가 B의 자식으로 중첩(Cmd=중첩 정책).
    const CMD: i32 = 32;
    const headerA_y = rowCenterY(session, 0, header_h, slot_h, header_row_h);
    session.mouse(1, x, headerA_y, 0, CMD); // down on 헤더 A → arm
    try std.testing.expect(session.sidebar_group_drag_armed);
    const headerB_y = rowCenterY(session, 3, header_h, slot_h, header_row_h);
    session.mouse(2, x, headerB_y, 0, CMD); // Cmd 드래그 → threshold 초과 → 헤더 드롭=중첩 plan의 **비커밋 프리뷰**(SG8e)
    try std.testing.expect(session.sidebar_group_drag_active);
    try std.testing.expect(session.sidebar_drag_preview != null); // 비커밋 프리뷰(subtree 고스트, B 자식 depth로 들여쓰기)
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_nest); // Cmd → 중첩 plan

    // 드래그 중 self.tabs 불변 — sidebar_rows(hit-test 도메인)는 아직 중첩 전(원본 depth). 확정은 up.
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // B 최상위(불변)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // A 아직 최상위(프리뷰만 중첩)
    session.mouse(3, x, headerB_y, 0, CMD); // up → 마지막 plan(group_nest) 1회 커밋
    // 결과: A가 B의 자식(depth2). B는 최상위(depth1). t0(A 카드)=depth2(라이브 시절과 동일 = 등가).
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2)); // B 최상위
    try std.testing.expectEqual(@as(?u8, 2), sidebarCardDepth(session, t0)); // A → B 자식(중첩)
    try std.testing.expect(!session.sidebar_group_drag_armed);
    try std.testing.expect(session.sidebar_drag_preview == null); // 프리뷰 정리됨
}

// ── 그룹 드래그 "Cmd=중첩 / 없으면 형제" modifier 매트릭스(N/P/R/B) 공용 헬퍼 ─────────────────────────────────────────
// 표시 row의 세로 중앙 y(backing px, scroll=0). 그룹 드래그 mouse 시뮬레이션 테스트가 공유한다(N2와 같은 산식).
fn sbRowCenterY(s: *AppSession, row: usize) f64 {
    const sb = chrome.components.sidebar;
    const top = sb.rowTop(s.sidebar_rows.items, row, s.sidebar_header_height_px, s.sidebar_slot_height_px, s.sidebar_header_row_h_px, 0);
    const rh = sb.rowHeight(s.sidebar_rows.items[row], s.sidebar_slot_height_px, s.sidebar_header_row_h_px);
    return @floatFromInt(top + @as(i64, @intCast(rh / 2)));
}

// 두 형제 최상위 그룹 A=[t0,t1]·B=[t2,t3]을 만든 4-탭 세션. 호출자가 defer deinit/destroy. cols 넉넉히 잡아 사이드바+본문 확보.
fn makeTwoSiblingGroups(allocator: std.mem.Allocator) !*AppSession {
    const session = try allocator.create(AppSession);
    errdefer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);
    inline for (0..3) |_| _ = try session.newTab(); // [t0..t3]
    try setGroupMarker(session, 0, "A", 1);
    try setGroupMarker(session, 2, "B", 1);
    session.recomputeVisibleTabs(); // [hA(0), c t0(1), c t1(2), hB(3), c t2(4), c t3(5)]
    return session;
}

test "N1: 그룹 헤더를 다른 헤더에 Cmd 없이 드롭 → 형제(group_sibling, 중첩 안 됨·depth 불변)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try makeTwoSiblingGroups(allocator);
    defer allocator.destroy(session);
    defer session.deinit();
    const t0 = session.tabs.items[0];
    const t2 = session.tabs.items[2];
    const x: f64 = @floatFromInt(session.sidebar_width_px / 2);

    // 헤더 A(row0)를 헤더 B(row3)에 **Cmd 없이(mods=0)** 드래그 → 형제(중첩 아님).
    session.mouse(1, x, sbRowCenterY(session, 0), 0, 0); // down → arm
    try std.testing.expect(session.sidebar_group_drag_armed);
    session.mouse(2, x, sbRowCenterY(session, 3), 0, 0); // drag onto 헤더 B
    try std.testing.expect(session.sidebar_drag_preview != null);
    try std.testing.expect(session.sidebar_drag_preview.?.plan == .group_sibling); // Cmd 없음 → 형제(중첩 절대 안 함)
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 드래그 중 depth 불변
    session.mouse(3, x, sbRowCenterY(session, 3), 0, 0); // up → 형제 이동 커밋
    // 결과 [t2(B), t3, t0(A), t1] — A가 B 뒤 형제로. depth 둘 다 1(중첩 없음).
    try std.testing.expectEqual(t2, session.tabs.items[0]);
    try std.testing.expectEqual(t0, session.tabs.items[2]);
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t0)); // 최상위 유지
    try std.testing.expectEqual(@as(?u8, 1), sidebarCardDepth(session, t2));
    try std.testing.expect(session.sidebar_drag_preview == null);
}

test "N3: 그룹 헤더를 카드에 Cmd 없이 드롭 → 형제" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
