    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    // 검색 줄(헤더 하단)을 클릭 → 검색 활성, 키 포커스가 검색으로 라우팅.
    const search_x: f64 = @as(f64, @floatFromInt(session.sidebar_width_px)) * 0.5;
    const search_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) * 0.8;
    try std.testing.expectEqual(chrome.components.sidebar.HeaderRegion.search, chrome.components.sidebar.headerHit(search_x, search_y, session.sidebar_width_px, session.cell_width_px, session.cell_height_px, session.sidebar_header_height_px));
    session.mouse(1, search_x, search_y, 0, 0);
    try std.testing.expect(session.sidebar_search_active);
    try std.testing.expectEqual(AppSession.InputFocus.sidebar_search, session.inputFocus());

    // 검색어를 입력한 채 터미널 본문 클릭 → blur(검색어 '보존'), 키 포커스가 터미널로 복구.
    session.sidebar_search_input.appendChar(allocator, 'a') catch {};
    const term_x: f64 = @floatFromInt(session.active_pane_rect.x + 50);
    const term_y: f64 = @floatFromInt(session.active_pane_rect.y + 50);
    session.mouse(1, term_x, term_y, 0, 0);
    try std.testing.expect(!session.sidebar_search_active);
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());
    try std.testing.expectEqualStrings("a", session.sidebar_search_input.query.items); // blur는 검색어를 안 지운다

    // 다시 검색 활성 → 검색어가 그대로 이어진다(초안 보존).
    session.mouse(1, search_x, search_y, 0, 0);
    try std.testing.expect(session.sidebar_search_active);
    try std.testing.expectEqualStrings("a", session.sidebar_search_input.query.items);

    // 사이드바 카드 슬롯 클릭도 blur(카드 전환 + 검색 비활성, 검색어 보존).
    const card_x: f64 = @as(f64, @floatFromInt(session.cell_width_px));
    const card_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) + @as(f64, @floatFromInt(session.sidebar_slot_height_px)) * 0.5; // 슬롯 0 중앙
    session.mouse(1, card_x, card_y, 0, 0);
    try std.testing.expect(!session.sidebar_search_active);
    try std.testing.expectEqual(AppSession.InputFocus.terminal, session.inputFocus());

    // Esc 경로(closeSidebarSearch)만 검색어를 완전히 비운다 — blur와 구분.
    session.mouse(1, search_x, search_y, 0, 0); // 재활성
    session.closeSidebarSearch();
    try std.testing.expect(!session.sidebar_search_active);
    try std.testing.expectEqual(@as(usize, 0), session.sidebar_search_input.query.items.len);
}

// P4: view options(⚙) 메뉴 — ⚙ 클릭 → 표시 토글 메뉴 열림, 항목 클릭 시 show-branch/folder를 뒤집고(즉시 카드
// 반영) 메뉴는 열린 채(체크박스 패널), config persist 예약(config_dirty_keys)에 키를 넣는다. 바깥 클릭=닫힘.
// 실 좌표 hit-test + config 토글이라 macOS 게이트.
test "view options menu: ⚙ toggles sidebar show-branch/folder, stays open, signals config persist" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{}; // 레이아웃 기하만 격리
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const init_branch = session.loaded_config.config.sidebar.show_branch;
    const init_folder = session.loaded_config.config.sidebar.show_folder;

    // ⚙ 아이콘(헤더 상단 우측 view_options zone [w-6cw, w-3cw), ⚙ col=cols-5) 클릭 → view options 메뉴 열림.
    const gear_x: f64 = @as(f64, @floatFromInt(session.sidebar_width_px)) - @as(f64, @floatFromInt(session.cell_width_px)) * 4;
    const gear_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) * 0.2; // 상단 아이콘 줄
    try std.testing.expectEqual(chrome.components.sidebar.HeaderRegion.view_options, chrome.components.sidebar.headerHit(gear_x, gear_y, session.sidebar_width_px, session.cell_width_px, session.cell_height_px, session.sidebar_header_height_px));
    session.mouse(1, gear_x, gear_y, 0, 0);
    try std.testing.expect(session.view_options_menu);
    try std.testing.expect(session.chrome_host.context_menu.open);

    // 항목 0(브랜치 표시) 선택·accept → show_branch 토글 + 메뉴 유지 + persist 신호(1회성).
    session.chrome_host.context_menu.selected = 0;
    session.acceptContextMenu();
    try std.testing.expectEqual(!init_branch, session.loaded_config.config.sidebar.show_branch);
    try std.testing.expect(session.view_options_menu); // 체크박스 패널 — 닫히지 않는다
    try std.testing.expect(session.takeConfigDirty()); // persist 예약 — true(dirty 키 있음)
    session.config_dirty_keys.clearRetainingCapacity(); // serializeConfig가 하는 일(파일 IO 없이 계약만 확인)
    try std.testing.expect(!session.takeConfigDirty()); // 비워짐 — false

    // 항목 1(폴더 표시) 토글 — 메뉴 유지.
    session.chrome_host.context_menu.selected = 1;
    session.acceptContextMenu();
    try std.testing.expectEqual(!init_folder, session.loaded_config.config.sidebar.show_folder);
    try std.testing.expect(session.view_options_menu);

    // 메뉴 밖(터미널) 클릭 → 닫힘(view_options 플래그·메뉴 상태 모두 해제).
    const out_x: f64 = @floatFromInt(session.active_pane_rect.x + 50);
    const out_y: f64 = @floatFromInt(session.active_pane_rect.y + 50);
    session.mouse(1, out_x, out_y, 0, 0);
    try std.testing.expect(!session.view_options_menu);
    try std.testing.expect(!session.chrome_host.context_menu.open);
}

// 세팅 화면 토글 → 선택 행 bool config flip(라이브) + config_dirty_keys persist 예약(CS-4-4c). 실제 파일 write는
// Swift atomic write(사이드바와 같은 경로 — 일반화)라 여기선 메모리 flip + dirty 예약까지 헤드리스로 고정한다.
test "settings 드롭다운 통합: enum 행 활성→팝업 열림·변형 목록·applyDropdownSelection로 config 변경+영속" {
    // 이 테스트가 증명하는 것: enum 행 활성이 드롭다운 팝업을 현재값에서 열고(toggleSelectedSetting), buildSettingsDropdownItems가
    // 그 enum의 변형 목록을 주며(enumVariants), 다른 인덱스를 확정하면 applyDropdownSelection이 config enum을 그 값으로 바꾸고
    // (setEnumIndex) 팝업을 닫고 영속을 예약한다 — 설정 enum 선택의 플랫폼 전 경로(라이브 프리뷰·확정의 코어).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.toggleSettings();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    // 실제 스키마 enum(theme.preset synthetic 제외)이 있는 섹션·행을 찾는다(bool→num→enum 순 인덱싱).
    var enum_row: ?usize = null;
    var enum_key: []const u8 = "";
    for (sections, 0..) |_, si| {
        session.chrome_host.settings.section = si;
        const cf = try session.currentSectionFields(scratch.allocator());
        for (cf.enums, 0..) |e, ei| {
            if (std.mem.eql(u8, e.key, "theme.preset")) continue; // synthetic — 별도 경로
            enum_row = cf.bools.len + cf.nums.len + ei;
            enum_key = e.key;
            break;
        }
        if (enum_row != null) break;
    }
    try std.testing.expect(enum_row != null); // 스키마 enum 행이 존재
    session.refreshSettingsFieldCount();
    session.chrome_host.settings.selected = enum_row.?;
    _ = session.takeConfigDirty(); // 이전 dirty 비우기

    // 활성 → 드롭다운 팝업 열림 + 현재 인덱스에서 시작.
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.dropdown.open);
    const cur = config_mod.schema.enumIndex(session.loaded_config.config, enum_key).?;
    try std.testing.expectEqual(cur, session.chrome_host.settings.dropdown.selected);

    // buildSettingsDropdownItems가 그 enum의 변형 목록을 준다.
    const items = try session.buildSettingsDropdownItems(scratch.allocator());
    const variants = (try config_mod.schema.enumVariants(scratch.allocator(), session.loaded_config.config, enum_key)).?;
    try std.testing.expectEqual(variants.len, items.len);

    // 다른 인덱스 확정 → config enum 변경 + 팝업 닫힘 + dirty 예약.
    const target = (cur + 1) % variants.len;
    session.chrome_host.settings.dropdown.selected = target;
    session.applyDropdownSelection();
    try std.testing.expect(!session.chrome_host.settings.dropdown.open);
    try std.testing.expectEqual(@as(?usize, target), config_mod.schema.enumIndex(session.loaded_config.config, enum_key));
    try std.testing.expect(session.takeConfigDirty()); // 영속 예약됨
}

test "settings 숫자 입력 박스 커밋: 편집→파싱→범위 clamp로 config 변경 (슬라이더 대체)" {
    // 이 테스트가 증명하는 것: number 행 활성이 입력 박스 편집을 열고(현재값 시드), 범위 초과 값을 타이핑해 커밋하면
    // commitSelectedText가 파싱→setNumber(범위 clamp)로 config를 max로 고정하고 영속을 예약한다 — 프로그레스바를
    // 대체한 숫자 직접 입력의 핵심(잘못된 값이 range 밖으로 새지 않음).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.toggleSettings();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var num_row: ?usize = null;
    var num_key: []const u8 = "";
    var num_max: f64 = 0;
    for (sections, 0..) |_, si| {
        session.chrome_host.settings.section = si;
        const cf = try session.currentSectionFields(scratch.allocator());
        if (cf.nums.len > 0) {
            num_row = cf.bools.len; // 첫 number(bool 다음)
            num_key = cf.nums[0].key;
            num_max = cf.nums[0].max;
            break;
        }
    }
    try std.testing.expect(num_row != null); // number 행이 존재
    session.refreshSettingsFieldCount();
    session.chrome_host.settings.selected = num_row.?;
    _ = session.takeConfigDirty();

    // 활성 → 편집 진입(입력 박스, 현재값 시드). 편집 버퍼를 범위 초과 값으로 덮고 커밋 → clamp.
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.editing);
    session.chrome_host.settings.enterEdit("999999"); // 범위 초과
    session.commitSelectedText();
    try std.testing.expect(!session.chrome_host.settings.editing); // 커밋 후 편집 종료
    try std.testing.expect(session.takeConfigDirty()); // 영속 예약

    // config number가 max로 clamp됐는지 — 재빌드해 그 키의 값 확인(f32 저장 반올림 허용).
    session.chrome_host.settings.selected = num_row.?;
    const cf2 = try session.currentSectionFields(scratch.allocator());
    var found = false;
    for (cf2.nums) |n| {
        if (std.mem.eql(u8, n.key, num_key)) {
            found = true;
            try std.testing.expectApproxEqAbs(num_max, n.value, 0.01); // 999999 → max로 clamp
        }
    }
    try std.testing.expect(found);
}

test "settingsPaletteArrowIntercept: 팔레트 행 폼-포커스 ←→=셀 이동, 셀0(←)·셀15(→) 끝은 미가로채기(영역 이동)" {
    // 이 테스트가 증명하는 것: 팔레트 그리드 행(폼 포커스)의 ←→가 16색 셀을 이동하되, ← 셀0·→ 셀15(끝)에선 가로채지
    // 않아(false) 컴포넌트의 영역 포커스 이동으로 이어진다는 엣지-이탈 규칙. 네비 포커스면 가로채지 않는다(폼 전용).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.toggleSettings();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var pal_row: ?usize = null;
    for (sections, 0..) |_, si| {
        session.chrome_host.settings.section = si;
        const cf = try session.currentSectionFields(scratch.allocator());
        if (cf.paletteRowIndex()) |pi| {
            pal_row = pi;
            break;
        }
    }
    try std.testing.expect(pal_row != null); // 팔레트 그리드 행 존재(테마 섹션)
    session.refreshSettingsFieldCount();
    session.chrome_host.settings.selected = pal_row.?;
    session.chrome_host.settings.nav_focused = false; // 폼 포커스
    session.chrome_host.settings.grid_cell = 0;

    const left = terminal.KeyEvent{ .key = .arrow_left, .modifiers = .{} };
    const right = terminal.KeyEvent{ .key = .arrow_right, .modifiers = .{} };

    // ← 셀0 → 미가로채기(false — 컴포넌트 영역 이동으로), grid_cell 불변.
    try std.testing.expect(!session.settingsPaletteArrowIntercept(left));
    try std.testing.expectEqual(@as(usize, 0), session.chrome_host.settings.grid_cell);
    // → 셀0 → 가로채기(셀 이동) grid_cell→1.
    try std.testing.expect(session.settingsPaletteArrowIntercept(right));
    try std.testing.expectEqual(@as(usize, 1), session.chrome_host.settings.grid_cell);
    // 셀15에서 → → 미가로채기(끝).
    session.chrome_host.settings.grid_cell = 15;
    try std.testing.expect(!session.settingsPaletteArrowIntercept(right));
    // 셀5에서 ← → 가로채기 grid_cell→4.
    session.chrome_host.settings.grid_cell = 5;
    try std.testing.expect(session.settingsPaletteArrowIntercept(left));
    try std.testing.expectEqual(@as(usize, 4), session.chrome_host.settings.grid_cell);
    // 네비 포커스면 미가로채기(폼 전용).
    session.chrome_host.settings.nav_focused = true;
    session.chrome_host.settings.grid_cell = 5;
    try std.testing.expect(!session.settingsPaletteArrowIntercept(right));
}

test "settingsPaletteArrowIntercept: 검색 중에도 팔레트 ←→ 셀 이동 살아있음(검색 필터 인덱스 정합)" {
    // 이 테스트가 증명하는 것: 검색 상태에서도 팔레트 행 ←→가 셀을 움직인다(사용자 요청). currentSectionFields가 검색
    // 필터를 적용해 paletteRowIndex와 selected가 같은 필터-인덱스라 정합하고, 검색의 ←→는 원래 소비만 되던 미사용 키다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.toggleSettings();

    // "palette"로 검색(theme.palette 키 부분일치) → 교차 검색으로 팔레트 행이 나온다.
    const s = &session.chrome_host.settings;
    s.startSearch();
    for ("palette") |c| s.appendSearchCp(c);
    try std.testing.expect(s.searching);
    session.refreshSettingsFieldCount();

    // 필터된 필드에서 팔레트 행 인덱스를 찾아 selected로(검색 필터가 적용된 인덱스라 intercept와 정합).
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const cf = try session.currentSectionFields(scratch.allocator());
    const pi = cf.paletteRowIndex() orelse return error.TestUnexpectedResult;
    s.selected = pi;
    s.nav_focused = false;
    s.grid_cell = 5;

    const right = terminal.KeyEvent{ .key = .arrow_right, .modifiers = .{} };
    const left = terminal.KeyEvent{ .key = .arrow_left, .modifiers = .{} };
    // 검색 중이어도 → 셀 이동(가로챔) grid_cell→6, ← → 5.
    try std.testing.expect(session.settingsPaletteArrowIntercept(right));
    try std.testing.expectEqual(@as(usize, 6), s.grid_cell);
    try std.testing.expect(session.settingsPaletteArrowIntercept(left));
    try std.testing.expectEqual(@as(usize, 5), s.grid_cell);
    try std.testing.expect(s.searching); // 검색은 그대로 유지
}

test "settings 폰트 드롭다운 취소: 커스텀(번들 밖) 폰트 복원 (데이터 손실 회귀 가드)" {
    // 이 테스트가 증명하는 것: 번들 목록 밖 커스텀 폰트에서 드롭다운을 열고 번들 폰트를 라이브 프리뷰한 뒤 취소하면,
    // 인덱스가 아니라 **열 때 스냅샷한 원본 문자열**로 복원된다(인덱스 기반 복원이 커스텀 폰트를 첫 번들로 덮어써
    // 잃던 code-review 데이터 손실 수정). 확정 경로가 아닌 취소가 원본을 지켜야 한다.
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.loaded_config.config.font.family = "Menlo"; // 번들 밖 커스텀(정적 문자열)
    session.toggleSettings();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var font_row: ?usize = null;
    for (sections, 0..) |_, si| {
        session.chrome_host.settings.section = si;
        const cf = try session.currentSectionFields(scratch.allocator());
        for (cf.texts, 0..) |t, tii| if (std.mem.eql(u8, t.key, "font.family")) {
            font_row = cf.bools.len + cf.nums.len + cf.enums.len + tii;
        };
        if (font_row != null) break;
    }
    try std.testing.expect(font_row != null);
    session.refreshSettingsFieldCount();
    session.chrome_host.settings.selected = font_row.?;

    // 열기 → 스냅샷(kind=.font, "Menlo"), cur_idx="직접 입력…" 슬롯(=번들 수, 목록 밖이라).
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.dropdown.open);
    // 첫 번들 폰트를 라이브 프리뷰 → font.family가 바뀐다.
    session.chrome_host.settings.dropdown.selected = 0;
    session.applyDropdownPreview();
    try std.testing.expectEqualStrings(config_mod.theme.bundled_font_families[0], session.loaded_config.config.font.family);
    // 취소 → 원본 "Menlo" 복원(첫 번들로 안 남음).
    session.cancelDropdownSelection();
    try std.testing.expect(!session.chrome_host.settings.dropdown.open);
    try std.testing.expectEqualStrings("Menlo", session.loaded_config.config.font.family);
}

test "settings 테마 프리셋 드롭다운 취소: 커스텀 테마 색·잠금 복원 (데이터 손실 회귀 가드)" {
    // 이 테스트가 증명하는 것: 커스텀 테마("사용자 지정")에서 프리셋 드롭다운을 열고 프리셋을 라이브 프리뷰한 뒤
    // 취소하면, 인덱스가 아니라 **열 때 스냅샷한 원본 색·잠금 플래그**로 복원된다(applyThemePresetIndex(n)이 색을
    // 안 되돌려 커스텀 테마를 잃던 code-review 데이터 손실 수정).
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.loaded_config.config.theme_follow_system = false; // theme.preset 행이 보이게
    session.theme_user_custom = true; // 커스텀(프리셋 아님)
    session.loaded_config.config.theme.background = "#070b0d"; // 프리셋과 안 겹칠 커스텀 색(hex 문자열)
    const orig_bg = session.loaded_config.config.theme.background;
    session.toggleSettings();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var preset_row: ?usize = null;
    for (sections, 0..) |_, si| {
        session.chrome_host.settings.section = si;
        const cf = try session.currentSectionFields(scratch.allocator());
        for (cf.enums, 0..) |e, ei| if (std.mem.eql(u8, e.key, "theme.preset")) {
            preset_row = cf.bools.len + cf.nums.len + ei;
        };
        if (preset_row != null) break;
    }
    try std.testing.expect(preset_row != null); // theme.preset 행 존재
    session.refreshSettingsFieldCount();
    session.chrome_host.settings.selected = preset_row.?;

    // 열기 → 스냅샷(kind=.preset, 커스텀 색·user_custom). 첫 프리셋 프리뷰 → 색이 바뀐다.
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.dropdown.open);
    session.chrome_host.settings.dropdown.selected = 0;
    session.applyDropdownPreview();
    try std.testing.expect(!std.mem.eql(u8, session.loaded_config.config.theme.background, orig_bg)); // 프리뷰로 바뀜
    try std.testing.expect(!session.theme_user_custom); // 프리셋 적용이 잠금
    // **핵심 회귀 가드(code-review high)**: 미리보기는 인메모리만 — 파일 영속을 예약하면 안 된다(theme_preset_persist·dirty 없음).
    try std.testing.expect(session.theme_preset_persist == null);
    try std.testing.expect(!session.takeConfigDirty());

    // 취소 → 원본 커스텀 색·user_custom 복원 + **파일 영속도 없음**(미리본 프리셋이 disk에 안 써짐).
    session.cancelDropdownSelection();
    try std.testing.expectEqualStrings(orig_bg, session.loaded_config.config.theme.background);
    try std.testing.expect(session.theme_user_custom);
    try std.testing.expect(session.theme_preset_persist == null); // theme.preset 줄 예약 없음
    try std.testing.expect(!session.takeConfigDirty()); // 커스텀 색 줄이 disk에서 안 지워짐
}

