    try std.testing.expectEqualStrings("", session.loaded_config.config.window_background_image);

    // (4) 빈 경로 provide(취소 등)는 무동작 — 직전 빈 값 유지.
    session.providePickedFile("");
    try std.testing.expectEqualStrings("", session.loaded_config.config.window_background_image);
}

test "settings HSV picker 스포이드 ABI: settings_eyedropper→pending, take 1회성, provide→picker 반영 (v83)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // picker 열기(검정 시드).
    session.chrome_host.settings.openPicker(.{ .r = 0, .g = 0, .b = 0 });
    // dispatchChromeAction(.settings_eyedropper) → color_sample_pending.
    session.dispatchChromeAction(.settings_eyedropper);
    try std.testing.expect(session.takeColorSampleRequest()); // Swift가 drain
    try std.testing.expect(!session.takeColorSampleRequest()); // 1회성
    // Swift NSColorSampler 콜백 → provideSampledColor → picker 반영(#ff0080 근사).
    session.provideSampledColor(.{ .r = 0xff, .g = 0, .b = 0x80 });
    try std.testing.expectEqual(@as(u8, 0xff), session.chrome_host.settings.pickerRgb().r);
    try std.testing.expectEqual(@as(u8, 0x80), session.chrome_host.settings.pickerRgb().b);
    // picker 닫힌 뒤 provide는 무시(setPickerRgb 가드).
    session.chrome_host.settings.closePicker();
    session.provideSampledColor(.{ .r = 0x10, .g = 0x20, .b = 0x30 });
    // 닫혔으니 pick 값 안 바뀜(여전히 #ff0080 근사) — picking=false라 setPickerRgb 무동작.
    try std.testing.expectEqual(@as(u8, 0xff), session.chrome_host.settings.pickerRgb().r);
}

