        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // theme 섹션 선택(네비에서 theme 인덱스 찾기 — 기본 config 기준).
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var theme_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .theme) {
        theme_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = theme_idx;

    // 팔레트 그리드 행은 theme 섹션 마지막(color 뒤). paletteRowIndex로 selected 설정.
    const cf = try session.currentSectionFields(scratch.allocator());
    try std.testing.expect(cf.has_palette);
    const pi = cf.paletteRowIndex().?;
    session.chrome_host.settings.selected = pi;

    // 셀 5 선택 → Enter(toggle) = 편집 시작(기본 미override라 xterm256(5) 시드).
    session.chrome_host.settings.grid_cell = 5;
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.editing);

    // 편집 버퍼를 새 hex로 바꿔 커밋 → palette[5]=#abcdef, dirty=theme.palette.5(write-back이 직렬화).
    session.chrome_host.settings.enterEdit("#abcdef");
    session.config_dirty_keys.clearRetainingCapacity();
    session.commitSelectedText();
    try std.testing.expect(session.loaded_config.config.theme.palette[5] != null);
    try std.testing.expectEqualStrings("#abcdef", session.loaded_config.config.theme.palette[5].?);
    try std.testing.expect(!session.chrome_host.settings.editing); // 커밋 후 편집 종료
    var found = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, "theme.palette.5")) {
        found = true;
    };
    try std.testing.expect(found);

    // ←/→(adjust) = 선택 셀 이동(색 변경 아님, wrap).
    session.chrome_host.settings.grid_cell = 5;
    session.adjustSelectedSetting(1);
    try std.testing.expectEqual(@as(usize, 6), session.chrome_host.settings.grid_cell);
    session.adjustSelectedSetting(-1);
    try std.testing.expectEqual(@as(usize, 5), session.chrome_host.settings.grid_cell);

    // 잘못된 hex는 거부(기존값 유지) — 파일 로드와 같은 검증.
    session.chrome_host.settings.selected = pi;
    session.chrome_host.settings.grid_cell = 5;
    session.chrome_host.settings.enterEdit("#gggggg");
    session.commitSelectedText();
    try std.testing.expectEqualStrings("#abcdef", session.loaded_config.config.theme.palette[5].?); // 거부 — 유지
}

test "settings HSV picker 커밋: theme color 행 Enter→picker 열림, pickerRgb()→#rrggbb setText + dirty (CS-4-6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var theme_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .theme) {
        theme_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = theme_idx;

    // theme 섹션 첫 color 행 선택(bool+num+enum+text 다음).
    const cf = try session.currentSectionFields(scratch.allocator());
    try std.testing.expect(cf.colors.len > 0);
    const first_color = cf.bools.len + cf.nums.len + cf.enums.len + cf.texts.len;
    session.chrome_host.settings.selected = first_color;
    const key = cf.colors[0].key;

    // Enter(toggle) → HSV picker 열림(현재 색 시드).
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.picking);

    // 순수 빨강으로 설정 후 커밋 → 그 color 키 = #ff0000, dirty 예약, picker 닫힘.
    session.chrome_host.settings.pick_h = 0;
    session.chrome_host.settings.pick_s = 100;
    session.chrome_host.settings.pick_v = 100;
    session.config_dirty_keys.clearRetainingCapacity();
    session.commitPickerColor();
    try std.testing.expect(!session.chrome_host.settings.picking); // 커밋 후 닫힘(폼 복귀)
    var found = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, key)) {
        found = true;
    };
    try std.testing.expect(found);

    // 재빌드한 color 값이 빨강으로 갱신(포맷/대소문자 무관하게 parse해 RGB 비교).
    const cf2 = try session.currentSectionFields(scratch.allocator());
    const rgb = try config_mod.appearance.parseHexColor(cf2.colors[0].value);
    try std.testing.expectEqual(@as(u8, 255), rgb.r);
    try std.testing.expectEqual(@as(u8, 0), rgb.g);
    try std.testing.expectEqual(@as(u8, 0), rgb.b);
}

test "settings keybind recorder: 입력 섹션 행 녹음→캡처→rebind + 영속 예약, Esc 취소 (CS-4-3)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 입력 섹션 선택.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try session.currentSectionFields(scratch.allocator());
    try std.testing.expect(cf.keybind_entries.len == command_catalog.entries.len); // 쿼리 없으면 전부
    const ks = cf.keybindRowStart().?;

    // new_term은 command_catalog.entries[0] — 그 keybind 행 선택 → Enter(toggle) = 녹음 시작.
    session.chrome_host.settings.selected = ks; // entries[0]=new_term
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.recording);

    // Cmd+E 캡처 → new_term이 Cmd+E로 rebind + dirty 예약 + 녹음 종료.
    session.config_keybind_rebinds.clearRetainingCapacity();
    session.captureKeybindRecording(.{ .key = .{ .char = 'E' }, .modifiers = .{ .command = true } });
    try std.testing.expect(!session.chrome_host.settings.recording);
    const resolver = session.loaded_config.keyBindingResolver();
    const chord = command_catalog.chordForAction(resolver, .new_term).?;
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+E")).eql(chord)); // resolver가 새 chord 반영
    try std.testing.expect(session.takeConfigDirty()); // write-back 예약됨
    var saw = false;
    for (session.config_keybind_rebinds.items) |rb| if (std.mem.eql(u8, rb.action, "new_term") and std.mem.eql(u8, rb.chord, "Cmd+E")) {
        saw = true;
    };
    try std.testing.expect(saw);

    // 평범한 Esc 캡처 → 취소(rebind 안 함, dirty 변화 없음).
    session.chrome_host.settings.selected = ks;
    session.chrome_host.settings.recording = true;
    const before = session.config_keybind_rebinds.items.len;
    session.captureKeybindRecording(.{ .key = .escape, .modifiers = .{} });
    try std.testing.expect(!session.chrome_host.settings.recording);
    try std.testing.expectEqual(before, session.config_keybind_rebinds.items.len); // 변화 없음
}

test "settings global hotkey: .global_hotkey 섹션 3행 노출 + rebind가 global_bindings 교체·큐 적재, descriptorFor null 거부, Backspace 해제 (PR1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // .global_hotkey 섹션은 schema 필드가 없어도 좌측 네비에 강제로 들어간다.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var gh_idx: ?usize = null;
    for (sections, 0..) |s, i| if (s.section == .global_hotkey) {
        gh_idx = i;
    };
    try std.testing.expect(gh_idx != null);

    session.chrome_host.settings.show();
    session.chrome_host.settings.section = gh_idx.?;
    const cf = try session.currentSectionFields(scratch.allocator());
    // 전역 행 3개(toggle_window/show_window/toggle_quick_terminal), schema·keybind 행 없음.
    try std.testing.expectEqual(@as(usize, 3), cf.global_entries.len);
    try std.testing.expectEqual(@as(usize, 0), cf.keybind_entries.len);
    const gs = cf.globalKeybindRowStart().?;
    try std.testing.expectEqual(gs, cf.total() - 3); // 맨 끝 3행

    // global_entries[0]=toggle_window 행 선택 → Enter(toggle) = 녹음 시작.
    session.chrome_host.settings.selected = gs;
    session.toggleSelectedSetting();
    try std.testing.expect(session.chrome_host.settings.recording);

    // Cmd+Alt+Space 캡처 → toggle_window가 그 chord로 rebind + global_bindings 교체 + 큐 적재 + 녹음 종료.
    session.captureKeybindRecording(.{ .key = .{ .char = ' ' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expect(!session.chrome_host.settings.recording);
    const chord = command_catalog.chordForGlobalAction(session.loaded_config.global_bindings, .toggle_window).?;
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+Alt+Space")).eql(chord)); // global_bindings 교체 반영
    try std.testing.expect(session.takeConfigDirty());
    var saw = false;
    for (session.config_global_rebinds.items) |rb| if (std.mem.eql(u8, rb.action, "toggle_window") and std.mem.eql(u8, rb.chord, "Cmd+Alt+Space")) {
        saw = true;
    };
    try std.testing.expect(saw); // write-back 큐 적재

    // descriptorFor가 null인 chord(Cmd+Plus — 가상 키코드 매핑 없음)는 거부(global_bindings·큐 불변).
    const before_len = session.loaded_config.global_bindings.len;
    const before_q = session.config_global_rebinds.items.len;
    session.chrome_host.settings.selected = gs;
    session.chrome_host.settings.recording = true;
    session.captureKeybindRecording(.{ .key = .{ .char = '+' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(before_len, session.loaded_config.global_bindings.len); // 거부 — 불변
    try std.testing.expectEqual(before_q, session.config_global_rebinds.items.len);
    // 거부돼도 toggle_window는 여전히 Cmd+Alt+Space.
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+Alt+Space")).eql(command_catalog.chordForGlobalAction(session.loaded_config.global_bindings, .toggle_window).?));

    // Backspace로 해제 → global_bindings에서 제거 + 줄 제거 예약 + 펜딩 rebind 취소.
    const cf2 = try session.currentSectionFields(scratch.allocator());
    session.chrome_host.settings.selected = cf2.globalKeybindRowStart().?; // toggle_window 행
    session.deleteSelectedSettingRow();
    try std.testing.expect(command_catalog.chordForGlobalAction(session.loaded_config.global_bindings, .toggle_window) == null);
    var saw_removed = false;
    for (session.config_global_removed.items) |k| if (std.mem.eql(u8, k, "toggle_window")) {
        saw_removed = true;
    };
    try std.testing.expect(saw_removed);
    for (session.config_global_rebinds.items) |rb| try std.testing.expect(!std.mem.eql(u8, rb.action, "toggle_window")); // 펜딩 취소
}

test "global hotkey live re-register: rebuildGlobalHotkeys가 descriptor 재생성·매핑 불가 제외, rebind/unbind/reload/reset이 dirty, takeGlobalHotkeysDirty 1회성 (PR2)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // init은 dirty를 세우지 않는다(앱 시작 시 Swift가 어차피 한 번 register). 기본 config엔 전역 바인딩이 없어 목록도 빈다.
    try std.testing.expect(!session.global_hotkeys_dirty);
    try std.testing.expectEqual(@as(usize, 0), session.globalHotkeys().len);

    // GUI 녹음으로 toggle_window를 Cmd+Alt+Space에 rebind → rebuildGlobalHotkeys가 descriptor 1개를 만들고 dirty=true.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var gh_idx: ?usize = null;
    for (sections, 0..) |s, i| if (s.section == .global_hotkey) {
        gh_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = gh_idx.?;
    const cf = try session.currentSectionFields(scratch.allocator());
    const gs = cf.globalKeybindRowStart().?;
    session.chrome_host.settings.selected = gs; // toggle_window 행
    session.toggleSelectedSetting(); // 녹음 시작
    session.captureKeybindRecording(.{ .key = .{ .char = ' ' }, .modifiers = .{ .command = true, .option = true } });
    try std.testing.expectEqual(@as(usize, 1), session.globalHotkeys().len); // descriptor 재생성(매핑 가능 chord)
    try std.testing.expect(session.global_hotkeys_dirty); // rebind가 dirty 세움

    // takeGlobalHotkeysDirty는 1회성 — 첫 호출 true·리셋, 둘째 false.
    try std.testing.expect(session.takeGlobalHotkeysDirty());
    try std.testing.expect(!session.takeGlobalHotkeysDirty());
    try std.testing.expect(!session.global_hotkeys_dirty);

    // 매핑 불가 chord는 descriptor에서 제외된다 — global_bindings에 직접 등록 불가 chord를 넣고 rebuild하면 목록이 빈다.
    var list: std.ArrayList(config_mod.GlobalBinding) = .empty;
    const a = session.loaded_config.arena.allocator();
    try list.append(a, .{ .chord = try config_mod.KeyChord.parse("Cmd+Plus"), .action = .toggle_window }); // 가상 키코드 매핑 없음
    session.loaded_config.global_bindings = try list.toOwnedSlice(a);
    try session.rebuildGlobalHotkeys();
    try std.testing.expectEqual(@as(usize, 0), session.globalHotkeys().len); // descriptorFor null → 제외

    // GUI unbind(행 Backspace)도 dirty를 세운다 — 매핑 가능 chord로 다시 묶은 뒤 해제.
    session.chrome_host.settings.selected = gs;
    session.toggleSelectedSetting();
    session.captureKeybindRecording(.{ .key = .{ .char = ' ' }, .modifiers = .{ .command = true, .option = true } });
    _ = session.takeGlobalHotkeysDirty(); // rebind dirty 소비
    const cf2 = try session.currentSectionFields(scratch.allocator());
    session.chrome_host.settings.selected = cf2.globalKeybindRowStart().?;
    session.deleteSelectedSettingRow();
    try std.testing.expect(session.global_hotkeys_dirty); // unbind가 dirty 세움
    try std.testing.expectEqual(@as(usize, 0), session.globalHotkeys().len); // 해제 후 빈 목록

    // resetAllSettings도 dirty를 세운다 — 기본값엔 전역 바인딩이 없어 목록을 비우고 라이브 재등록 신호.
    // (reloadConfig도 같은 wiring으로 dirty를 세우지만, 파일 I/O 의존이라 디스크 상태와 무관한 reset으로 검증한다.)
    // 안전 가드: resetAllSettings가 configPath()에 파일을 쓰므로 실 config 대신 tmp로 박는다(실 config 보호).
    var reset_tmp = std.testing.tmpDir(.{});
    defer reset_tmp.cleanup();
    var reset_path_buf: [4096]u8 = undefined;
    const reset_cfg_path = try std.fmt.bufPrint(&reset_path_buf, ".zig-cache/tmp/{s}/config", .{reset_tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, reset_cfg_path);
    _ = session.takeGlobalHotkeysDirty();
    session.resetAllSettings();
    try std.testing.expect(session.global_hotkeys_dirty);
    try std.testing.expectEqual(@as(usize, 0), session.globalHotkeys().len);
}

test "reloadConfig: 옛 arena 문자열을 가리키는 write-back 대기열을 비운다 — use-after-free 방지 (리뷰)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 옛 loaded_config arena의 문자열을 가리키는 두 큐를 시드한다(이 리뷰가 다룬 UAF 부류):
    //  ① theme_preset_persist — persistThemePreset이 arena에 프리셋 이름을 dupe.
    //  ② config_keybind_unbind_removed — arena dupe한 chord 문자열.
    session.persistThemePreset(.gruvbox_dark);
    try std.testing.expect(session.theme_preset_persist != null);
    const a = session.loaded_config.arena.allocator();
    try session.config_keybind_unbind_removed.append(allocator, try a.dupe(u8, "cmd+shift+x"));
    try std.testing.expect(session.config_keybind_unbind_removed.items.len > 0);

    // reloadConfig는 옛 arena를 deinit한다 — clearConfigDirty로 위 큐를 비우지 않으면 두 슬라이스가 dangling이 되고
    // 다음 serializeConfig가 freed 메모리를 읽는다. 비우면 null·빈 목록이라 안전.
    session.reloadConfig();
    try std.testing.expect(session.theme_preset_persist == null);
    try std.testing.expectEqual(@as(usize, 0), session.config_keybind_unbind_removed.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.config_dirty_keys.items.len);
    try std.testing.expectEqual(@as(usize, 0), session.config_removed_keys.items.len);
}

test "settings keybind unbind: keybind 행 Backspace → 사용자 바인딩 해제 + 줄 제거 예약, 펜딩 rebind 취소 (keybind unbind)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try session.currentSectionFields(scratch.allocator());
    const ks = cf.keybindRowStart().?;
    session.chrome_host.settings.selected = ks; // entries[0]=new_term

    // 먼저 new_term을 Cmd+E로 rebind(사용자 바인딩 생성 + 펜딩).
    session.chrome_host.settings.recording = true;
    session.captureKeybindRecording(.{ .key = .{ .char = 'E' }, .modifiers = .{ .command = true } });
    var has_user_bind = false;
    for (session.loaded_config.keybindings) |b| if (std.meta.activeTag(b.action) == .new_term) {
        has_user_bind = true;
    };
    try std.testing.expect(has_user_bind);

    // 이제 Backspace로 unbind → 사용자 바인딩 제거 + 빌트인 chord(Cmd+T) unbind 지시어 예약 + 줄 제거 + 펜딩 rebind 취소.
    session.deleteSelectedSettingRow();
    for (session.loaded_config.keybindings) |b| try std.testing.expect(std.meta.activeTag(b.action) != .new_term); // 사용자 바인딩 사라짐
    // 완전 해제 — chordForAction(new_term)이 null(사용자 Cmd+E 제거 + 빌트인 Cmd+T unbinds로 죽음).
    try std.testing.expect(command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .new_term) == null);
    var saw_removed = false;
    for (session.config_keybind_removed.items) |k| if (std.mem.eql(u8, k, "new_term")) {
        saw_removed = true;
    };
    try std.testing.expect(saw_removed); // 사용자 줄 제거 예약
    var saw_unbind = false; // 빌트인 Cmd+T unbind 지시어 예약
    for (session.config_keybind_unbinds.items) |c| if (std.mem.eql(u8, c, "Cmd+T")) {
        saw_unbind = true;
    };
    try std.testing.expect(saw_unbind);
    for (session.config_keybind_rebinds.items) |rb| try std.testing.expect(!std.mem.eql(u8, rb.action, "new_term")); // 펜딩 rebind 취소
    try std.testing.expect(session.takeConfigDirty());

    // 이미 해제된 액션을 다시 unbind 시도 → notice 경로(무동작, keybindings 불변).
    const cf2 = try session.currentSectionFields(scratch.allocator());
    session.chrome_host.settings.selected = cf2.keybindRowStart().?;
    const len_before = session.loaded_config.keybindings.len;
    session.deleteSelectedSettingRow();
    try std.testing.expectEqual(len_before, session.loaded_config.keybindings.len); // 불변(이미 미지정)
}

test "settings keybind 충돌: 이미 다른 액션에 묶인 chord로 rebind → 폼 상단 배너(세팅 유지, rebind는 진행)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;
    const cf = try session.currentSectionFields(scratch.allocator());
    session.chrome_host.settings.selected = cf.keybindRowStart().?; // entries[0]=new_term

    // new_term을 close_term의 빌트인 Cmd+W로 rebind → 충돌(다른 액션에 이미 묶임) → 폼 상단 배너 경고(세팅 유지).
    session.chrome_host.settings.recording = true;
    session.captureKeybindRecording(.{ .key = .{ .char = 'W' }, .modifiers = .{ .command = true } });
    try std.testing.expect(session.chrome_host.settings.message().len > 0); // 배너 경고 표시(세팅 자체 그리드)
    try std.testing.expect(!session.chrome_host.notice.open); // notice 토스트가 아님(세팅을 안 닫는다)
    try std.testing.expect(session.chrome_host.settings.open); // 세팅 모달 유지(회귀 가드 — 예전엔 showNotice가 닫았다)
    // rebind는 진행됨 — new_term이 Cmd+W로(사용자 바인딩 우선, last-wins).
    const chord = command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .new_term).?;
    try std.testing.expect((try config_mod.KeyChord.parse("Cmd+W")).eql(chord));
}

test "settings 전역 단축키 등록 불가 키: 폼 상단 배너(세팅 유지) — 사용자 제보 '설정창이 꺼짐' 회귀 가드" {
