    // 두 빌트인 chord가 모두 죽어 next_tab이 **완전히** 미지정(하나만 죽이는 회귀면 첫 chord가 남아 non-null).
    try std.testing.expect(command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .next_tab) == null);
    try std.testing.expect(session.config_keybind_unbinds.items.len >= 2); // chord 2개 다 unbind 지시어 예약
}

test "settings keybind 완전 교체: rebind하면 그 액션 빌트인 chord가 죽는다 — 옛 키+새 키가 아니라 새 키만 (키바인드 완전 교체)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // next_tab 엔트리를 새 chord(Cmd+E — next_tab 빌트인 ⇧⌘]/⇧⌘}와 다른 자유 chord)로 rebind.
    const new_chord = try config_mod.KeyChord.parse("Cmd+E");
    var entry: ?command_catalog.Entry = null;
    for (command_catalog.entries) |e| if (std.mem.eql(u8, e.key, "next_tab")) {
        entry = e;
    };
    try std.testing.expect(entry != null);
    session.config_keybind_unbinds.clearRetainingCapacity();
    session.rebindActionEntry(entry.?, new_chord);

    const resolver = session.loaded_config.keyBindingResolver();
    // (1) next_tab의 effective chord = 새 Cmd+E(사용자 바인딩).
    try std.testing.expect(command_catalog.chordForAction(resolver, .next_tab).?.eql(new_chord));
    // (2) **핵심**: next_tab의 빌트인 chord(새 chord 아님)는 전부 unbinds에 들어가 죽었다 — 옛 키가 더는 next_tab을 안 함.
    //     (add-only 회귀면 빌트인이 unbinds에 없어 옛 키가 살아 있다.)
    var had_builtin = false;
    for (config_mod.keybinding.default_app_bindings) |db| if (std.meta.eql(db.action, .next_tab) and !db.chord.eql(new_chord)) {
        had_builtin = true;
        var found = false;
        for (session.loaded_config.unbinds) |u| if (u.eql(db.chord)) {
            found = true;
        };
        try std.testing.expect(found); // 빌트인 chord가 unbind됨(라이브)
    };
    try std.testing.expect(had_builtin); // next_tab엔 죽일 빌트인이 있었다(테스트 전제)
    // (3) 영속: 빌트인 unbind 지시어가 예약됐다(파일에 keybind = chord = unbind).
    try std.testing.expect(session.config_keybind_unbinds.items.len >= 1);
}

test "settings keybind stale unbind 정리: unbind한 chord를 다시 바인딩하면 unbinds에서 빠지고 옛 줄 제거 예약 (stale unbind)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // (1) next_tab을 unbind → 빌트인 chord(들)가 loaded_config.unbinds + 펜딩 unbind-append에 들어간다.
    var nt: ?command_catalog.Entry = null;
    for (command_catalog.entries) |e| if (std.mem.eql(u8, e.key, "next_tab")) {
        nt = e;
    };
    session.unbindActionEntry(nt.?);
    var target: ?config_mod.KeyChord = null;
    for (config_mod.keybinding.default_app_bindings) |db| if (std.meta.eql(db.action, .next_tab)) {
        target = db.chord;
    };
    try std.testing.expect(target != null);
    var was_unbound = false;
    for (session.loaded_config.unbinds) |u| if (u.eql(target.?)) {
        was_unbound = true;
    };
    try std.testing.expect(was_unbound); // 그 chord가 지금 죽어 있다

    // (2) 다른 액션(previous_tab)을 그 죽은 chord로 rebind → stale unbind 정리.
    var pt: ?command_catalog.Entry = null;
    for (command_catalog.entries) |e| if (std.mem.eql(u8, e.key, "previous_tab")) {
        pt = e;
    };
    session.config_keybind_unbind_removed.clearRetainingCapacity();
    session.rebindActionEntry(pt.?, target.?);

    // (3) 그 chord가 loaded_config.unbinds에서 빠졌다(부활) + previous_tab의 effective chord가 됐다.
    var still = false;
    for (session.loaded_config.unbinds) |u| if (u.eql(target.?)) {
        still = true;
    };
    try std.testing.expect(!still);
    try std.testing.expect(command_catalog.chordForAction(session.loaded_config.keyBindingResolver(), .previous_tab).?.eql(target.?));
    // (4) 옛 `keybind = chord = unbind` 줄 제거가 예약됐다(파일 위생).
    var chord_buf: [command_catalog.max_chord_display_len]u8 = undefined;
    const cs = target.?.toConfigString(&chord_buf);
    var reserved = false;
    for (session.config_keybind_unbind_removed.items) |c| if (std.mem.eql(u8, c, cs)) {
        reserved = true;
    };
    try std.testing.expect(reserved);
}

test "settings 검색 필터: 쿼리로 keybind/schema 행 필터 + 필터 후 인덱스가 올바른 액션에 매핑 (CS-4-4 검색)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var input_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .input) {
        input_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = input_idx;

    // **교차 섹션** 검색 "split"(현재 섹션=input이지만 쿼리가 있으면 전 섹션) → workspace.split-inherit-cwd(bool, 키에
    // "split") + Split Right/Down keybind 2개. enum은 "split" 미매칭(0).
    session.chrome_host.settings.startSearch();
    for ("split") |c| session.chrome_host.settings.appendSearchCp(c);
    const cf = try session.currentSectionFields(scratch.allocator());
    try std.testing.expectEqual(@as(usize, 0), cf.enums.len); // "split" 미매칭
    try std.testing.expect(cf.bools.len >= 1); // 교차 섹션: workspace.split-inherit-cwd(다른 섹션) 매칭
    try std.testing.expectEqual(@as(usize, 2), cf.keybind_entries.len); // Split Right, Split Down
    for (cf.keybind_entries) |e| try std.testing.expect(std.ascii.indexOfIgnoreCase(e.title, "split") != null);

    // keybindRowStart는 앞선 schema 행(여기선 split bool 등) 다음. 그 행 녹음→캡처가 **필터된 첫 keybind 엔트리**(Split Right)를
    // rebind해야 한다(교차 섹션 필터 후에도 인덱스 정합 — keybindRowStart가 정확히 keybind_entries[0]을 가리킨다).
    const ks = cf.keybindRowStart().?;
    session.chrome_host.settings.selected = ks;
    session.chrome_host.settings.recording = true;
    session.config_keybind_rebinds.clearRetainingCapacity();
    session.captureKeybindRecording(.{ .key = .{ .char = 'J' }, .modifiers = .{ .command = true } });
    try std.testing.expectEqual(@as(usize, 1), session.config_keybind_rebinds.items.len);
    // 재바인딩된 action 키 = 필터된 목록의 첫 엔트리 키(엉뚱한 액션이 아니라).
    try std.testing.expectEqualStrings(cf.keybind_entries[0].key, session.config_keybind_rebinds.items[0].action);

    // 빈 쿼리(검색 종료)면 현재 섹션(input)만 복귀 — keybind 전부 + input enum.
    session.chrome_host.settings.endSearch();
    const cf2 = try session.currentSectionFields(scratch.allocator());
    try std.testing.expectEqual(command_catalog.entries.len, cf2.keybind_entries.len);
    try std.testing.expect(cf2.enums.len > 0); // input dropdown 복귀
    try std.testing.expectEqual(@as(usize, 5), cf2.bools.len); // input 섹션 bool = mouse-hide-while-typing(F1-6) + option-as-meta(F2-2) + keyhint.enabled(KH-3) + paste-protection + bracketed-paste-is-safe 5개(split bool은 workspace라 검색 끝나 사라짐)
}

test "mouse-hide-while-typing: IME 확정(글자) 입력 시 takeMouseHide 신호(1회성), 한글·meta chord·config off 구분 (F1-6)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.loaded_config.config.input.mouse_hide_while_typing = true;

    // 평범한 글자 'a' 입력은 macOS에서 IME(NSTextInputClient) 확정으로 routeCommittedText를 탄다(handleKeyEvent 우회).
    // 터미널 focus라 숨김 신호. takeMouseHide는 1회성(다음 호출 false).
    session.routeCommittedText("a");
    try std.testing.expect(session.takeMouseHide());
    try std.testing.expect(!session.takeMouseHide()); // drain됨

    // 한글/CJK도 같은 IME 확정 경로 → 숨김(옛 구현은 handleKeyEvent .char만 봐서 CJK를 놓쳤다 — code-review max).
    session.routeCommittedText("한");
    try std.testing.expect(session.takeMouseHide());

    // Option+글자 같은 meta chord는 handleKeyEvent .terminal_input로 오지만 타이핑이 아닌 nav chord라 안 숨김
    // (mouse_hide 판정을 그 경로에서 뺐다 — 옛 구현은 여기서 숨겨 의도가 역전됐었다).
    _ = try session.handleKeyEvent(.{ .key = .{ .char = 'b' }, .modifiers = .{ .option = true } });
    try std.testing.expect(!session.takeMouseHide());

    // config off면 글자여도 안 숨김(기본 false = 현행).
    session.loaded_config.config.input.mouse_hide_while_typing = false;
    session.routeCommittedText("c");
    try std.testing.expect(!session.takeMouseHide());
}

test "settings env 삭제: Backspace로 env.<KEY> 행 삭제 → config.env에서 제거 + 줄 삭제 예약 (env delete)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var term_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .terminal) {
        term_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = term_idx;

    // env 두 개 추가(setEnvVar 경유).
    session.setEnvVar("FOO", "bar");
    session.setEnvVar("BAZ", "qux");
    try std.testing.expectEqual(@as(usize, 2), session.loaded_config.config.env.len);

    // env.FOO 행을 selected로(text 구간에서 key=="env.FOO" 찾기).
    const cf = try session.currentSectionFields(scratch.allocator());
    const after_enums = cf.bools.len + cf.nums.len + cf.enums.len;
    var foo_sel: ?usize = null;
    for (cf.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, "env.FOO")) {
        foo_sel = after_enums + i;
    };
    session.chrome_host.settings.selected = foo_sel.?;

    // Backspace 삭제 → FOO 제거, BAZ 유지 + dirty 제거 키.
    session.config_removed_keys.clearRetainingCapacity();
    session.deleteSelectedSettingRow();
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len);
    try std.testing.expectEqualStrings("BAZ=qux", session.loaded_config.config.env[0]);
    try std.testing.expect(session.takeConfigDirty());
    var saw = false;
    for (session.config_removed_keys.items) |k| if (std.mem.eql(u8, k, "env.FOO")) {
        saw = true;
    };
    try std.testing.expect(saw);

    // 추가 sentinel 행("env.")이나 shell.args 행에서 삭제 시도 → 무동작(env 변화 없음).
    const cf2 = try session.currentSectionFields(scratch.allocator());
    const after_enums2 = cf2.bools.len + cf2.nums.len + cf2.enums.len;
    var sa_sel: ?usize = null;
    for (cf2.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, "shell.args")) {
        sa_sel = after_enums2 + i;
    };
    session.chrome_host.settings.selected = sa_sel.?;
    session.deleteSelectedSettingRow();
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len); // 그대로
}

test "settings env/shell.args: terminal 섹션 synthetic text 행 — shell.args 분리·env upsert·추가 행 파싱 (CS-4-5)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // terminal 섹션 선택.
    var scratch = std.heap.ArenaAllocator.init(allocator);
    defer scratch.deinit();
    const sections = try session.buildSectionList(scratch.allocator());
    var term_idx: usize = 0;
    for (sections, 0..) |s, i| if (s.section == .terminal) {
        term_idx = i;
    };
    session.chrome_host.settings.show();
    session.chrome_host.settings.section = term_idx;

    // text 행 key로 selected 인덱스를 찾는 헬퍼(인라인): selected = bools+nums+enums + (cf.texts 안 인덱스).
    const selForTextKey = struct {
        fn f(s: *AppSession, a: std.mem.Allocator, key: []const u8) ?usize {
            const c = s.currentSectionFields(a) catch return null;
            const base = c.bools.len + c.nums.len + c.enums.len;
            for (c.texts, 0..) |t, i| if (std.mem.eql(u8, t.key, key)) return base + i;
            return null;
        }
    }.f;

    // shell.args 행 편집 "-i -l" → 공백 분리 토큰 2개 + dirty "shell.args".
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "shell.args").?;
    session.chrome_host.settings.enterEdit("-i -l");
    session.config_dirty_keys.clearRetainingCapacity();
    session.commitSelectedText();
    try std.testing.expectEqual(@as(usize, 2), session.loaded_config.config.shell.args.len);
    try std.testing.expectEqualStrings("-i", session.loaded_config.config.shell.args[0]);
    try std.testing.expectEqualStrings("-l", session.loaded_config.config.shell.args[1]);
    var saw_sa = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, "shell.args")) {
        saw_sa = true;
    };
    try std.testing.expect(saw_sa);

    // env 추가 행("env." sentinel) 편집 "FOO=bar" → config.env에 "FOO=bar" + dirty "env.FOO".
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "env.").?;
    session.chrome_host.settings.enterEdit("FOO=bar");
    session.config_dirty_keys.clearRetainingCapacity();
    session.commitSelectedText();
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len);
    try std.testing.expectEqualStrings("FOO=bar", session.loaded_config.config.env[0]);
    var saw_foo = false;
    for (session.config_dirty_keys.items) |k| if (std.mem.eql(u8, k, "env.FOO")) {
        saw_foo = true;
    };
    try std.testing.expect(saw_foo);

    // 이제 "env.FOO" 행이 생겼다 — 값만 "baz"로 편집 → upsert(교체, 추가 아님).
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "env.FOO").?;
    session.chrome_host.settings.enterEdit("baz");
    session.commitSelectedText();
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len); // 교체 — 개수 그대로
    try std.testing.expectEqualStrings("FOO=baz", session.loaded_config.config.env[0]);

    // 추가 행에 '=' 없는 입력 → 무시(env 변화 없음).
    session.chrome_host.settings.selected = selForTextKey(session, scratch.allocator(), "env.").?;
    session.chrome_host.settings.enterEdit("INVALID");
    session.commitSelectedText();
    try std.testing.expectEqual(@as(usize, 1), session.loaded_config.config.env.len); // 그대로
}

test "detectThemePreset / applyThemePreset / resetAllSettings: 테마 프리셋·통합 리셋" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // detectThemePreset: 프리셋 색 세트는 그 프리셋으로 식별, 임의 색은 null.
    session.loaded_config.config.theme = config_mod.theme.presetColors(.dracula);
    try std.testing.expectEqual(config_mod.theme.ThemePreset.dracula, AppSession.detectThemePreset(session.loaded_config.config.theme).?);
    session.loaded_config.config.theme.background = "#123456";
    try std.testing.expect(AppSession.detectThemePreset(session.loaded_config.config.theme) == null); // 사용자 지정

    // applyThemePreset: dir=+1 적용 → config.theme가 그 프리셋 색 + **theme.preset 영속 예약**(개별 색·palette는 제거
    // 예약 — 4색만 쓰던 옛 한계 해소, 팔레트 영속 리뷰). theme.preset 한 줄이 로더에서 16색 팔레트까지 통째로 펼쳐진다.
    session.loaded_config.config.theme = config_mod.theme.presetColors(.maru);
    session.applyThemePreset(1); // maru → 다음(ghostty)
    try std.testing.expectEqualStrings(config_mod.theme.presetColors(.ghostty).background, session.loaded_config.config.theme.background);
    try std.testing.expectEqual(config_mod.theme.ThemePreset.ghostty, AppSession.detectThemePreset(session.loaded_config.config.theme).?);
    try std.testing.expect(session.theme_preset_persist != null);
    try std.testing.expectEqualStrings("ghostty", session.theme_preset_persist.?); // dashed 이름(파일에 theme.preset = ghostty)
    var saw_bg_removed = false;
    for (session.config_removed_keys.items) |k| if (std.mem.eql(u8, k, "theme.background")) {
        saw_bg_removed = true; // 개별 색은 제거 예약(theme.preset이 base를 깔므로 충돌 방지)
    };
    try std.testing.expect(saw_bg_removed);

    // resetAllSettings: 모든 config를 기본값으로 + **config 파일을 기본 상태로 덮어쓰기**(삭제 아님 — 파일·경로 보존) +
    // dirty 비움(부분 write-back 안 함). 안전: 실제 사용자 config가 아니라 tmp 파일을 덮어쓰도록 config_path_buffer를 박는다.
    const io = std.testing.io;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.writeFile(io, .{ .sub_path = "config", .data = "font.size = 99\n" });
    var path_buf: [4096]u8 = undefined;
    const cfg_path = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/config", .{tmp.sub_path});
    if (session.config_path_buffer) |b| allocator.free(b);
    session.config_path_buffer = try allocator.dupe(u8, cfg_path); // 세션 소유 — deinit이 해제

    session.config_dirty_keys.clearRetainingCapacity();
    session.loaded_config.config.font.size = 99;
    session.loaded_config.config.cursor.blink = !(config_mod.Config{}).cursor.blink;
    // 리셋 직전 예약된 변경이 config_dirty_keys 외 컬렉션에 있어도 reset이 전부 폐기하는지(리뷰 #844-followup) —
    // 안 비우면 다음 tick serializeConfig가 takeConfigDirty()=true로 방금 리셋한 파일에 되살린다. 대표로 두 컬렉션에 더미.
    try session.config_removed_keys.append(allocator, "env.STALE");
    try session.config_keybind_unbinds.append(allocator, "cmd+k");
    session.resetAllSettings();
    try std.testing.expectEqual((config_mod.Config{}).font.size, session.loaded_config.config.font.size); // 라이브 기본값
    try std.testing.expectEqual((config_mod.Config{}).cursor.blink, session.loaded_config.config.cursor.blink);
    try std.testing.expect(!session.takeConfigDirty()); // 5개 dirty 컬렉션 전부 비워짐(부분 write-back 예약 없음)
    // config 파일이 기본 상태로 덮어써졌는지(삭제 아님 — 파일 존재 + 안내 주석, 옛 override 사라짐).
    const after = try tmp.dir.readFileAlloc(io, "config", allocator, .limited(4096));
    defer allocator.free(after);
    try std.testing.expect(std.mem.indexOf(u8, after, "Reset to Defaults") != null); // 안내 주석 헤더
    try std.testing.expect(std.mem.indexOf(u8, after, "font.size = 99") == null); // 옛 override 사라짐

    // make_path + replace 계약(리뷰 #844-followup): config 경로의 부모 디렉터리가 없어도(신규 사용자 ~/.config[/maru] 부재)
    // reset이 부모를 재귀 생성하고 헤더를 쓴다. 존재하지 않는 nested/dir 하위로 경로를 바꿔 검증.
    const nested = try std.fmt.bufPrint(&path_buf, ".zig-cache/tmp/{s}/nested/dir/config", .{tmp.sub_path});
    allocator.free(session.config_path_buffer.?);
    session.config_path_buffer = try allocator.dupe(u8, nested);
    session.resetAllSettings();
    const nested_after = tmp.dir.readFileAlloc(io, "nested/dir/config", allocator, .limited(4096)) catch null;
    defer if (nested_after) |na| allocator.free(na);
    try std.testing.expect(nested_after != null); // make_path가 nested/dir를 생성하고 헤더를 씀
    try std.testing.expect(std.mem.indexOf(u8, nested_after.?, "Reset to Defaults") != null);
}

test "테마 프리셋 잠금: 사용자 지정 순환 + 프리셋 활성 시 색·팔레트 잠금 + 프리셋 행 최상단" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    const Preset = config_mod.theme.ThemePreset;
    const n = @typeInfo(Preset).@"enum".fields.len;

    // 프리셋 색 + 사용자 미전환 → 활성(잠금).
    session.loaded_config.config.theme = config_mod.theme.presetColors(.maru);
    session.theme_user_custom = false;
    try std.testing.expect(session.themePresetActive());

    // 마지막 프리셋에서 +1 → "사용자 지정": 색 보존 + theme_user_custom=true + 잠금 해제(색을 안 바꾼다).
    const last: Preset = @enumFromInt(n - 1);
    session.loaded_config.config.theme = config_mod.theme.presetColors(last);
    session.theme_user_custom = false;
    const last_bg = session.loaded_config.config.theme.background;
    session.applyThemePreset(1);
    try std.testing.expect(session.theme_user_custom);
    try std.testing.expectEqualStrings(last_bg, session.loaded_config.config.theme.background);
    try std.testing.expect(!session.themePresetActive());

    // "사용자 지정"에서 +1 → 첫 프리셋(maru) 적용 + 잠금 복귀.
    session.applyThemePreset(1);
    try std.testing.expect(!session.theme_user_custom);
    try std.testing.expectEqual(Preset.maru, AppSession.detectThemePreset(session.loaded_config.config.theme).?);
    try std.testing.expect(session.themePresetActive());

    // 세팅 폼(테마 섹션): 프리셋이 첫 dropdown(최상단)이고, 활성이라 색 행은 전부 disabled.
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const secs = try session.buildSectionList(arena.allocator());
    for (secs, 0..) |s, idx| if (s.section == .theme) {
        session.chrome_host.settings.section = idx;
    };
    const rows = try session.buildSettingsFields(arena.allocator());
    var first_dropdown: ?[]const u8 = null;
    var any_color = false;
    var any_color_enabled = false;
    for (rows) |r| switch (r.kind) {
        .dropdown => if (first_dropdown == null) {
            first_dropdown = r.label;
        },
        .color => {
            any_color = true;
            if (!r.disabled) any_color_enabled = true;
        },
        else => {},
    };
    try std.testing.expectEqualStrings("테마 프리셋", first_dropdown.?); // 프리셋이 최상단 enum
    try std.testing.expect(any_color and !any_color_enabled); // 색 행 존재 + 전부 잠금

    // "사용자 지정"으로 풀면 색 행 활성(편집 가능).
    session.theme_user_custom = true;
    const rows2 = try session.buildSettingsFields(arena.allocator());
    var any_color_enabled2 = false;
    for (rows2) |r| if (r.kind == .color) {
        if (!r.disabled) any_color_enabled2 = true;
    };
    try std.testing.expect(any_color_enabled2);
}

// isWindowDragRegion: 헤더 '빈' 영역(아이콘·검색 아님)만 창 드래그/확대 영역(Swift performDrag·zoom). 아이콘·검색·
// 카드·접힘은 아니다 — 터미널 본문 드래그로 창이 끌려가던 것을 막고(mouseDownCanMoveWindow=false) 헤더만 타이틀바화.
test "isWindowDragRegion: only empty header area drags the window (not icons/search/cards/collapsed)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const cw: f64 = @floatFromInt(session.cell_width_px);
    const icon_y: f64 = @as(f64, @floatFromInt(session.cell_height_px)) * 0.5; // 아이콘 줄(row 0)
    // 헤더 빈 영역(줄0 좌측 = 신호등 영역 옆 빈 공간) → 드래그 영역.
    try std.testing.expect(session.isWindowDragRegion(2 * cw, icon_y));
    // 우측 아이콘(◧/⚙/+) → 드래그 아님(클릭 대상).
    const gear_x: f64 = @as(f64, @floatFromInt(session.sidebar_width_px)) - 3 * cw;
    try std.testing.expect(!session.isWindowDragRegion(gear_x, icon_y));
    // 검색 줄 → 드래그 아님.
    const search_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) * 0.85;
    try std.testing.expect(!session.isWindowDragRegion(2 * cw, search_y));
    // 헤더 아래 카드 영역 → 드래그 아님.
    const card_y: f64 = @as(f64, @floatFromInt(session.sidebar_header_height_px)) + 5;
    try std.testing.expect(!session.isWindowDragRegion(2 * cw, card_y));
    // 터미널 위 타이틀바 띠(y<strip) → 드래그 영역(② cmux식 상단 띠).
    const term_x: f64 = @floatFromInt(session.active_pane_rect.x + 50);
    try std.testing.expect(session.isWindowDragRegion(term_x, @as(f64, @floatFromInt(session.titlebar_strip_px)) * 0.5));
    // 터미널 '본문'(띠 아래 y≥strip) → 드래그 아님(셀 선택).
    try std.testing.expect(!session.isWindowDragRegion(term_x, @as(f64, @floatFromInt(session.titlebar_strip_px)) + 5));
    // 접힘: 전체 폭 타이틀바 띠가 드래그, 단 ◧ 펼치기 버튼 위는 아님(클릭).
    session.toggleSidebarCollapsed();
    const strip_y: f64 = @as(f64, @floatFromInt(session.titlebar_strip_px)) * 0.5;
    try std.testing.expect(session.isWindowDragRegion(2 * cw, strip_y)); // 띠 빈 곳
    const btn = session.collapsedToggleRect().?;
    try std.testing.expect(!session.isWindowDragRegion(@as(f64, @floatFromInt(btn.x)) + 1, strip_y)); // ◧ 버튼 위
    session.toggleSidebarCollapsed(); // 원복
}

// 사이드바 접기 토글: ◧ 클릭/토글 → 폭 0(완전 숨김) + pt 보존, 좌상단 펼치기 버튼 클릭 → 폭 복원. macOS 게이트.
test "sidebar collapse toggle: hides (width 0, pt preserved) and the top-left button expands it" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    const w0 = session.sidebar_width_px;
    const pt0 = session.sidebar_width_pt;
    try std.testing.expect(w0 > 0);
    try std.testing.expect(!session.sidebar_collapsed);
    try std.testing.expect(session.collapsedToggleRect() == null); // 펼침일 땐 버튼 없음

    // 접기(토글) → 폭 0, pt는 보존(복원용), 좌상단 버튼 등장. 검색이 활성이었으면 비활성화(키 갇힘 방지, code-review #3).
    session.sidebar_search_active = true; // 접기 직전 검색 활성 상태 가정
    session.toggleSidebarCollapsed();
    try std.testing.expect(session.sidebar_collapsed);
    try std.testing.expect(!session.sidebar_search_active); // 접으면 검색 비활성(보이지 않는 검색에 키 안 갇힘)
    try std.testing.expectEqual(@as(u32, 0), session.sidebar_width_px);
    try std.testing.expectEqual(pt0, session.sidebar_width_pt); // pt 보존
    try std.testing.expect(session.collapsedToggleRect() != null);
    // 펼치기 버튼 rect 높이 = 타이틀바 띠 전체(cell_h가 아님) — 1.7× 버튼이 띠 하단으로 삐져나간 데드존 방지(code-review #1).
    try std.testing.expectEqual(session.titlebar_strip_px, session.collapsedToggleRect().?.h);

    // 좌상단 펼치기 버튼 안 클릭 → 펼침(폭 복원). 사이드바 폭 0이라 inSidebar=false인데도 별도 경로로 잡힌다.
    const r = session.collapsedToggleRect().?;
    const bx: f64 = @floatFromInt(r.x);
    session.mouse(1, bx + 1, 1, 0, 0);
    try std.testing.expect(!session.sidebar_collapsed);
    try std.testing.expectEqual(w0, session.sidebar_width_px); // 폭 복원

    // 헤더 ◧(toggle_sidebar) 영역 클릭으로도 접힌다(폭이 충분해 헤더가 그려질 때).
    const cw: f64 = @floatFromInt(session.cell_width_px);
    const cols = session.sidebar_width_px / session.cell_width_px;
    if (cols >= 10) {
        const toggle_x: f64 = @as(f64, @floatFromInt(cols - 7)) * cw; // ◧ zone [cols-9, cols-6)
        const toggle_y: f64 = @as(f64, @floatFromInt(session.cell_height_px)) * 0.5;
        try std.testing.expectEqual(chrome.components.sidebar.HeaderRegion.toggle_sidebar, chrome.components.sidebar.headerHit(toggle_x, toggle_y, session.sidebar_width_px, session.cell_width_px, session.cell_height_px, session.sidebar_header_height_px));
        session.mouse(1, toggle_x, toggle_y, 0, 0);
        try std.testing.expect(session.sidebar_collapsed);
    }
}

// 접힘 펼치기 토글(◧) 폴리시: (1) hoverCursor가 토글 위에서 호버 배경 quad를 켜고 밖에서 끈다(접힘 시 사이드바
// 폭 0이라 헤더 호버 경로가 안 타므로 별도 추적), (2) metalFrame이 titlebar_strip_px를 실어 렌더러가 ◧를 띠 안
// 세로 중앙에 정렬(신호등 정렬)할 수 있게 한다. 호버 quad는 distinctive한 fg-반투명 색(packRgbAlpha 0x40)으로 식별.
test "collapsed toggle: hover emits a highlight quad and metalFrame carries titlebar_strip_px" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    session.toggleSidebarCollapsed();
    try std.testing.expect(session.sidebar_collapsed);

    // metalFrame이 띠 높이를 실어 렌더러가 ◧를 띠 안 세로 중앙에 정렬할 수 있다(접힘 띠 = max(cell_h, 30pt) > 0).
    try std.testing.expect(session.titlebar_strip_px > 0);
    try std.testing.expectEqual(session.titlebar_strip_px, session.metalFrame().titlebar_strip_px);

    // 호버 quad를 식별하는 distinctive 색 — 헤더 아이콘 호버와 같은 밝은 fg 반투명(straight-alpha).
    const hover_fill = packRgbAlpha(session.appearance.theme.sidebar_foreground, 0x40);
    const hasHoverQuad = struct {
        fn run(s: *const AppSession, fill: u32) bool {
            for (s.gpu_quads.items) |q| if (q.fill_color0 == fill) return true;
            return false;
        }
    }.run;

    // 클릭 rect는 글리프와 동심이어야 한다 — .m이 ◧를 셀 중심 (col+0.5)·cw 기준 1.7×로 그리므로(maru_fill_cell_quad
    // 중심 확대), rect를 col·cw부터 잡으면 0.5칸 우측으로 치우쳐 글리프 좌측이 안 눌린다(code-review). rect 중심 ==
    // col·cw + cw/2(글리프 중심)인지 고정한다.
    const r = session.collapsedToggleRect().?;
    {
        const cw_i: i32 = @intCast(session.cell_width_px);
        const glyph_center = @as(i32, session.collapsedToggleCol()) * cw_i + @divTrunc(cw_i, 2);
        try std.testing.expectEqual(glyph_center, r.x + @as(i32, @intCast(r.w / 2)));
    }
    // 토글 밖(띠 빈 곳) 호버 → 호버 off, 호버 quad 없음.
    const far_x: f64 = @floatFromInt(r.x + @as(i32, @intCast(r.w)) + 100);
    _ = session.hoverCursor(far_x, 1, 0);
    try std.testing.expect(!session.hovered_collapsed_toggle);
    try std.testing.expect(!hasHoverQuad(session, hover_fill));

    // 토글 중심 호버 → pointingHand(.link) + 호버 on + 호버 quad 방출.
    const cx: f64 = @floatFromInt(r.x + @as(i32, @intCast(r.w / 2)));
    const cy: f64 = @floatFromInt(@as(i32, @intCast(r.h / 2)));
    try std.testing.expectEqual(CursorKind.link, session.hoverCursor(cx, cy, 0));
    try std.testing.expect(session.hovered_collapsed_toggle);
    try std.testing.expect(hasHoverQuad(session, hover_fill));

    // 다시 밖으로 → 호버 off, quad 제거(rebuildSidebar가 다시 비움).
    _ = session.hoverCursor(far_x, 1, 0);
    try std.testing.expect(!session.hovered_collapsed_toggle);
    try std.testing.expect(!hasHoverQuad(session, hover_fill));
}

// 접힘에도 알림 종 유지: 좌상단 띠에 ◧ 오른쪽 종(collapsedBellCol=collapsedToggleCol+3)을 그리고, 그 클릭 rect는
// 종 글리프와 동심·◧ rect와 비겹침이며, 클릭하면 알림 패널이 열린다(접힘 분기 anchor). 드러난-것=클릭되는-것 단일 출처.
test "collapsed notification bell: hit-test rect is concentric with the glyph, clears the ◧ toggle, and opens the panel" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();
    session.window_padding_px = .{};
    _ = try session.resize(session.sidebar_width_px + 800, 600, session.scale_milli);

    try std.testing.expect(session.collapsedNotificationRect() == null); // 펼침일 땐 종 rect 없음(접힘 전제)
    _ = session.pushNotificationHistory("t", "b", 0, true); // 안읽음 1 → 배지 표시(종 좌측)
    session.toggleSidebarCollapsed();
    try std.testing.expect(session.sidebar_collapsed);

    // 종이 ◧ '왼쪽'(펼침과 같은 순서) — collapsedToggleCol = collapsedBellCol + 3(아이콘 간격 단일 출처). 토글↔펼침 swap 방지.
    try std.testing.expectEqual(session.collapsedBellCol() + @as(u16, 3), session.collapsedToggleCol());

    const cw_i: i32 = @intCast(session.cell_width_px);
    const r = session.collapsedNotificationRect().?;
    // rect 높이 = 타이틀바 띠 전체(데드존 방지 — collapsedToggleRect와 같은 규약).
    try std.testing.expectEqual(session.titlebar_strip_px, r.h);
    // 클릭 rect 중심 == 종 글리프 시각 중심 (bell_col+0.5)·cw(렌더러 −0.5칸 px_nudge 반영; (3cw)/2 == cw + cw/2라 홀/짝 cw 무관).
    const bell_center = @as(i32, session.collapsedBellCol()) * cw_i + @divTrunc(cw_i, 2);
    try std.testing.expectEqual(bell_center, r.x + @as(i32, @intCast(r.w / 2)));
    // 종 rect(왼쪽)와 ◧ 토글 rect(오른쪽)는 안 겹친다(클릭 모호성 없음) — 종 우단 ≤ 토글 좌단.
    const t = session.collapsedToggleRect().?;
    try std.testing.expect(t.x >= r.x + @as(i32, @intCast(r.w)));

    // 종 클릭 → 알림 패널 열림(접힘 분기 anchor). 종은 ◧와 별개라 펼치지 않는다(폭 0 유지).
    const cx: f64 = @floatFromInt(r.x + @as(i32, @intCast(r.w / 2)));
    const cy: f64 = @floatFromInt(@as(i32, @intCast(r.h / 2)));
    session.mouse(1, cx, cy, 0, 0);
    try std.testing.expect(session.chrome_host.notifications.open);
    try std.testing.expect(session.sidebar_collapsed); // 종 클릭은 펼치지 않는다(◧와 별개 영역)
}

// window.opacity(F1-1): ResolvedAppearance.window_opacity가 metalFrame.window_opacity_milli(×1000, 0~1000)로 실린다.
// 렌더러가 이 값/1000을 화면 clear color alpha에 곱해 default 배경만 투명해진다(명시적 배경색 셀은 셀 quad라 불변).
test "window.opacity → metalFrame.window_opacity_milli ×1000 (F1-1)" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const session = try allocator.create(AppSession);
    defer allocator.destroy(session);
    try session.init(std.Io.Threaded.global_single_threaded.io(), allocator, .{
        .abi_version = abi_version,
        .cols = 20,
        .rows = 5,
        .queue_capacity = 16,
        .command_kind = @intFromEnum(CommandKind.controlled_smoke),
    });
    defer session.deinit();

    // 기본(불투명) → 1000.
    try std.testing.expectEqual(@as(u32, 1000), session.metalFrame().window_opacity_milli);

    // 0.6 → 600(반올림).
    session.appearance.window_opacity = 0.6;
    try std.testing.expectEqual(@as(u32, 600), session.metalFrame().window_opacity_milli);

    // 0.0(완전 투명) → 0.
